dGNoIHt9DQogICAgfQ0KfQ0KDQpleGl0ICRFeGl0Q29kZQ0K
'@

# -----------------------------------------------------------------------------
# STEP 1: INITIALIZE SCRIPT / APPLICATION DIRECTORY & AUDIT FILE
# -----------------------------------------------------------------------------
$script:appDir = if (-not [string]::IsNullOrEmpty($PSScriptRoot)) {
    $PSScriptRoot
} elseif ($MyInvocation.MyCommand -and $MyInvocation.MyCommand.Path) {
    Split-Path -Parent $MyInvocation.MyCommand.Path
} else {
    [System.AppDomain]::CurrentDomain.BaseDirectory
}
if ([string]::IsNullOrEmpty($script:appDir)) {
    $script:appDir = (Get-Location).Path
}

$script:auditDir = "$env:ProgramData\IncidentResponse-Automator"
$script:auditCsv = Join-Path $script:auditDir "AuditLog.csv"
$canWriteProgramData = $false
try {
    if (-not (Test-Path $script:auditDir)) {
        New-Item -ItemType Directory -Path $script:auditDir -Force -ErrorAction Stop | Out-Null
    }
    if (-not (Test-Path $script:auditCsv)) {
        "Timestamp,Admin,TargetUPN,TargetName,Action,Status,Details" | Out-File -FilePath $script:auditCsv -Encoding utf8 -ErrorAction Stop
    }
    # Verify actual write/append access in case an elevated session created the file previously
    $fsTest = [System.IO.File]::Open($script:auditCsv, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::ReadWrite)
    $fsTest.Close()
    $fsTest.Dispose()
    $canWriteProgramData = $true
} catch {
    $canWriteProgramData = $false
}

if (-not $canWriteProgramData) {
    $script:auditDir = "$env:LOCALAPPDATA\IncidentResponse-Automator"
    try {
        if (-not (Test-Path $script:auditDir)) {
            New-Item -ItemType Directory -Path $script:auditDir -Force -ErrorAction SilentlyContinue | Out-Null
        }
        $script:auditCsv = Join-Path $script:auditDir "AuditLog.csv"
        if (-not (Test-Path $script:auditCsv)) {
            "Timestamp,Admin,TargetUPN,TargetName,Action,Status,Details" | Out-File -FilePath $script:auditCsv -Encoding utf8 -ErrorAction SilentlyContinue
        }
    } catch {}
}
$script:inMemoryAuditLog = [System.Collections.Generic.List[psobject]]::new()

# -----------------------------------------------------------------------------
# STEP 2: DOMAIN AUTO-DETECTION & MULTI-DOMAIN PROFILE ENGINE (AD + GRAPH + GAM)
# -----------------------------------------------------------------------------
$script:BaseDefaultGamCfgDir = if (-not [string]::IsNullOrWhiteSpace($env:GAMCFGDIR)) {
    [Environment]::ExpandEnvironmentVariables($env:GAMCFGDIR)
} elseif (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
    Join-Path $env:USERPROFILE '.gam'
} else {
    ''
}
$script:BaseDefaultGraphDir = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
    Join-Path $env:LOCALAPPDATA 'MicrosoftGraphSetup'
} else {
    Join-Path ([IO.Path]::GetTempPath()) 'MicrosoftGraphSetup'
}
$script:ProfilesRootDir = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
    Join-Path $env:LOCALAPPDATA 'IncidentResponse-Automator\Profiles'
} elseif (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
    Join-Path $env:USERPROFILE '.incident-response\Profiles'
} else {
    Join-Path ([IO.Path]::GetTempPath()) 'IncidentResponse-Automator\Profiles'
}

function Save-LastDomainConnectionSafe {
    param(
        [string]$TargetDomain,
        [string]$TargetServer,
        [string]$AdminUsername
    )
    try {
        if ([string]::IsNullOrWhiteSpace($TargetDomain) -and (-not [string]::IsNullOrWhiteSpace($TargetServer))) {
            $TargetDomain = $TargetServer
        }
        if ([string]::IsNullOrWhiteSpace($TargetServer) -and (-not [string]::IsNullOrWhiteSpace($TargetDomain))) {
            $TargetServer = $TargetDomain
        }

        # Multi-location persistence ensures remembered DC/Domain and Admin Username survive profile resets
        $locations = [System.Collections.Generic.List[string]]::new()
        if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
            $locations.Add((Join-Path $env:LOCALAPPDATA 'IncidentResponse-Automator'))
        }
        if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
            $locations.Add((Join-Path $env:USERPROFILE '.incident-response'))
        }

        # SECURITY ENFORCEMENT: Passwords and credentials are NEVER saved to disk under any circumstances.
        # Only the Domain/DC FQDN and username are retained to streamline analyst reconnects.
        $obj = @{
            TargetDomain  = [string]$TargetDomain
            TargetServer  = [string]$TargetServer
            AdminUsername = [string]$AdminUsername
            LastSavedUtc  = (Get-Date).ToUniversalTime().ToString("o")
        }
        $json = $obj | ConvertTo-Json -Compress

        foreach ($dir in $locations) {
            try {
                if (-not (Test-Path -LiteralPath $dir -PathType Container)) {
                    New-Item -ItemType Directory -Path $dir -Force -ErrorAction SilentlyContinue | Out-Null
                }
                $cfgPath = Join-Path $dir 'LastDomainConnection.json'
                [System.IO.File]::WriteAllText($cfgPath, $json, [System.Text.Encoding]::UTF8)
            } catch {}
        }
    } catch {}
}

function Get-LastDomainConnectionSafe {
    try {
        $paths = [System.Collections.Generic.List[string]]::new()
        if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
            $paths.Add((Join-Path (Join-Path $env:LOCALAPPDATA 'IncidentResponse-Automator') 'LastDomainConnection.json'))
        }
        if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
            $paths.Add((Join-Path (Join-Path $env:USERPROFILE '.incident-response') 'LastDomainConnection.json'))
        }

        foreach ($p in $paths) {
            if (Test-Path -LiteralPath $p -PathType Leaf) {
                try {
                    $raw = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
                    if (-not [string]::IsNullOrWhiteSpace($raw)) {
                        $parsed = $raw | ConvertFrom-Json
                        if ($parsed -and ($parsed.TargetDomain -or $parsed.TargetServer -or $parsed.AdminUsername)) {
                            return $parsed
                        }
                    }
                } catch {}
            }
        }
    } catch {}
    return $null
}

function Get-DiscoveredLocalDomainSafe {
    try {
        $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
        if ($cs -and $cs.PartOfDomain -and -not [string]::IsNullOrEmpty($cs.Domain)) {
            return [string]$cs.Domain
        }
    } catch {}
    try {
        Add-Type -AssemblyName System.DirectoryServices -ErrorAction SilentlyContinue
        $compDomain = [System.DirectoryServices.ActiveDirectory.Domain]::GetComputerDomain()
        if ($compDomain -and $compDomain.Name) {
            return [string]$compDomain.Name
        }
    } catch {}
    if (-not [string]::IsNullOrEmpty($env:USERDNSDOMAIN)) {
        return $env:USERDNSDOMAIN.ToLower()
    }
    try {
        $ipDom = [System.Net.NetworkInformation.IPGlobalProperties]::GetIPGlobalProperties().DomainName
        if (-not [string]::IsNullOrWhiteSpace($ipDom)) {
            return $ipDom.ToLower()
        }
    } catch {}
    return ""
}

function Get-DomainProfilePaths {
    param([Parameter(Mandatory = $true)]$ProfileObj)

    $pidSafe = if ($ProfileObj -and -not [string]::IsNullOrWhiteSpace([string]$ProfileObj.Id)) {
        ([string]$ProfileObj.Id -replace '[^a-zA-Z0-9_-]', '_')
    } else {
        'default'
    }
    $profDir = Join-Path $script:ProfilesRootDir $pidSafe
    $isDef = ($pidSafe -eq 'default') -or ($ProfileObj -and [bool]$ProfileObj.IsDefault)

    $gamDir = if ($ProfileObj -and (-not [string]::IsNullOrWhiteSpace([string]$ProfileObj.GamConfigDir))) {
        [Environment]::ExpandEnvironmentVariables([string]$ProfileObj.GamConfigDir)
    } elseif ($isDef) {
        $script:BaseDefaultGamCfgDir
    } else {
        Join-Path $profDir 'gam'
    }

    $graphDir = if ($ProfileObj -and (-not [string]::IsNullOrWhiteSpace([string]$ProfileObj.GraphSetupDir))) {
        [Environment]::ExpandEnvironmentVariables([string]$ProfileObj.GraphSetupDir)
    } elseif ($isDef) {
        $script:BaseDefaultGraphDir
    } else {
        Join-Path $profDir 'graph'
    }

    $mgDir = Join-Path $profDir 'mg'
    return @{
        ProfileDir = $profDir
        GamDir     = $gamDir
        GraphDir   = $graphDir
        MgDir      = $mgDir
        IsDefault  = $isDef
    }
}

function Get-ActiveGamConfigDir {
    if ($script:activeProfile) {
        $paths = Get-DomainProfilePaths -ProfileObj $script:activeProfile
        if (-not [string]::IsNullOrWhiteSpace($paths.GamDir)) {
            return $paths.GamDir
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($env:GAMCFGDIR)) {
        return [Environment]::ExpandEnvironmentVariables($env:GAMCFGDIR)
    }
    return $script:BaseDefaultGamCfgDir
}

function Get-ActiveGraphSetupDir {
    if ($script:activeProfile) {
        $paths = Get-DomainProfilePaths -ProfileObj $script:activeProfile
        if (-not [string]::IsNullOrWhiteSpace($paths.GraphDir)) {
            return $paths.GraphDir
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($env:IR_GRAPH_SETUP_DIR)) {
        return [Environment]::ExpandEnvironmentVariables($env:IR_GRAPH_SETUP_DIR)
    }
    return $script:BaseDefaultGraphDir
}

function Save-DomainProfilesSafe {
    try {
        if (-not $script:domainProfilesData) { return }
        $locations = [System.Collections.Generic.List[string]]::new()
        if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
            $locations.Add((Join-Path $env:LOCALAPPDATA 'IncidentResponse-Automator'))
        }
        if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
            $locations.Add((Join-Path $env:USERPROFILE '.incident-response'))
        }

        $hasAnyPrimary = $false
        $exportProfiles = @($script:domainProfilesData.Profiles | ForEach-Object {
            if ([bool]$_.IsPrimary) { $hasAnyPrimary = $true }
            [PSCustomObject]@{
                Id                = [string]$_.Id
                Name              = [string]$_.Name
                IsDefault         = [bool]$_.IsDefault
                IsPrimary         = [bool]$_.IsPrimary
                TargetDomain      = [string]$_.TargetDomain
                TargetServer      = [string]$_.TargetServer
                AdminUsername     = [string]$_.AdminUsername
                UseExplicitCreds  = [bool]$_.UseExplicitCreds
                GamConfigDir      = [string]$_.GamConfigDir
                GraphSetupDir     = [string]$_.GraphSetupDir
                GraphAccountHint  = [string]$_.GraphAccountHint
                GraphTenantIdHint = [string]$_.GraphTenantIdHint
                LastUsedUtc       = [string]$_.LastUsedUtc
            }
        })
        $isPrimaryConf = ([bool]$script:domainProfilesData.PrimaryConfigured) -or $hasAnyPrimary
        $script:domainProfilesData.PrimaryConfigured = $isPrimaryConf

        $payload = [PSCustomObject]@{
            SchemaVersion     = 2
            PrimaryConfigured = $isPrimaryConf
            ActiveProfileId   = [string]$script:domainProfilesData.ActiveProfileId
            Profiles          = $exportProfiles
            LastSavedUtc      = (Get-Date).ToUniversalTime().ToString('o')
        }
        $json = $payload | ConvertTo-Json -Depth 5

        foreach ($dir in $locations) {
            try {
                if (-not (Test-Path -LiteralPath $dir -PathType Container)) {
                    New-Item -ItemType Directory -Path $dir -Force -ErrorAction SilentlyContinue | Out-Null
                }
                $cfgPath = Join-Path $dir 'Profiles.json'
                [System.IO.File]::WriteAllText($cfgPath, $json, [System.Text.Encoding]::UTF8)
            } catch {}
        }
    } catch {}
}

function Load-DomainProfilesSafe {
    param(
        [string]$DefaultDomain = "",
        [string]$DefaultServer = "",
        [string]$DefaultAdmin = "",
        [bool]$DefaultUseExplicit = $false
    )

    $paths = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $paths.Add((Join-Path (Join-Path $env:LOCALAPPDATA 'IncidentResponse-Automator') 'Profiles.json'))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
        $paths.Add((Join-Path (Join-Path $env:USERPROFILE '.incident-response') 'Profiles.json'))
    }

    $loaded = $null
    foreach ($p in $paths) {
        if (Test-Path -LiteralPath $p -PathType Leaf) {
            try {
                $raw = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
                if (-not [string]::IsNullOrWhiteSpace($raw)) {
                    $parsed = $raw | ConvertFrom-Json
                    if ($parsed -and $parsed.Profiles -and @($parsed.Profiles).Count -gt 0) {
                        $loaded = $parsed
                        break
                    }
                }
            } catch {}
        }
    }

    $list = [System.Collections.Generic.List[psobject]]::new()
    $anyPrimary = $false
    $loadedPrimaryConf = $false
    if ($loaded -and ($loaded.PSObject.Properties.Name -contains 'PrimaryConfigured')) {
        $loadedPrimaryConf = [bool]$loaded.PrimaryConfigured
    }

    if ($loaded) {
        foreach ($pr in @($loaded.Profiles)) {
            if (-not $pr -or [string]::IsNullOrWhiteSpace([string]$pr.Id)) { continue }
            $isPrim = if ($pr.PSObject.Properties.Name -contains 'IsPrimary') {
                [bool]$pr.IsPrimary
            } elseif ($loadedPrimaryConf -and (([string]$pr.Id -eq 'default') -or [bool]$pr.IsDefault)) {
                $true
            } else {
                $false
            }
            if ($isPrim) { $anyPrimary = $true }
            $profName = if ($pr.Name) { [string]$pr.Name } else { [string]$pr.Id }
            if ($profName -eq 'Default (Primary)' -and (-not $isPrim)) {
                $profName = 'Default Profile'
            }
            $list.Add([PSCustomObject]@{
                Id                = [string]$pr.Id
                Name              = $profName
                IsDefault         = [bool]$pr.IsDefault -or ([string]$pr.Id -eq 'default')
                IsPrimary         = $isPrim
                TargetDomain      = [string]$pr.TargetDomain
                TargetServer      = [string]$pr.TargetServer
                AdminUsername     = [string]$pr.AdminUsername
                UseExplicitCreds  = [bool]$pr.UseExplicitCreds
                GamConfigDir      = [string]$pr.GamConfigDir
                GraphSetupDir     = [string]$pr.GraphSetupDir
                GraphAccountHint  = [string]$pr.GraphAccountHint
                GraphTenantIdHint = [string]$pr.GraphTenantIdHint
                LastUsedUtc       = [string]$pr.LastUsedUtc
            })
        }
    }

    if ($list.Count -eq 0) {
        $initName = if (-not [string]::IsNullOrWhiteSpace($DefaultDomain)) { "Default ($DefaultDomain)" } else { 'Default Profile' }
        $list.Add([PSCustomObject]@{
            Id                = 'default'
            Name              = $initName
            IsDefault         = $true
            IsPrimary         = $false
            TargetDomain      = $DefaultDomain
            TargetServer      = $DefaultServer
            AdminUsername     = $DefaultAdmin
            UseExplicitCreds  = $DefaultUseExplicit
            GamConfigDir      = ''
            GraphSetupDir     = ''
            GraphAccountHint  = ''
            GraphTenantIdHint = ''
            LastUsedUtc       = (Get-Date).ToUniversalTime().ToString('o')
        })
    }

    $activeId = if ($loaded -and (-not [string]::IsNullOrWhiteSpace([string]$loaded.ActiveProfileId))) {
        [string]$loaded.ActiveProfileId
    } else {
        [string]$list[0].Id
    }

    return [PSCustomObject]@{
        SchemaVersion     = 2
        PrimaryConfigured = ($loadedPrimaryConf -or $anyPrimary)
        ActiveProfileId   = $activeId
        Profiles          = $list
    }
}

function Get-PrimaryDomainProfileSafe {
    if (-not $script:domainProfilesData -or -not $script:domainProfilesData.Profiles) { return $null }
    foreach ($pr in $script:domainProfilesData.Profiles) {
        if ([bool]$pr.IsPrimary) {
            return $pr
        }
    }
    return $null
}

function Set-PrimaryDomainProfileSafe {
    param(
        [Parameter(Mandatory = $true)]$TargetProfile,
        [string]$NewName = ""
    )
    if (-not $script:domainProfilesData -or -not $TargetProfile) { return }
    foreach ($pr in $script:domainProfilesData.Profiles) {
        $pr.IsPrimary = ([string]::Equals([string]$pr.Id, [string]$TargetProfile.Id, [StringComparison]::OrdinalIgnoreCase))
    }
    if (-not [string]::IsNullOrWhiteSpace($NewName)) {
        $TargetProfile.Name = $NewName.Trim()
    }
    $script:domainProfilesData.PrimaryConfigured = $true
    Save-DomainProfilesSafe
}

function Get-ProfileByIdSafe {
    param([string]$ProfileId)
    if (-not $script:domainProfilesData -or -not $script:domainProfilesData.Profiles) { return $null }
    foreach ($pr in $script:domainProfilesData.Profiles) {
        if ([string]::Equals([string]$pr.Id, [string]$ProfileId, [StringComparison]::OrdinalIgnoreCase)) {
            return $pr
        }
    }
    return $script:domainProfilesData.Profiles[0]
}

function Save-ActiveGraphSnapshotSafe {
    try {
        if (-not $script:activeProfile -or [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { return }
        $paths = Get-DomainProfilePaths -ProfileObj $script:activeProfile
        $mgCtxSrc = Join-Path $env:USERPROFILE '.mg\MgContext.json'
        if (Test-Path -LiteralPath $mgCtxSrc -PathType Leaf) {
            if (-not (Test-Path -LiteralPath $paths.MgDir -PathType Container)) {
                New-Item -ItemType Directory -Path $paths.MgDir -Force -ErrorAction SilentlyContinue | Out-Null
            }
            $mgCtxDst = Join-Path $paths.MgDir 'MgContext.json'
            Copy-Item -LiteralPath $mgCtxSrc -Destination $mgCtxDst -Force -ErrorAction SilentlyContinue
            try {
                $obj = Get-Content -LiteralPath $mgCtxSrc -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                if ($obj -and (-not [string]::IsNullOrWhiteSpace([string]$obj.Account))) {
                    $script:activeProfile.GraphAccountHint = [string]$obj.Account
                }
                if ($obj -and (-not [string]::IsNullOrWhiteSpace([string]$obj.TenantId))) {
                    $script:activeProfile.GraphTenantIdHint = [string]$obj.TenantId
                }
                Save-DomainProfilesSafe
            } catch {}
        }
    } catch {}
}

function Restore-GraphProfileContextSafe {
    param([Parameter(Mandatory = $true)]$TargetProfile)

    $script:cachedGraphAppToken = $null
    $script:cachedGraphAppTokenExpiry = [datetime]::MinValue
    $script:attemptedSchemaV2Upgrade = $false

    try {
        if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
            Set-MgGraphOption -DisableLoginByWAM $true -ErrorAction SilentlyContinue
        }
        if (Get-Command -Name 'Disconnect-MgGraph' -ErrorAction SilentlyContinue) {
            Disconnect-MgGraph -ErrorAction SilentlyContinue | Out-Null
        }
    } catch {}

    try {
        if ([string]::IsNullOrWhiteSpace($env:USERPROFILE)) { return }
        $mgDirLive = Join-Path $env:USERPROFILE '.mg'
        $mgCtxLive = Join-Path $mgDirLive 'MgContext.json'
        $paths = Get-DomainProfilePaths -ProfileObj $TargetProfile
        $mgCtxSnap = Join-Path $paths.MgDir 'MgContext.json'

        if (Test-Path -LiteralPath $mgCtxSnap -PathType Leaf) {
            if (-not (Test-Path -LiteralPath $mgDirLive -PathType Container)) {
                New-Item -ItemType Directory -Path $mgDirLive -Force -ErrorAction SilentlyContinue | Out-Null
            }
            Copy-Item -LiteralPath $mgCtxSnap -Destination $mgCtxLive -Force -ErrorAction SilentlyContinue

            # Silently re-attach cached MSAL refresh token for this tenant when module is already loaded/available
            try {
                if (Get-Module -Name 'Microsoft.Graph.Authentication') {
                    if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
                        Set-MgGraphOption -DisableLoginByWAM $true -ErrorAction SilentlyContinue
                    }
                    Connect-MgGraph -ContextScope CurrentUser -NoWelcome -ErrorAction SilentlyContinue | Out-Null
                }
            } catch {}
        } else {
            # Prevent another domain profile's MgContext.json from falsely verifying an unconfigured profile
            if (Test-Path -LiteralPath $mgCtxLive -PathType Leaf) {
                Remove-Item -LiteralPath $mgCtxLive -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {}
}

function New-DomainProfileSafe {
    param(
        [Parameter(Mandatory = $true)][string]$ProfileName,
        [switch]$CopyCurrentGamSecrets
    )

    $cleanName = $ProfileName.Trim()
    if ([string]::IsNullOrWhiteSpace($cleanName)) {
        throw "Domain profile name cannot be blank."
    }

    $slug = ($cleanName.ToLowerInvariant() -replace '[^a-z0-9]+', '-').Trim('-')
    if ([string]::IsNullOrWhiteSpace($slug)) { $slug = 'domain' }
    if ($slug.Length -gt 24) { $slug = $slug.Substring(0, 24).Trim('-') }
    $suffix = [Guid]::NewGuid().ToString('N').Substring(0, 4)
    $newId = "dom-$slug-$suffix"

    $profDir = Join-Path $script:ProfilesRootDir $newId
    $gamDir = Join-Path $profDir 'gam'
    $graphDir = Join-Path $profDir 'graph'
    $mgDir = Join-Path $profDir 'mg'

    foreach ($d in @($profDir, $gamDir, $graphDir, $mgDir)) {
        if (-not (Test-Path -LiteralPath $d -PathType Container)) {
            New-Item -ItemType Directory -Path $d -Force -ErrorAction Stop | Out-Null
        }
    }

    if ($CopyCurrentGamSecrets) {
        $srcGamDir = Get-ActiveGamConfigDir
        if ($srcGamDir) {
            $srcSecrets = Join-Path $srcGamDir 'client_secrets.json'
            if (Test-Path -LiteralPath $srcSecrets -PathType Leaf) {
                Copy-Item -LiteralPath $srcSecrets -Destination (Join-Path $gamDir 'client_secrets.json') -Force -ErrorAction SilentlyContinue
            }
        }
    }

    $newObj = [PSCustomObject]@{
        Id                = $newId
        Name              = $cleanName
        IsDefault         = $false
        IsPrimary         = $false
        TargetDomain      = ''
        TargetServer      = ''
        AdminUsername     = ''
        UseExplicitCreds  = $true
        GamConfigDir      = $gamDir
        GraphSetupDir     = $graphDir
        GraphAccountHint  = ''
        GraphTenantIdHint = ''
        LastUsedUtc       = (Get-Date).ToUniversalTime().ToString('o')
    }
    [void]$script:domainProfilesData.Profiles.Add($newObj)
    Save-DomainProfilesSafe
    return $newObj
}

function Get-DomainProfileStatusSummary {
    param([Parameter(Mandatory = $true)]$ProfileObj)

    $paths = Get-DomainProfilePaths -ProfileObj $ProfileObj
    $graphLabel = "Not linked"
    $graphReady = $false

    try {
        $setupLog = Join-Path $paths.GraphDir 'Setup.log'
        $audCfg = Join-Path $paths.GraphDir 'MailboxAuditorApp.json'
        $mgSnap = Join-Path $paths.MgDir 'MgContext.json'
        if (Test-Path -LiteralPath $setupLog -PathType Leaf) {
            $lines = @(Get-Content -LiteralPath $setupLog -ErrorAction SilentlyContinue)
            $raw = $lines -join "`n"
            if ($raw.Contains('Setup completed successfully for')) {
                foreach ($ln in $lines) {
                    $idx = $ln.IndexOf('Authenticated account:')
                    if ($idx -ge 0) {
                        $graphLabel = $ln.Substring($idx + 'Authenticated account:'.Length).Trim()
                        $graphReady = $true
                    }
                }
            }
        }
        if (-not $graphReady -and (Test-Path -LiteralPath $audCfg -PathType Leaf)) {
            $j = Get-Content -LiteralPath $audCfg -Raw -ErrorAction SilentlyContinue | ConvertFrom-Json -ErrorAction SilentlyContinue
            if ($j -and $j.TenantId) {
                $graphLabel = if ($j.Account) { [string]$j.Account } else { "App-Only ($($j.TenantId))" }
                $graphReady = $true
            }
        }
        if (-not $graphReady -and (Test-Path -LiteralPath $mgSnap -PathType Leaf)) {
            $mj = Get-Content -LiteralPath $mgSnap -Raw -ErrorAction SilentlyContinue | ConvertFrom-Json -ErrorAction SilentlyContinue
            if ($mj -and $mj.Account) {
                $graphLabel = [string]$mj.Account
                $graphReady = $true
            }
        }
        if (-not $graphReady -and (-not [string]::IsNullOrWhiteSpace([string]$ProfileObj.GraphAccountHint))) {
            $graphLabel = [string]$ProfileObj.GraphAccountHint
            $graphReady = $true
        }
    } catch {}

    $gamLabel = "Not linked"
    $gamReady = $false
    try {
        if (-not [string]::IsNullOrWhiteSpace($paths.GamDir) -and (Test-Path -LiteralPath $paths.GamDir -PathType Container)) {
            $hasOauth = (Test-Path -LiteralPath (Join-Path $paths.GamDir 'oauth2.txt') -PathType Leaf) -or
                        (Test-Path -LiteralPath (Join-Path $paths.GamDir 'oauth2service.json') -PathType Leaf)
            $hasSec = Test-Path -LiteralPath (Join-Path $paths.GamDir 'client_secrets.json') -PathType Leaf
            $gamCfgPath = Join-Path $paths.GamDir 'gam.cfg'
            $domHint = ""
            if (Test-Path -LiteralPath $gamCfgPath -PathType Leaf) {
                $cfgRaw = Get-Content -LiteralPath $gamCfgPath -Raw -ErrorAction SilentlyContinue
                if ($cfgRaw -match '(?m)^\s*domain\s*=\s*([^\r\n#]+)') {
                    $domHint = $Matches[1].Trim()
                }
            }
            if ($hasOauth) {
                $gamReady = $true
                $gamLabel = if ($domHint) { "Ready ($domHint)" } else { "OAuth Ready" }
            } elseif ($hasSec) {
                $gamLabel = "Project linked (OAuth pending)"
            }
        }
    } catch {}

    return @{
        GraphReady = $graphReady
        GraphLabel = $graphLabel
        GamReady   = $gamReady
        GamLabel   = $gamLabel
    }
}

$script:detectedDomain = ""
$script:isDomainJoined = $false
$script:useExplicitCreds = $false
$script:adCredential = $null
$script:savedDomainConfig = Get-LastDomainConnectionSafe

$localDomainFound = Get-DiscoveredLocalDomainSafe
if (-not [string]::IsNullOrWhiteSpace($localDomainFound)) {
    $script:detectedDomain = $localDomainFound
    $script:isDomainJoined = $true
} else {
    $script:detectedDomain = "Not Domain-Joined (Workgroup)"
    $script:isDomainJoined = $false
}

$defaultTargetDomain = if ($script:isDomainJoined) {
    $script:detectedDomain
} elseif ($script:savedDomainConfig -and (-not [string]::IsNullOrWhiteSpace([string]$script:savedDomainConfig.TargetDomain))) {
    [string]$script:savedDomainConfig.TargetDomain
} elseif ($script:savedDomainConfig -and (-not [string]::IsNullOrWhiteSpace([string]$script:savedDomainConfig.TargetServer))) {
    [string]$script:savedDomainConfig.TargetServer
} else {
    ""
}

$defaultTargetServer = if ($script:isDomainJoined) {
    $script:detectedDomain
} elseif ($script:savedDomainConfig -and (-not [string]::IsNullOrWhiteSpace([string]$script:savedDomainConfig.TargetServer))) {
    [string]$script:savedDomainConfig.TargetServer
} elseif ($defaultTargetDomain) {
    $defaultTargetDomain
} else {
    ""
}

$defaultAdminAccount = if ($script:savedDomainConfig -and (-not [string]::IsNullOrWhiteSpace([string]$script:savedDomainConfig.AdminUsername))) {
    [string]$script:savedDomainConfig.AdminUsername
} elseif (-not [string]::IsNullOrEmpty($env:USERDNSDOMAIN)) {
    "$env:USERNAME@$($env:USERDNSDOMAIN.ToLower())"
} elseif (-not [string]::IsNullOrEmpty($env:USERNAME)) {
    $env:USERNAME
} else {
    "admin"
}
$defaultUseExplicit = ($script:savedDomainConfig -and (-not [string]::IsNullOrWhiteSpace([string]$script:savedDomainConfig.AdminUsername)) -and (-not $script:isDomainJoined))

$script:domainProfilesData = Load-DomainProfilesSafe -DefaultDomain $defaultTargetDomain -DefaultServer $defaultTargetServer -DefaultAdmin $defaultAdminAccount -DefaultUseExplicit ([bool]$defaultUseExplicit)
$script:activeProfile = Get-ProfileByIdSafe -ProfileId $script:domainProfilesData.ActiveProfileId
if (-not $script:activeProfile) {
    $script:activeProfile = $script:domainProfilesData.Profiles[0]
}
$script:domainProfilesData.ActiveProfileId = $script:activeProfile.Id

# Seed startup GAM & Graph environment for the active profile (no-op for single-domain Default users)
$activePathsInit = Get-DomainProfilePaths -ProfileObj $script:activeProfile
foreach ($ensureDir in @($activePathsInit.ProfileDir, $activePathsInit.MgDir)) {
    try {
        if (-not (Test-Path -LiteralPath $ensureDir -PathType Container)) {
            New-Item -ItemType Directory -Path $ensureDir -Force -ErrorAction SilentlyContinue | Out-Null
        }
    } catch {}
}
if (-not $activePathsInit.IsDefault) {
    foreach ($ensureCustomDir in @($activePathsInit.GamDir, $activePathsInit.GraphDir)) {
        try {
            if (-not (Test-Path -LiteralPath $ensureCustomDir -PathType Container)) {
                New-Item -ItemType Directory -Path $ensureCustomDir -Force -ErrorAction SilentlyContinue | Out-Null
            }
        } catch {}
    }
    $env:GAMCFGDIR = $activePathsInit.GamDir
    $env:IR_GRAPH_SETUP_DIR = $activePathsInit.GraphDir
    # Ensure startup .mg\MgContext.json reflects the active profile (not a leftover session from another domain)
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
        $liveMgCtx = Join-Path $env:USERPROFILE '.mg\MgContext.json'
        $snapMgCtx = Join-Path $activePathsInit.MgDir 'MgContext.json'
        if (Test-Path -LiteralPath $snapMgCtx -PathType Leaf) {
            $liveMgDir = Split-Path -Parent $liveMgCtx
            if (-not (Test-Path -LiteralPath $liveMgDir -PathType Container)) {
                New-Item -ItemType Directory -Path $liveMgDir -Force -ErrorAction SilentlyContinue | Out-Null
            }
            Copy-Item -LiteralPath $snapMgCtx -Destination $liveMgCtx -Force -ErrorAction SilentlyContinue
        } elseif (Test-Path -LiteralPath $liveMgCtx -PathType Leaf) {
            Remove-Item -LiteralPath $liveMgCtx -Force -ErrorAction SilentlyContinue
        }
    }
} else {
    # Ensure Default profile retains a snapshot if user already has an existing .mg\MgContext.json
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
        $liveMgCtx = Join-Path $env:USERPROFILE '.mg\MgContext.json'
        $snapMgCtx = Join-Path $activePathsInit.MgDir 'MgContext.json'
        if ((Test-Path -LiteralPath $liveMgCtx -PathType Leaf) -and (-not (Test-Path -LiteralPath $snapMgCtx -PathType Leaf))) {
            Copy-Item -LiteralPath $liveMgCtx -Destination $snapMgCtx -Force -ErrorAction SilentlyContinue
        }
    }
}

$script:targetDomain = if (-not [string]::IsNullOrWhiteSpace([string]$script:activeProfile.TargetDomain)) {
    [string]$script:activeProfile.TargetDomain
} elseif ($activePathsInit.IsDefault -and $script:isDomainJoined) {
    $script:detectedDomain
} else {
    $defaultTargetDomain
}

$script:targetServer = if (-not [string]::IsNullOrWhiteSpace([string]$script:activeProfile.TargetServer)) {
    [string]$script:activeProfile.TargetServer
} elseif (-not [string]::IsNullOrWhiteSpace($script:targetDomain)) {
    $script:targetDomain
} else {
    $defaultTargetServer
}

$script:adminAccount = if (-not [string]::IsNullOrWhiteSpace([string]$script:activeProfile.AdminUsername)) {
    [string]$script:activeProfile.AdminUsername
} else {
    $defaultAdminAccount
}

if ([bool]$script:activeProfile.UseExplicitCreds) {
    $script:useExplicitCreds = $true
} elseif ($activePathsInit.IsDefault -and $defaultUseExplicit) {
    $script:useExplicitCreds = $true
}

function Test-ValidADServer {
    param([string]$ServerName)
    return (-not [string]::IsNullOrWhiteSpace($ServerName)) -and
           ($ServerName -ne "Not Domain-Joined (Workgroup)") -and
           ($ServerName -ne "WORKGROUP")
}

function Get-ADInvocationParams {
    $p = @{}
    if (Test-ValidADServer $script:targetServer) {
        $p['Server'] = $script:targetServer
    }
    if ($script:adCredential) {
        $p['Credential'] = $script:adCredential
    }
    return $p
}

# -----------------------------------------------------------------------------
# REAL INTEGRATION VERIFICATION ENGINE (AD, MICROSOFT GRAPH, GOOGLE GAM7)
# -----------------------------------------------------------------------------
function Get-ADDomainSafe {
    param([string]$Server, [System.Management.Automation.PSCredential]$Cred)

    $hasServer = Test-ValidADServer $Server
    if (-not $script:isDomainJoined -and -not $hasServer) {
        throw "Workstation is not domain-joined and no target Domain Controller or domain name was specified."
    }

    if (Get-Command Get-ADDomain -ErrorAction SilentlyContinue) {
        $p = @{}
        if ($hasServer) { $p['Server'] = $Server }
        if ($Cred) { $p['Credential'] = $Cred }
        $rootDse = Get-ADRootDSE @p -ErrorAction Stop
        $domObj = Get-ADDomain @p -ErrorAction Stop
        if (-not $rootDse -or -not $rootDse.defaultNamingContext -or -not $domObj -or -not $domObj.DNSRoot) {
            throw "Domain Controller did not return a valid RootDSE or DNSRoot."
        }
        return [string]$domObj.DNSRoot
    }

    # Native .NET System.DirectoryServices live RootDSE bind verification (No RSAT required)
    $target = if ($hasServer) { $Server } else { $script:detectedDomain }
    if (-not (Test-ValidADServer $target)) {
        throw "No valid Active Directory domain or Domain Controller specified."
    }
    $ldapPath = "LDAP://$target/RootDSE"
    $de = if ($Cred) {
        New-Object System.DirectoryServices.DirectoryEntry($ldapPath, $Cred.UserName, $Cred.GetNetworkCredential().Password)
    } else {
        New-Object System.DirectoryServices.DirectoryEntry($ldapPath)
    }
    try {
        $nc = $de.Properties["defaultNamingContext"].Value
        if ([string]::IsNullOrWhiteSpace([string]$nc)) {
            throw "LDAP RootDSE handshake did not return a defaultNamingContext."
        }
        $resolvedDomain = ($nc -split ',' | Where-Object { $_ -match '^DC=' } | ForEach-Object { $_ -replace '^DC=','' }) -join '.'
        if (-not [string]::IsNullOrWhiteSpace($resolvedDomain)) {
            return $resolvedDomain
        }
        return $target
    } finally {
        if ($de) {
            try { $de.Dispose() } catch {}
        }
    }
}

function Invoke-VerifyAD {
    param([switch]$QuickStartup)

    $result = @{
        Verified      = $false
        Engine        = "None"
        Domain        = ""
        RootDSE       = ""
        RsatInstalled = $false
        Error         = ""
    }

    if (-not $QuickStartup) {
        $result.RsatInstalled = [bool](Get-Module -ListAvailable -Name ActiveDirectory)
        if ($result.RsatInstalled) {
            try { Import-Module ActiveDirectory -ErrorAction SilentlyContinue } catch {}
        }
    } else {
        $result.RsatInstalled = [bool](Get-Command Get-ADRootDSE -ErrorAction SilentlyContinue)
    }

    $hasServer = Test-ValidADServer $script:targetServer
    $isCustomProfile = $script:activeProfile -and (-not [bool]$script:activeProfile.IsDefault) -and ([string]$script:activeProfile.Id -ne 'default')
    if ((-not $script:isDomainJoined -or $isCustomProfile) -and (-not $hasServer)) {
        $result.Error = "No target Active Directory domain or DC configured for this profile. Click 'Switch Domain / Profile'."
        return $result
    }
    if ($script:useExplicitCreds -and (-not $script:adCredential)) {
        $result.Error = "Password authentication required for '$($script:targetServer)'. Click 'Switch Domain / Profile' to connect."
        return $result
    }

    try {
        if ((-not $QuickStartup) -and (Get-Command Get-ADRootDSE -ErrorAction SilentlyContinue)) {
            $p = Get-ADInvocationParams
            $rootDse = Get-ADRootDSE @p -ErrorAction Stop
            $domObj = Get-ADDomain @p -ErrorAction Stop
            if (-not $rootDse -or -not $rootDse.defaultNamingContext -or -not $domObj -or -not $domObj.DNSRoot) {
                throw "Domain Controller did not return a valid RootDSE or DNSRoot."
            }
            $result.Verified = $true
            $result.Engine = "ActiveDirectory RSAT PowerShell Module"
            $result.Domain = [string]$domObj.DNSRoot
            $result.RootDSE = [string]$rootDse.defaultNamingContext
            return $result
        }

        $target = if ($hasServer) { $script:targetServer } else { $script:detectedDomain }
        $ldapPath = "LDAP://$target/RootDSE"
        $de = if ($script:adCredential) {
            New-Object System.DirectoryServices.DirectoryEntry($ldapPath, $script:adCredential.UserName, $script:adCredential.GetNetworkCredential().Password)
        } else {
            New-Object System.DirectoryServices.DirectoryEntry($ldapPath)
        }
        try {
            $nc = $de.Properties["defaultNamingContext"].Value
            if ([string]::IsNullOrWhiteSpace([string]$nc)) {
                throw "LDAP RootDSE bind did not return defaultNamingContext."
            }
            $dnsHost = [string]$de.Properties["dnsHostName"].Value
            $resolvedDom = ($nc -split ',' | Where-Object { $_ -match '^DC=' } | ForEach-Object { $_ -replace '^DC=','' }) -join '.'
            $result.Verified = $true
            $result.Engine = "Native .NET System.DirectoryServices (LDAP)"
            $result.Domain = if ($resolvedDom) { $resolvedDom } else { $target }
            $result.RootDSE = if ($dnsHost) { "$nc ($dnsHost)" } else { [string]$nc }
            return $result
        } finally {
            if ($de) { $de.Dispose() }
        }
    } catch {
        $errMsg = $_.Exception.Message
        if ($errMsg -match 'Logon failure|unknown user name|bad password|credentials|access is denied' -or (-not $script:isDomainJoined -and -not $script:adCredential)) {
            $result.Error = "Target DC '$($script:targetServer)' requires admin authentication. Click 'Switch Domain / Profile' to enter password."
        } else {
            $result.Error = $errMsg
        }
        return $result
    }
}

function Get-SetupGraphLogState {
    $state = @{
        Verified = $false
        Account  = ""
        TenantId = ""
        Scopes   = @('User.RevokeSessions.All', 'Directory.AccessAsUser.All')
    }
    try {
        $logDir = Get-ActiveGraphSetupDir
        if (-not [string]::IsNullOrWhiteSpace($logDir)) {
            $logPath = Join-Path $logDir 'Setup.log'
            if (Test-Path -LiteralPath $logPath -PathType Leaf) {
                $lines = @(Get-Content -LiteralPath $logPath -ErrorAction Stop)
                $rawLog = $lines -join "`n"
                if ($rawLog -and
                    $rawLog.Contains('All requested delegated permissions are present.') -and
                    $rawLog.Contains('Setup completed successfully for') -and
                    (-not $rawLog.Contains('[Error]'))) {
                    $acctVal = ""
                    $tenantVal = ""
                    foreach ($ln in $lines) {
                        $idxAcct = $ln.IndexOf('Authenticated account:')
                        if ($idxAcct -ge 0) {
                            $acctVal = $ln.Substring($idxAcct + 'Authenticated account:'.Length).Trim()
                        }
                        $idxTen = $ln.IndexOf('Tenant ID:')
                        if ($idxTen -ge 0) {
                            $tenantVal = $ln.Substring($idxTen + 'Tenant ID:'.Length).Trim()
                        }
                    }
                    if ((-not [string]::IsNullOrWhiteSpace($acctVal)) -and (-not [string]::IsNullOrWhiteSpace($tenantVal))) {
                        $state.Verified = $true
                        $state.Account  = $acctVal
                        $state.TenantId = $tenantVal
                        return $state
                    }
                }
            }

            # Check for M365 Mailbox Auditor App configuration
            $auditorCfg = Join-Path $logDir 'MailboxAuditorApp.json'
            if (Test-Path -LiteralPath $auditorCfg -PathType Leaf) {
                try {
                    $appJson = Get-Content -LiteralPath $auditorCfg -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                    if ($appJson -and (-not [string]::IsNullOrWhiteSpace([string]$appJson.TenantId)) -and (-not [string]::IsNullOrWhiteSpace([string]$appJson.ClientId))) {
                        $state.Verified = $true
                        $state.TenantId = [string]$appJson.TenantId
                        $state.Account  = if ($appJson.AppName) { [string]$appJson.AppName } else { "Tenant Service Principal ($($appJson.ClientId))" }
                        return $state
                    }
                } catch {}
            }
        }
        if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
            $mgDir = Join-Path $env:USERPROFILE '.mg'
            $mgContextJson = Join-Path $mgDir 'MgContext.json'
            if (Test-Path -LiteralPath $mgContextJson -PathType Leaf) {
                $jsonObj = Get-Content -LiteralPath $mgContextJson -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                if ($jsonObj -and (-not [string]::IsNullOrWhiteSpace([string]$jsonObj.Account)) -and (-not [string]::IsNullOrWhiteSpace([string]$jsonObj.TenantId))) {
                    $state.Verified = $true
                    $state.Account  = [string]$jsonObj.Account
                    $state.TenantId = [string]$jsonObj.TenantId
                    if ($jsonObj.Scopes) {
                        $state.Scopes = @($jsonObj.Scopes)
                    }
                    return $state
                }
            }
        }
    } catch {}
    return $state
}

function Invoke-VerifyGraph {
    param([switch]$LiveApiCheck, [switch]$QuickStartup)

    $result = @{
        Verified         = $false
        ModulesInstalled = $false
        Account          = ""
        TenantId         = ""
        Scopes           = @()
        Error            = ""
    }

    $requiredModules = @(
        'Microsoft.Graph.Authentication',
        'Microsoft.Graph.Users.Actions'
    )
    $missingModules = @()
    foreach ($mod in $requiredModules) {
        if (-not (Get-Module -ListAvailable -Name $mod)) {
            $missingModules += $mod
        }
    }
    if ($missingModules.Count -gt 0) {
        $result.Error = "Missing Microsoft Graph modules: $($missingModules -join ', '). Open Tab 2 ('Health & Diagnostics') and click '1. Setup Microsoft Graph'."
        return $result
    }
    $result.ModulesInstalled = $true

    try {
        Import-Module -Name 'Microsoft.Graph.Authentication' -DisableNameChecking -ErrorAction Stop
        if (-not $QuickStartup) {
            Import-Module -Name 'Microsoft.Graph.Users.Actions' -DisableNameChecking -ErrorAction Stop
            foreach ($cmdName in @('Connect-MgGraph', 'Disconnect-MgGraph', 'Get-MgContext', 'Revoke-MgUserSignInSession')) {
                if (-not (Get-Command -Name $cmdName -ErrorAction SilentlyContinue)) {
                    throw "Required Microsoft Graph command unavailable: $cmdName"
                }
            }
        }

        try {
            if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
                Set-MgGraphOption -DisableLoginByWAM $true -ErrorAction SilentlyContinue
            }
        } catch {}

        $requiredScopes = @('User.RevokeSessions.All', 'Directory.AccessAsUser.All')
        $mgContextPath = if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { Join-Path $env:USERPROFILE '.mg\MgContext.json' } else { "" }
        $hasMgCacheFile = (-not [string]::IsNullOrWhiteSpace($mgContextPath)) -and (Test-Path -LiteralPath $mgContextPath -PathType Leaf)

        $ctx = Get-MgContext -ErrorAction SilentlyContinue
        if ((-not $QuickStartup) -and (-not $ctx -or [string]::IsNullOrWhiteSpace([string]$ctx.Account)) -and $hasMgCacheFile) {
            try {
                Connect-MgGraph -ContextScope CurrentUser -NoWelcome -ErrorAction SilentlyContinue
                $ctx = Get-MgContext -ErrorAction SilentlyContinue
            } catch {}
        }

        if ($ctx -and (-not [string]::IsNullOrWhiteSpace([string]$ctx.Account)) -and (-not [string]::IsNullOrWhiteSpace([string]$ctx.TenantId))) {
            $grantedScopes = @($ctx.Scopes)
            $missingScopes = @()
            foreach ($reqScope in $requiredScopes) {
                $found = $false
                foreach ($granted in $grantedScopes) {
                    if ([string]::Equals([string]$granted, [string]$reqScope, [StringComparison]::OrdinalIgnoreCase)) {
                        $found = $true
                        break
                    }
                }
                if (-not $found) {
                    $missingScopes += $reqScope
                }
            }
            if ($missingScopes.Count -gt 0) {
                throw "Signed-in account $($ctx.Account) is missing required Graph permissions: $($missingScopes -join ', ')."
            }

            $result.Verified = $true
            $result.Account  = [string]$ctx.Account
            $result.TenantId = [string]$ctx.TenantId
            $result.Scopes   = $grantedScopes
            return $result
        }

        # On Windows PowerShell 5.1, Connect-MgGraph inside Setup-MicrosoftGraph.bat runs in a separate
        # child process and writes verified state to %LOCALAPPDATA%\MicrosoftGraphSetup\Setup.log
        $setupState = Get-SetupGraphLogState
        if ($setupState.Verified) {
            $result.Verified = $true
            $result.Account  = if ($ctx -and (-not [string]::IsNullOrWhiteSpace([string]$ctx.Account))) { [string]$ctx.Account } else { [string]$setupState.Account }
            $result.TenantId = if ($ctx -and (-not [string]::IsNullOrWhiteSpace([string]$ctx.TenantId))) { [string]$ctx.TenantId } else { [string]$setupState.TenantId }
            $result.Scopes   = if ($ctx -and $ctx.Scopes) { @($ctx.Scopes) } else { @($setupState.Scopes) }
            return $result
        }

        throw "Microsoft Graph is not signed in. Open Tab 1 ('1. Setup') and click '1. Setup Microsoft Graph'."
    } catch {
        $result.Error = $_.Exception.Message
        return $result
    }
}

function Test-RoutableCloudAddress {
    param([string]$Address)
    if ([string]::IsNullOrWhiteSpace($Address)) { return $false }
    $trimmed = $Address.Trim()
    $atIdx = $trimmed.IndexOf('@')
    if ($atIdx -le 0 -or $atIdx -ge ($trimmed.Length - 3)) { return $false }
    $domainPart = $trimmed.Substring($atIdx + 1).ToLowerInvariant()
    if (-not $domainPart.Contains('.')) { return $false }
    foreach ($nonRoutable in @('.local', '.internal', '.lan', '.corp', '.home', '.priv', '.intranet')) {
        if ($domainPart.EndsWith($nonRoutable)) {
            return $false
        }
    }
    return $true
}

function Resolve-UserCloudIdentities {
    param(
        [string]$SamAccountName,
        [string]$UserPrincipalName,
        [string]$Mail,
        [string[]]$ProxyAddresses
    )

    $primarySmtp = ""
    $secondarySmtps = [System.Collections.Generic.List[string]]::new()
    if ($ProxyAddresses) {
        foreach ($pa in $ProxyAddresses) {
            if ([string]::IsNullOrWhiteSpace($pa)) { continue }
            $paTrim = $pa.Trim()
            if ($paTrim.StartsWith("SMTP:", [StringComparison]::Ordinal)) {
                $addr = $paTrim.Substring(5).Trim()
                if (-not [string]::IsNullOrWhiteSpace($addr) -and [string]::IsNullOrWhiteSpace($primarySmtp)) {
                    $primarySmtp = $addr
                }
            } elseif ($paTrim.StartsWith("smtp:", [StringComparison]::OrdinalIgnoreCase)) {
                $addr = $paTrim.Substring(5).Trim()
                if (-not [string]::IsNullOrWhiteSpace($addr)) {
                    $secondarySmtps.Add($addr)
                }
            }
        }
    }

    $resolvedMail = if (Test-RoutableCloudAddress $Mail) {
        $Mail.Trim()
    } elseif (Test-RoutableCloudAddress $primarySmtp) {
        $primarySmtp
    } elseif (-not [string]::IsNullOrWhiteSpace($Mail)) {
        $Mail.Trim()
    } elseif (-not [string]::IsNullOrWhiteSpace($primarySmtp)) {
        $primarySmtp
    } else {
        ""
    }

    # Build prioritized candidate list for Graph and GAM7
    $routableList = [System.Collections.Generic.List[string]]::new()
    $fallbackList = [System.Collections.Generic.List[string]]::new()

    foreach ($cand in @($UserPrincipalName, $resolvedMail, $primarySmtp) + $secondarySmtps.ToArray()) {
        if ([string]::IsNullOrWhiteSpace($cand)) { continue }
        $c = $cand.Trim()
        if (Test-RoutableCloudAddress $c) {
            $exists = $false
            foreach ($item in $routableList) {
                if ([string]::Equals($item, $c, [StringComparison]::OrdinalIgnoreCase)) { $exists = $true; break }
            }
            if (-not $exists) { $routableList.Add($c) }
        } else {
            $exists = $false
            foreach ($item in $fallbackList) {
                if ([string]::Equals($item, $c, [StringComparison]::OrdinalIgnoreCase)) { $exists = $true; break }
            }
            if (-not $exists) { $fallbackList.Add($c) }
        }
    }

    $allCandidates = [System.Collections.Generic.List[string]]::new()
    foreach ($r in $routableList) { $allCandidates.Add($r) }
    foreach ($f in $fallbackList) { $allCandidates.Add($f) }

    # Graph prefers routable UPN first, then routable Mail; GAM prefers routable Mail first, then routable UPN
    $graphId = if (Test-RoutableCloudAddress $UserPrincipalName) {
        $UserPrincipalName.Trim()
    } elseif (Test-RoutableCloudAddress $resolvedMail) {
        $resolvedMail
    } elseif ($allCandidates.Count -gt 0) {
        $allCandidates[0]
    } else {
        $UserPrincipalName
    }

    $gamId = if (Test-RoutableCloudAddress $resolvedMail) {
        $resolvedMail
    } elseif (Test-RoutableCloudAddress $UserPrincipalName) {
        $UserPrincipalName.Trim()
    } elseif ($allCandidates.Count -gt 0) {
        $allCandidates[0]
    } else {
        $UserPrincipalName
    }

    return @{
        Mail            = $resolvedMail
        PrimarySmtp     = $primarySmtp
        GraphTargetId   = $graphId
        GamTargetId     = $gamId
        CloudCandidates = $allCandidates.ToArray()
    }
}

function Ensure-MgGraphSessionActive {
    param(
        [string[]]$RequiredScopes = @()
    )

    $prevSyncCtx = [System.Threading.SynchronizationContext]::Current
    try {
        [System.Threading.SynchronizationContext]::SetSynchronizationContext($null)
        Import-Module -Name 'Microsoft.Graph.Authentication' -DisableNameChecking -ErrorAction Stop
        Import-Module -Name 'Microsoft.Graph.Users.Actions' -DisableNameChecking -ErrorAction SilentlyContinue

        # Prevent Windows WAM (Web Account Manager) from auto-selecting the user's primary daily Windows account
        # instead of the cached delegated Admin account in MSAL.
        try {
            if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
                Set-MgGraphOption -DisableLoginByWAM $true -ErrorAction SilentlyContinue
            }
        } catch {}

        $defaultScopes = @(
            'User.RevokeSessions.All'
            'Directory.AccessAsUser.All'
            'User.ReadWrite.All'
            'UserAuthenticationMethod.ReadWrite.All'
            'MailboxSettings.ReadWrite'
            'Mail.ReadWrite'
            'AuditLog.Read.All'
            'IdentityRiskEvent.Read.All'
        )
        foreach ($reqScope in @($RequiredScopes)) {
            if (-not [string]::IsNullOrWhiteSpace($reqScope) -and ($defaultScopes -notcontains $reqScope)) {
                $defaultScopes += $reqScope
            }
        }

        $mgContextPath = if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { Join-Path $env:USERPROFILE '.mg\MgContext.json' } else { "" }
        $hasMgCacheFile = (-not [string]::IsNullOrWhiteSpace($mgContextPath)) -and (Test-Path -LiteralPath $mgContextPath -PathType Leaf)

        # Step 1: Check existing in-process context
        $ctx = Get-MgContext -ErrorAction SilentlyContinue

        # Step 2: Attempt silent reconnection to CurrentUser MSAL cache only when MgContext.json exists for this user
        if ((-not $ctx -or [string]::IsNullOrWhiteSpace([string]$ctx.Account)) -and $hasMgCacheFile) {
            try {
                Connect-MgGraph -ContextScope CurrentUser -NoWelcome -ErrorAction SilentlyContinue
                $ctx = Get-MgContext -ErrorAction SilentlyContinue
            } catch {}
        }

        # Step 3: Check if required scopes are satisfied
        $missingRequired = $false
        if ($ctx -and $RequiredScopes -and $RequiredScopes.Count -gt 0) {
            $granted = @($ctx.Scopes)
            foreach ($rs in $RequiredScopes) {
                $hasScope = $false
                foreach ($g in $granted) {
                    if ([string]::Equals([string]$g, [string]$rs, [StringComparison]::OrdinalIgnoreCase)) {
                        $hasScope = $true
                        break
                    }
                }
                if (-not $hasScope) {
                    $missingRequired = $true
                    break
                }
            }
        }

        # Step 4: If still not connected or missing required scopes, use dedicated Device-Code console
        # so multi-account admins can paste the code into an Admin browser profile (never auto-SSO primary Windows account via WAM)
        if (-not $ctx -or [string]::IsNullOrWhiteSpace([string]$ctx.Account) -or $missingRequired) {
            Write-AppLog "Connecting Microsoft Graph session via device-code authentication..." "INFO"

            $authPs1 = Join-Path ([IO.Path]::GetTempPath()) ("IRGraphAuth_" + [Guid]::NewGuid().ToString("N").Substring(0, 8) + ".ps1")
            try {
                $scopeStr = ($defaultScopes -join ',')
                $authScript = @"
`$ErrorActionPreference = 'Stop'
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host '  MICROSOFT GRAPH AUTHENTICATION - INCIDENT RESPONSE' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host 'Copy the device code and open the sign-in URL in a browser signed into your ADMIN account.' -ForegroundColor Yellow
try {
    Import-Module Microsoft.Graph.Authentication -DisableNameChecking -ErrorAction Stop
    if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
        Set-MgGraphOption -DisableLoginByWAM `$true -ErrorAction SilentlyContinue
    }
    Connect-MgGraph -Scopes ('$scopeStr' -split ',') -ContextScope CurrentUser -UseDeviceAuthentication -NoWelcome -ErrorAction Stop
    Write-Host 'Graph session connected and cached successfully!' -ForegroundColor Green
    Start-Sleep -Seconds 1
} catch {
    Write-Host "Authentication error: `$(`$_.Exception.Message)" -ForegroundColor Red
    Start-Sleep -Seconds 3
}
"@
                Set-Content -LiteralPath $authPs1 -Value $authScript -Encoding UTF8 -Force
                $psExeAuth = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
                if (-not (Test-Path -LiteralPath $psExeAuth)) { $psExeAuth = "powershell.exe" }
                $null = Start-Process -FilePath $psExeAuth -ArgumentList @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$authPs1`"") -Wait -PassThru -WindowStyle Normal

                # Re-attach parent process to the newly updated CurrentUser token cache (WAM disabled)
                if (Test-Path -LiteralPath $mgContextPath -PathType Leaf) {
                    Connect-MgGraph -ContextScope CurrentUser -NoWelcome -ErrorAction SilentlyContinue
                    Save-ActiveGraphSnapshotSafe
                }
                $ctx = Get-MgContext -ErrorAction SilentlyContinue
            } catch {} finally {
                if (Test-Path -LiteralPath $authPs1) {
                    Remove-Item -LiteralPath $authPs1 -Force -ErrorAction SilentlyContinue
                }
            }

            if (-not $ctx -or [string]::IsNullOrWhiteSpace([string]$ctx.Account)) {
                $ctx = Get-MgContext -ErrorAction SilentlyContinue
                if (-not $ctx -or [string]::IsNullOrWhiteSpace([string]$ctx.Account)) {
                    throw "Microsoft Graph authentication did not complete. Please sign in via Tab 1 ('1. Setup') -> '1. Setup Microsoft Graph'."
                }
            }
        }
        return $ctx
    } finally {
        [System.Threading.SynchronizationContext]::SetSynchronizationContext($prevSyncCtx)
    }
}

function Invoke-RevokeMgUserSignInSessionSafe {
    param(
        [Parameter(Mandatory = $true)][string]$UserPrincipalName,
        [string[]]$CandidateIds = @(),
        [string]$SamAccountName = ""
    )

    $setupDir = Get-ActiveGraphSetupDir
    $hasAppConfig = Test-Path -LiteralPath (Join-Path $setupDir 'MailboxAuditorApp.json')
    if ($hasAppConfig) {
        [void](Upgrade-GraphMailboxAuditorAppRolesIfNeededSafe)
    }

    # Only ensure delegated Graph session upfront if App-Only MailboxAuditorApp.json is not configured
    if (-not $hasAppConfig) {
        try {
            [void](Ensure-MgGraphSessionActive -RequiredScopes @('User.RevokeSessions.All'))
        } catch {
            Write-AppLog "Microsoft Graph session notice: $($_.Exception.Message)" "WARN"
        }
    }

    $tryList = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($UserPrincipalName)) {
        $tryList.Add($UserPrincipalName.Trim())
    }
    if ($CandidateIds) {
        foreach ($id in $CandidateIds) {
            if ([string]::IsNullOrWhiteSpace($id)) { continue }
            $cleanId = $id.Trim()
            $already = $false
            foreach ($existing in $tryList) {
                if ([string]::Equals($existing, $cleanId, [StringComparison]::OrdinalIgnoreCase)) { $already = $true; break }
            }
            if (-not $already) { $tryList.Add($cleanId) }
        }
    }

    $lastError = $null
    $matchedUserId = $null

    foreach ($candidate in $tryList) {
        # 1. If App-Only MailboxAuditor is configured, attempt non-blocking Graph Application REST
        if ($hasAppConfig) {
            try {
                $enc = [Uri]::EscapeDataString($candidate)
                $revokeResp = Invoke-GraphMailboxRestSafe -Method POST -Uri "https://graph.microsoft.com/v1.0/users/$enc/revokeSignInSessions" -BodyJson "{}"
                if ($null -ne $revokeResp -and $revokeResp.PSObject.Properties['value'] -and (-not $revokeResp.value)) {
                    throw "Microsoft Graph returned value=False for revokeSignInSessions on '$candidate'."
                }
                $matchedUserId = $candidate
                break
            } catch {
                $lastError = $_
            }
        }

        # 2. Delegated fallback via Microsoft.Graph.Users.Actions (primary path for standard delegated administrators)
        try {
            Import-Module -Name 'Microsoft.Graph.Users.Actions' -DisableNameChecking -ErrorAction SilentlyContinue
            $delRes = Revoke-MgUserSignInSession -UserId $candidate -ErrorAction Stop
            if ($null -ne $delRes -and $delRes.PSObject.Properties['Value'] -and (-not $delRes.Value)) {
                throw "Microsoft Graph returned Value=False for Revoke-MgUserSignInSession on '$candidate'."
            }
            $matchedUserId = $candidate
            break
        } catch {
            $lastError = $_
        }
    }

    # Fallback: Resolve user via Resolve-GraphUserObjectSafe by mail, userPrincipalName, or onPremisesSamAccountName
    if (-not $matchedUserId) {
        try {
            $resolvedUser = Resolve-GraphUserObjectSafe -PrimaryId $UserPrincipalName -CandidateIds $CandidateIds -SamAccountName $SamAccountName
            $resolvedGraphUpn = if ($resolvedUser.userPrincipalName) { [string]$resolvedUser.userPrincipalName } else { [string]$resolvedUser.id }
            $encResolved = [Uri]::EscapeDataString($resolvedGraphUpn)

            # Try App REST if configured
            $revokedSafe = $false
            if ($hasAppConfig) {
                try {
                    $revokeResp2 = Invoke-GraphMailboxRestSafe -Method POST -Uri "https://graph.microsoft.com/v1.0/users/$encResolved/revokeSignInSessions" -BodyJson "{}"
                    if ($null -ne $revokeResp2 -and $revokeResp2.PSObject.Properties['value'] -and (-not $revokeResp2.value)) {
                        throw "Microsoft Graph returned value=False for '$resolvedGraphUpn'."
                    }
                    $revokedSafe = $true
                } catch {
                    $lastError = $_
                }
            }

            if (-not $revokedSafe) {
                # Try delegated
                Import-Module -Name 'Microsoft.Graph.Users.Actions' -DisableNameChecking -ErrorAction SilentlyContinue
                $delRes2 = Revoke-MgUserSignInSession -UserId $resolvedGraphUpn -ErrorAction Stop
                if ($null -ne $delRes2 -and $delRes2.PSObject.Properties['Value'] -and (-not $delRes2.Value)) {
                    throw "Microsoft Graph returned Value=False for '$resolvedGraphUpn'."
                }
            }
            $matchedUserId = $resolvedGraphUpn
        } catch {
            $lastError = $_
        }
    }

    if (-not $matchedUserId) {
        if ($lastError) {
            throw "Failed to match or revoke user in Microsoft Graph (tried: $($tryList -join ', ')): $($lastError.Exception.Message)"
        }
        throw "User '$UserPrincipalName' was not found in Microsoft Entra ID."
    }

    if ($script:revokedGraphUsers) {
        [void]$script:revokedGraphUsers.Add($matchedUserId)
        if (-not [string]::IsNullOrWhiteSpace($UserPrincipalName)) { [void]$script:revokedGraphUsers.Add($UserPrincipalName) }
        if (-not [string]::IsNullOrWhiteSpace($SamAccountName)) { [void]$script:revokedGraphUsers.Add($SamAccountName) }
        foreach ($c in $tryList) {
            if (-not [string]::IsNullOrWhiteSpace($c)) { [void]$script:revokedGraphUsers.Add($c) }
        }
    }

    $ctx = Get-MgContext -ErrorAction SilentlyContinue
    $ctxAcct = if ($ctx -and $ctx.Account) { [string]$ctx.Account } else { "" }
    $ctxTenant = if ($ctx -and $ctx.TenantId) { [string]$ctx.TenantId } else { "" }
    return @{
        Context       = @{ Account = $ctxAcct; TenantId = $ctxTenant }
        MatchedUserId = $matchedUserId
    }
}

$script:revokedGraphUsers = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
$script:revokedGamUsers = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)

function Invoke-GamCliSafe {
    param(
        [Parameter(Mandatory = $true)][string]$GamExecutable,
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [int]$TimeoutSeconds = 15
    )

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $GamExecutable
    # Escape arguments safely for ProcessStartInfo
    $escapedArgs = @($Arguments | ForEach-Object {
        if ($_ -match '\s|"') { "`"$($_ -replace '"', '\"')`"" } else { $_ }
    }) -join ' '
    $psi.Arguments = $escapedArgs
    $psi.UseShellExecute = $false
    $activeGamDir = Get-ActiveGamConfigDir
    if (-not [string]::IsNullOrWhiteSpace($activeGamDir)) {
        $psi.EnvironmentVariables['GAMCFGDIR'] = $activeGamDir
    }
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true

    $stdout = ""
    $stderr = ""
    $exitCode = 1
    $timedOut = $false
    try {
        $proc = [System.Diagnostics.Process]::Start($psi)
        $outTask = $proc.StandardOutput.ReadToEndAsync()
        $errTask = $proc.StandardError.ReadToEndAsync()
        $waitMs = [Math]::Max(2000, ($TimeoutSeconds * 1000))
        if (-not $proc.WaitForExit($waitMs)) {
            $timedOut = $true
            try { $proc.Kill() } catch {}
        } else {
            $proc.WaitForExit()
        }
        try { $stdout = [string]$outTask.GetAwaiter().GetResult() } catch {}
        try { $stderr = [string]$errTask.GetAwaiter().GetResult() } catch {}
        $exitCode = if ($timedOut) { 124 } else { $proc.ExitCode }
    } catch {
        $stderr = $_.Exception.Message
    }

    # Filter benign GAM config warnings about optional oauth2service.json when running interactive/OAuth commands
    $cleanStderrLines = @($stderr -split "`r?`n" | Where-Object {
        $_ -and ($_ -notmatch 'WARNING:\s*Config File:.*oauth2service\.json,\s*Not Found')
    })
    $cleanStdoutLines = @($stdout -split "`r?`n" | Where-Object {
        $_ -and ($_ -notmatch 'WARNING:\s*Config File:.*oauth2service\.json,\s*Not Found')
    })
    $cleanOut = ($cleanStdoutLines -join [System.Environment]::NewLine).Trim()
    $cleanErr = ($cleanStderrLines -join [System.Environment]::NewLine).Trim()
    if ($timedOut) {
        $cleanErr = ("GAM command timed out after $TimeoutSeconds seconds. " + $cleanErr).Trim()
    }

    return @{
        ExitCode = $exitCode
        TimedOut = $timedOut
        Output   = $cleanOut
        StdError = $cleanErr
        Combined = ("$cleanOut`n$cleanErr").Trim()
    }
}

function Invoke-GamUserSignoutSafe {
    param(
        [Parameter(Mandatory = $true)][string]$GamExecutable,
        [Parameter(Mandatory = $true)][string]$PrimaryTarget,
        [string[]]$CandidateIds = @()
    )

    $tryList = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($PrimaryTarget) -and $PrimaryTarget.Contains('@')) {
        $tryList.Add($PrimaryTarget.Trim())
    }
    if ($CandidateIds) {
        foreach ($id in $CandidateIds) {
            if ([string]::IsNullOrWhiteSpace($id)) { continue }
            $cleanId = $id.Trim()
            if (-not $cleanId.Contains('@')) { continue }
            $already = $false
            foreach ($existing in $tryList) {
                if ([string]::Equals($existing, $cleanId, [StringComparison]::OrdinalIgnoreCase)) { $already = $true; break }
            }
            if (-not $already) { $tryList.Add($cleanId) }
        }
    }

    if ($tryList.Count -eq 0 -and (-not [string]::IsNullOrWhiteSpace($PrimaryTarget))) {
        $tryList.Add($PrimaryTarget.Trim())
    }

    $lastOutput = ""
    $lastExit = 1
    foreach ($candidate in $tryList) {
        # Use Invoke-GamCliSafe to avoid PowerShell treating GAM informational stderr lines as NativeCommandError
        $cliRes = Invoke-GamCliSafe -GamExecutable $GamExecutable -Arguments @('user', $candidate, 'signout') -TimeoutSeconds 15
        $gamExit = $cliRes.ExitCode
        $gamOut = if ($cliRes.Output) { $cliRes.Output } else { $cliRes.Combined }

        # Exit code 0 or explicit 'Signed Out' string indicates success
        if ($gamExit -eq 0 -or $gamOut -match 'Signed Out') {
            [void]$script:revokedGamUsers.Add($candidate)
            if (-not [string]::IsNullOrWhiteSpace($PrimaryTarget)) { [void]$script:revokedGamUsers.Add($PrimaryTarget) }
            foreach ($c in $tryList) {
                if (-not [string]::IsNullOrWhiteSpace($c)) { [void]$script:revokedGamUsers.Add($c) }
            }
            return @{
                MatchedUserId = $candidate
                Output        = $gamOut
            }
        }
        $lastOutput = $cliRes.Combined
        $lastExit = $gamExit
    }

    throw "GAM signout failed (tried: $($tryList -join ', '); exit code $lastExit): $lastOutput"
}

function Get-UserActiveSessionTelemetry {
    param($UserObj)

    $telemetry = @{
        GraphStatus = "Not Linked (Tab 1 Setup)"
        GraphSub    = "Check Tab 1 to link Graph"
        GraphMatch  = ""
        GamStatus   = "Not Linked (Tab 1 Setup)"
        GamSub      = "Check Tab 1 to link GAM7"
        GamMatch    = ""
    }
    if (-not $UserObj) { return $telemetry }

    $candidates = @()
    if ($UserObj.CloudCandidates -and $UserObj.CloudCandidates.Count -gt 0) {
        $candidates = @($UserObj.CloudCandidates)
    } else {
        $candidates = @($UserObj.UserPrincipalName, $UserObj.Mail) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    }

    $allUserKeys = [System.Collections.Generic.List[string]]::new()
    $seedKeys = @($UserObj.SamAccountName, $UserObj.UserPrincipalName, $UserObj.Mail, $UserObj.GraphTargetId, $UserObj.GamTargetId)
    foreach ($sk in $seedKeys) {
        if (-not [string]::IsNullOrWhiteSpace($sk)) {
            $t = ([string]$sk).Trim()
            if (-not $allUserKeys.Contains($t)) { $allUserKeys.Add($t) }
        }
    }
    if ($candidates) {
        foreach ($ck in $candidates) {
            if (-not [string]::IsNullOrWhiteSpace($ck)) {
                $t = ([string]$ck).Trim()
                if (-not $allUserKeys.Contains($t)) { $allUserKeys.Add($t) }
            }
        }
    }

    # 1. Check Microsoft 365 / Entra ID session & account state
    $graphCheck = Invoke-VerifyGraph -QuickStartup
    if ($graphCheck.Verified) {
        $graphTarget = if ($UserObj.GraphTargetId) { $UserObj.GraphTargetId } else { $UserObj.UserPrincipalName }
        $telemetry.GraphMatch = $graphTarget
        $wasGraphRevokedInSession = $false
        foreach ($k in $allUserKeys) {
            if ($script:revokedGraphUsers.Contains($k)) { $wasGraphRevokedInSession = $true; break }
        }

        $auditorCfgPath = Join-Path (Get-ActiveGraphSetupDir) 'MailboxAuditorApp.json'
        if (Test-Path -LiteralPath $auditorCfgPath) {
            $foundGraphUser = $null
            foreach ($cand in (@($graphTarget) + $candidates)) {
                if ([string]::IsNullOrWhiteSpace($cand)) { continue }
                try {
                    $encoded = [Uri]::EscapeDataString($cand.Trim())
                    $uri = "https://graph.microsoft.com/v1.0/users/$encoded`?`$select=id,userPrincipalName,mail,accountEnabled,signInSessionsValidFromDateTime"
                    $resp = Invoke-GraphMailboxRestSafe -Method GET -Uri $uri -TimeoutSec 5
                    if ($resp -and ($resp.userPrincipalName -or $resp.id)) {
                        $foundGraphUser = $resp
                        break
                    }
                } catch {}
            }
            if ($foundGraphUser) {
                $matchedUpn = if ($foundGraphUser.userPrincipalName) { [string]$foundGraphUser.userPrincipalName } else { $graphTarget }
                $telemetry.GraphMatch = $matchedUpn
                if ($script:revokedGraphUsers.Contains($matchedUpn)) { $wasGraphRevokedInSession = $true }
                $isAcctEnabled = if ($null -ne $foundGraphUser.accountEnabled) { [bool]$foundGraphUser.accountEnabled } else { $true }

                if (-not $isAcctEnabled) {
                    $telemetry.GraphStatus = "Sign-In Blocked"
                    $telemetry.GraphSub    = "Account Suspended / Disabled"
                } elseif ($wasGraphRevokedInSession) {
                    $telemetry.GraphStatus = "Sessions Revoked"
                    $telemetry.GraphSub    = "Login Capable (Not Blocked)"
                } elseif ($foundGraphUser.signInSessionsValidFromDateTime) {
                    try {
                        $validFrom = ([DateTime]$foundGraphUser.signInSessionsValidFromDateTime).ToLocalTime()
                        if (((Get-Date) - $validFrom).TotalHours -lt 4) {
                            $telemetry.GraphStatus = "Sessions Revoked"
                            $telemetry.GraphSub    = "Login Capable (Revoked $($validFrom.ToString('HH:mm')))"
                        } else {
                            $telemetry.GraphStatus = "Login Capable (Active)"
                            $telemetry.GraphSub    = "Sign-In Enabled & Active"
                        }
                    } catch {
                        $telemetry.GraphStatus = "Login Capable (Active)"
                        $telemetry.GraphSub    = "Sign-In Enabled & Active"
                    }
                } else {
                    $telemetry.GraphStatus = "Login Capable (Active)"
                    $telemetry.GraphSub    = "Sign-In Enabled & Active"
                }
            } else {
                if ($wasGraphRevokedInSession) {
                    $telemetry.GraphStatus = "Sessions Revoked"
                    $telemetry.GraphSub    = "Login Capable (Not Blocked)"
                } else {
                    $telemetry.GraphStatus = "Login Capable (Active)"
                    $telemetry.GraphSub    = "Sign-In Enabled & Active"
                }
            }
        } else {
            if ($wasGraphRevokedInSession) {
                $telemetry.GraphStatus = "Sessions Revoked"
                $telemetry.GraphSub    = "Login Capable (Not Blocked)"
            } else {
                $telemetry.GraphStatus = "Login Capable (Active)"
                $telemetry.GraphSub    = "Sign-In Enabled & Active"
            }
        }
    }

    # 2. Check Google Workspace (GAM7) session & account state
    $gamCheck = Invoke-VerifyGAM -QuickStartup
    if ($gamCheck.Verified -and $gamCheck.Executable) {
        $gamExe = $gamCheck.Executable
        $gamTarget = if ($UserObj.GamTargetId) { $UserObj.GamTargetId } else { $UserObj.UserPrincipalName }
        $telemetry.GamMatch = $gamTarget
        $wasGamRevokedInSession = $false
        foreach ($k in $allUserKeys) {
            if ($script:revokedGamUsers.Contains($k)) { $wasGamRevokedInSession = $true; break }
        }

        $matchedGam = $null
        $gamInfoOut = ""
        try {
            $gamTryList = [System.Collections.Generic.List[string]]::new()
            foreach ($c in (@($gamTarget) + $candidates)) {
                if ([string]::IsNullOrWhiteSpace($c) -or (-not $c.Contains('@'))) { continue }
                $ct = $c.Trim()
                $dup = $false
                foreach ($ex in $gamTryList) {
                    if ([string]::Equals($ex, $ct, [StringComparison]::OrdinalIgnoreCase)) { $dup = $true; break }
                }
                if (-not $dup) { $gamTryList.Add($ct) }
            }
            foreach ($cand in $gamTryList) {
                $cliInfo = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('info', 'user', $cand, 'noaliases', 'nogroups', 'nolicenses') -TimeoutSeconds 10
                if ($cliInfo.ExitCode -eq 0 -and $cliInfo.Output) {
                    $matchedGam = $cand
                    $gamInfoOut = $cliInfo.Output
                    break
                }
            }
        } catch {}

        if ($matchedGam) {
            $telemetry.GamMatch = $matchedGam
            if ($script:revokedGamUsers.Contains($matchedGam)) { $wasGamRevokedInSession = $true }
            $isSuspended = $gamInfoOut -match 'Account Suspended:\s*True'
            if ($isSuspended) {
                $telemetry.GamStatus = "Sign-In Blocked"
                $telemetry.GamSub    = "Account Suspended / Disabled"
            } elseif ($wasGamRevokedInSession) {
                $telemetry.GamStatus = "Sessions Revoked"
                $telemetry.GamSub    = "Login Capable (Not Blocked)"
            } else {
                $telemetry.GamStatus = "Login Capable (Active)"
                $telemetry.GamSub    = "Sign-In Enabled & Active"
            }
        } else {
            if ($wasGamRevokedInSession) {
                $telemetry.GamStatus = "Sessions Revoked"
                $telemetry.GamSub    = "Login Capable (Not Blocked)"
            } else {
                $telemetry.GamStatus = "Login Capable (Active)"
                $telemetry.GamSub    = "Sign-In Enabled & Active"
            }
        }
    }

    return $telemetry
}

function Resolve-GamExecutable {
    $machinePath = [Environment]::GetEnvironmentVariable('Path', 'Machine')
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    $combinedEntries = (($userPath + ';' + $machinePath + ';' + $env:Path) -split ';') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }

    $candidates = [System.Collections.Generic.List[string]]::new()
    foreach ($entry in $combinedEntries) {
        try {
            $expanded = [Environment]::ExpandEnvironmentVariables($entry.Trim().Trim('"')).TrimEnd('\')
            if ($expanded) {
                $candidates.Add((Join-Path $expanded 'gam.exe'))
            }
        } catch {}
    }

    $localAppData = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $env:LOCALAPPDATA
    } else {
        [Environment]::GetFolderPath([Environment+SpecialFolder]::LocalApplicationData)
    }

    foreach ($dir in @(
        (Join-Path $localAppData 'Programs\GAM7'),
        (Join-Path $localAppData 'GAM7'),
        (Join-Path $localAppData 'GAM'),
        'C:\GAM7',
        'C:\GAM',
        (Join-Path $env:USERPROFILE 'gam'),
        'C:\GAMADV-XTD3'
    )) {
        if ($dir) {
            $candidates.Add((Join-Path $dir 'gam.exe'))
        }
    }

    foreach ($candidate in ($candidates | Select-Object -Unique)) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            $dirName = Split-Path -Parent $candidate
            if (($env:Path -split ';') -notcontains $dirName) {
                $env:Path = "$dirName;$env:Path"
            }
            return $candidate
        }
    }
    return $null
}

function Invoke-VerifyGAM {
    param([switch]$QuickStartup)

    $result = @{
        Verified      = $false
        Installed     = $false
        Executable    = ""
        Version       = "Unknown"
        OAuthVerified = $false
        Error         = ""
    }

    $gamExe = Resolve-GamExecutable
    if (-not $gamExe) {
        $result.Error = "gam.exe was not found in PATH or %LOCALAPPDATA%\Programs\GAM7. Open Tab 1 ('1. Setup') and click '2. Setup Google GAM7'."
        return $result
    }
    $result.Installed = $true
    $result.Executable = $gamExe

    try {
        $verCli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('version', 'simple') -TimeoutSeconds 10
        $verOutput = $verCli.Combined
        $verExit = $verCli.ExitCode

        if ($verExit -ne 0) {
            throw "GAM version check failed (exit code $verExit): $($verOutput.Trim())"
        }
        $verMatch = [regex]::Match($verOutput, '\d+\.\d+\.\d+')
        if (-not $verMatch.Success) {
            throw "GAM executable ran, but version could not be parsed: $($verOutput.Trim())"
        }
        $result.Version = $verMatch.Value

        $gamDir = Split-Path -Parent $gamExe
        $cfgDir = Get-ActiveGamConfigDir
        $isCustomGamProfile = (-not [string]::IsNullOrWhiteSpace($script:BaseDefaultGamCfgDir)) -and
                              (-not [string]::IsNullOrWhiteSpace($cfgDir)) -and
                              ($cfgDir.TrimEnd('\') -ine $script:BaseDefaultGamCfgDir.TrimEnd('\'))

        # Check for GAM7 credentials (client_secrets.json, oauth2service.json, or oauth2.txt)
        $hasClientSecrets = (Test-Path -LiteralPath (Join-Path $cfgDir 'client_secrets.json') -PathType Leaf) -or
                            ((-not $isCustomGamProfile) -and (Test-Path -LiteralPath (Join-Path $gamDir 'client_secrets.json') -PathType Leaf))
        $hasServiceAccount = (Test-Path -LiteralPath (Join-Path $cfgDir 'oauth2service.json') -PathType Leaf) -or
                             ((-not $isCustomGamProfile) -and (Test-Path -LiteralPath (Join-Path $gamDir 'oauth2service.json') -PathType Leaf))
        $hasOauthFile = (Test-Path -LiteralPath (Join-Path $cfgDir 'oauth2.txt') -PathType Leaf) -or
                        ((-not $isCustomGamProfile) -and (Test-Path -LiteralPath (Join-Path $gamDir 'oauth2.txt') -PathType Leaf))

        if (-not ($hasClientSecrets -or $hasServiceAccount -or $hasOauthFile)) {
            throw "GAM $($result.Version) is installed at $gamExe, but Google Cloud credentials for this profile ($cfgDir) were not found. Open Tab 1 ('1. Setup') and click '2. Setup Google GAM7'."
        }

        # Check gam.cfg to ensure domain is actually configured (not unconfigured placeholder)
        $cfgFile = Join-Path $cfgDir 'gam.cfg'
        if (Test-Path -LiteralPath $cfgFile -PathType Leaf) {
            try {
                $cfgContent = Get-Content -LiteralPath $cfgFile -Raw -ErrorAction SilentlyContinue
                if ($cfgContent -match 'customer_id\s*=\s*my_customer' -and $cfgContent -match 'domain\s*=\s*\r?\n') {
                    throw "GAM $($result.Version) installed, but Google Workspace domain is not yet configured in gam.cfg. Click '2. Setup Google GAM7' to complete setup."
                }
            } catch {}
        }

        if ($QuickStartup) {
            $result.OAuthVerified = $true
            $result.Verified = $true
            return $result
        }

        $oauthCli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('oauth', 'verify') -TimeoutSeconds 12
        $oauthExit = $oauthCli.ExitCode

        if ($oauthExit -ne 0) {
            throw "GAM $($result.Version) is installed at $gamExe, but Google OAuth verification failed (exit code $oauthExit). Click '2. Setup Google GAM7' to re-authenticate."
        }

        $result.OAuthVerified = $true
        $result.Verified = $true
        return $result
    } catch {
        $result.Error = $_.Exception.Message
        return $result
    }
}

function Invoke-SetupBatchScript {
    param(
        [Parameter(Mandatory = $true)][string]$FileName,
        [Parameter(Mandatory = $true)][string]$Base64Payload,
        [switch]$Elevate
    )

    $targetBat = $null
    if (-not [string]::IsNullOrEmpty($script:appDir)) {
        $candidate = Join-Path $script:appDir $FileName
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            $targetBat = $candidate
        }
    }

    $isTemp = $false
    if (-not $targetBat) {
        $targetBat = Join-Path ([IO.Path]::GetTempPath()) $FileName
        $cleanB64 = ($Base64Payload -replace '\s+', '')
        $bytes = [Convert]::FromBase64String($cleanB64)
        [IO.File]::WriteAllBytes($targetBat, $bytes)
        $isTemp = $true
    }

    try {
        $activeGamDir = Get-ActiveGamConfigDir
        if (-not [string]::IsNullOrWhiteSpace($activeGamDir)) {
            $env:GAMCFGDIR = $activeGamDir
        }
        $activeGraphDir = Get-ActiveGraphSetupDir
        if (-not [string]::IsNullOrWhiteSpace($activeGraphDir)) {
            $env:IR_GRAPH_SETUP_DIR = $activeGraphDir
        }
        $startParams = @{
            FilePath     = "cmd.exe"
            ArgumentList = @('/c', "`"$targetBat`"")
            WindowStyle  = 'Normal'
            Wait         = $true
            PassThru     = $true
        }
        if ($Elevate) {
            $startParams['Verb'] = 'RunAs'
        }
        $proc = Start-Process @startParams
        return $proc.ExitCode
    } finally {
        if ($isTemp -and $targetBat -and (Test-Path -LiteralPath $targetBat)) {
            Remove-Item -LiteralPath $targetBat -Force -ErrorAction SilentlyContinue
        }
    }
}

# -----------------------------------------------------------------------------
# SAFE ACTIVE DIRECTORY OPERATIONS (RSAT + Native .NET System.DirectoryServices)
# -----------------------------------------------------------------------------
function Get-DomainControllersListSafe {
    param([string]$PreferredServer = "")

    $dcList = [System.Collections.Generic.List[string]]::new()
    $seen = @{
    }

    $addDc = {
        param([string]$HostName)
        if ([string]::IsNullOrWhiteSpace($HostName)) { return }
        $clean = $HostName.Trim()
        $key = $clean.ToLowerInvariant()
        if (-not $seen.ContainsKey($key)) {
            $seen[$key] = $true
            $dcList.Add($clean)
        }
    }

    if (Test-ValidADServer $PreferredServer) {
        & $addDc $PreferredServer
    }

    # Discover all Domain Controllers via .NET DirectoryServices (putting PDC Emulator first)
    try {
        $dom = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()
        if ($dom) {
            if ($dom.PdcRoleOwner -and (-not [string]::IsNullOrWhiteSpace([string]$dom.PdcRoleOwner.Name))) {
                & $addDc ([string]$dom.PdcRoleOwner.Name)
            }
            if ($dom.DomainControllers) {
                foreach ($dc in $dom.DomainControllers) {
                    if ($dc -and (-not [string]::IsNullOrWhiteSpace([string]$dc.Name))) {
                        & $addDc ([string]$dc.Name)
                    }
                }
            }
        }
    } catch {}

    # Fallback: If RSAT Get-ADDomainController is available and list is still empty/single
    if ($dcList.Count -le 1 -and (Get-Command Get-ADDomainController -ErrorAction SilentlyContinue)) {
        try {
            $p = @{ Filter = '*' }
            if (Test-ValidADServer $PreferredServer) { $p['Server'] = $PreferredServer }
            if ($script:adCredential) { $p['Credential'] = $script:adCredential }
            $adDcs = @(Get-ADDomainController @p -ErrorAction SilentlyContinue)
            foreach ($adc in $adDcs) {
                if ($adc -and (-not [string]::IsNullOrWhiteSpace([string]$adc.HostName))) {
                    & $addDc ([string]$adc.HostName)
                }
            }
        } catch {}
    }

    return $dcList.ToArray()
}

function Get-MultiDCUserNonReplicatedTelemetrySafe {
    param(
        [Parameter(Mandatory = $true)][string]$SamAccountName,
        [string]$Server = "",
        [System.Management.Automation.PSCredential]$Cred = $null
    )

    $result = @{
        QueriedDCs            = @()
        LatestLogonDateTime   = $null
        LatestLogonDisplay    = "Never / Unknown"
        LatestLogonDC         = ""
        TotalBadPwdCount      = 0
        LatestBadPasswordTime = $null
        LatestBadPasswordDC   = ""
        PerDCBadPasswords     = @()
        IsLockedOutAnyDC      = $false
    }

    if ([string]::IsNullOrWhiteSpace($SamAccountName)) { return $result }

    $dcs = @(Get-DomainControllersListSafe -PreferredServer $Server)
    if ($dcs.Count -eq 0) {
        if (Test-ValidADServer $script:targetDomain) {
            $dcs = @($script:targetDomain)
        } else {
            return $result
        }
    }

    $queried = [System.Collections.Generic.List[string]]::new()
    $badEvents = [System.Collections.Generic.List[psobject]]::new()
    $seenBadKeys = @{}
    $safeSam = $SamAccountName.Replace("\", "\5c").Replace("*", "\2a").Replace("(", "\28").Replace(")", "\29")

    # Cap to first 8 DCs with a 1.2s per-DC timeout so multi-DC telemetry always finishes in < 3 seconds
    foreach ($dc in ($dcs | Select-Object -First 8)) {
        $entry = $null
        $searcher = $null
        try {
            $path = "LDAP://$dc"
            $entry = if ($Cred) {
                New-Object System.DirectoryServices.DirectoryEntry($path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
            } else {
                New-Object System.DirectoryServices.DirectoryEntry($path)
            }
            $searcher = New-Object System.DirectoryServices.DirectorySearcher($entry)
            $searcher.Filter = "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$safeSam))"
            $searcher.ServerTimeLimit = [TimeSpan]::FromSeconds(2)
            $searcher.ClientTimeout = [TimeSpan]::FromSeconds(2)
            [void]$searcher.PropertiesToLoad.AddRange(@("lastlogon", "lastlogontimestamp", "badpwdcount", "badpasswordtime", "lockouttime"))

            $one = $searcher.FindOne()
            if ($one -and $one.Properties) {
                $shortDc = ($dc -split '\.')[0]
                $queried.Add($shortDc)
                $props = $one.Properties

                # Check non-replicated lastLogon AND replicated lastLogonTimestamp on this DC
                $dcBestLogon = $null
                foreach ($attrName in @("lastlogon", "lastlogontimestamp")) {
                    if ($props[$attrName] -and $props[$attrName].Count -gt 0) {
                        $ticks = [int64]$props[$attrName][0]
                        if ($ticks -gt 0) {
                            try {
                                $dt = [DateTime]::FromFileTime($ticks)
                                if ($dt.Year -gt 1990 -and ($null -eq $dcBestLogon -or $dt -gt $dcBestLogon)) {
                                    $dcBestLogon = $dt
                                }
                            } catch {}
                        }
                    }
                }
                if ($null -ne $dcBestLogon) {
                    if ($null -eq $result.LatestLogonDateTime -or $dcBestLogon -gt $result.LatestLogonDateTime) {
                        $result.LatestLogonDateTime = $dcBestLogon
                        $result.LatestLogonDC = $shortDc
                        $result.LatestLogonDisplay = "$($dcBestLogon.ToString('yyyy-MM-dd HH:mm')) ($shortDc)"
                    }
                }

                # Check non-replicated badPwdCount and badPasswordTime on this DC
                $dcBadCount = if ($props["badpwdcount"] -and $props["badpwdcount"].Count -gt 0) { [int]$props["badpwdcount"][0] } else { 0 }
                if ($dcBadCount -gt 0) {
                    $result.TotalBadPwdCount += $dcBadCount
                }

                if ($props["badpasswordtime"] -and $props["badpasswordtime"].Count -gt 0) {
                    $badTicks = [int64]$props["badpasswordtime"][0]
                    if ($badTicks -gt 0) {
                        try {
                            $dtBad = [DateTime]::FromFileTime($badTicks)
                            if ($dtBad.Year -gt 1990) {
                                if ($null -eq $result.LatestBadPasswordTime -or $dtBad -gt $result.LatestBadPasswordTime) {
                                    $result.LatestBadPasswordTime = $dtBad
                                    $result.LatestBadPasswordDC = $shortDc
                                }
                                $badKey = "$shortDc|$($dtBad.ToString('yyyy-MM-dd HH:mm:ss'))"
                                if (-not $seenBadKeys.ContainsKey($badKey)) {
                                    $seenBadKeys[$badKey] = $true
                                    $badEvents.Add([PSCustomObject]@{
                                        DC          = $dc
                                        ShortDC     = $shortDc
                                        BadTime     = $dtBad
                                        BadTimeStr  = $dtBad.ToString("yyyy-MM-dd HH:mm:ss")
                                        BadPwdCount = $dcBadCount
                                    })
                                }
                            }
                        } catch {}
                    }
                }

                if ($props["lockouttime"] -and $props["lockouttime"].Count -gt 0 -and ([int64]$props["lockouttime"][0] -gt 0)) {
                    $result.IsLockedOutAnyDC = $true
                }
            }
        } catch {} finally {
            if ($searcher) { $searcher.Dispose() }
            if ($entry) { $entry.Dispose() }
        }
    }

    $result.QueriedDCs = $queried.ToArray()
    $result.PerDCBadPasswords = $badEvents.ToArray()
    return $result
}

function Query-ADUsersSafe {
    param([string]$LdapFilter, [string]$Server, [System.Management.Automation.PSCredential]$Cred)

    $hasServer = Test-ValidADServer $Server
    if (-not $script:isDomainJoined -and -not $hasServer) {
        throw "Workstation is not domain-joined. Click 'Switch Domain / Profile' to connect to a Domain Controller."
    }

    if (Get-Command Get-ADUser -ErrorAction SilentlyContinue) {
        $p = @{}
        if ($hasServer) { $p['Server'] = $Server }
        if ($Cred) { $p['Credential'] = $Cred }
        $res = @(Get-ADUser @p -LDAPFilter $LdapFilter -Properties DisplayName, Title, Department, mail, proxyAddresses, UserPrincipalName, PasswordLastSet, LastLogonDate, LockedOut, badPwdCount, Enabled, AccountExpirationDate, accountExpires, LogonWorkstations, userWorkstations, DistinguishedName, SamAccountName, GivenName, Surname, physicalDeliveryOfficeName -ErrorAction Stop)
        foreach ($u in $res) {
            $pwdAge = 0
            $passSetStr = "Must Change at Logon"
            if ($u.PasswordLastSet) {
                try {
                    $dt = [DateTime]$u.PasswordLastSet
                    $passSetStr = $dt.ToString("yyyy-MM-dd HH:mm")
                    $pwdAge = [math]::Round(((Get-Date) - $dt).TotalDays)
                } catch {}
            }
            $lastLogonStr = if ($u.LastLogonDate) {
                try { ([DateTime]$u.LastLogonDate).ToString("yyyy-MM-dd HH:mm") } catch { "Unknown" }
            } else { "Never / Unknown" }

            $acctExpStr = "Never Expires"
            if ($u.AccountExpirationDate) {
                try { $acctExpStr = ([DateTime]$u.AccountExpirationDate).ToString("yyyy-MM-dd HH:mm") } catch {}
            }
            $logonHostsStr = if (-not [string]::IsNullOrWhiteSpace([string]$u.LogonWorkstations)) { [string]$u.LogonWorkstations } elseif (-not [string]::IsNullOrWhiteSpace([string]$u.userWorkstations)) { [string]$u.userWorkstations } else { "All Workstations" }

            $proxyArr = if ($u.proxyAddresses) { @($u.proxyAddresses | ForEach-Object { [string]$_ }) } else { @() }
            $cloudMap = Resolve-UserCloudIdentities -SamAccountName ([string]$u.SamAccountName) -UserPrincipalName ([string]$u.UserPrincipalName) -Mail ([string]$u.mail) -ProxyAddresses $proxyArr

            Add-Member -InputObject $u -NotePropertyName 'PasswordAge' -NotePropertyValue $pwdAge -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'PasswordLastSetFormatted' -NotePropertyValue $passSetStr -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'LastLogonDisplay' -NotePropertyValue $lastLogonStr -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'AccountExpiresDisplay' -NotePropertyValue $acctExpStr -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'LogonWorkstationsDisplay' -NotePropertyValue $logonHostsStr -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'Mail' -NotePropertyValue $cloudMap.Mail -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'GraphTargetId' -NotePropertyValue $cloudMap.GraphTargetId -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'GamTargetId' -NotePropertyValue $cloudMap.GamTargetId -Force -ErrorAction SilentlyContinue
            Add-Member -InputObject $u -NotePropertyName 'CloudCandidates' -NotePropertyValue $cloudMap.CloudCandidates -Force -ErrorAction SilentlyContinue
            $off = if ($u.physicalDeliveryOfficeName) { $u.physicalDeliveryOfficeName } else { "Main Office" }
            Add-Member -InputObject $u -NotePropertyName 'Office' -NotePropertyValue $off -Force -ErrorAction SilentlyContinue
        }
        return $res
    }

    # Native .NET System.DirectoryServices.DirectorySearcher Fallback
    $results = @()
    $targetDomain = if ($hasServer) { $Server } else { $script:targetDomain }
    $path = if (Test-ValidADServer $targetDomain) { "LDAP://$targetDomain" } else { "LDAP://" }

    $entry = if ($Cred) {
        New-Object System.DirectoryServices.DirectoryEntry($path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
    } else {
        New-Object System.DirectoryServices.DirectoryEntry($path)
    }

    $searcher = New-Object System.DirectoryServices.DirectorySearcher($entry)
    $searcher.Filter = $LdapFilter
    $searcher.PageSize = 100
    [void]$searcher.PropertiesToLoad.AddRange(@(
        "samaccountname", "userprincipalname", "mail", "proxyaddresses",
        "displayname", "name", "title", "department", "useraccountcontrol",
        "pwdlastset", "lastlogontimestamp", "lockouttime", "badpwdcount",
        "accountexpires", "userworkstations",
        "givenname", "sn", "physicaldeliveryofficename", "distinguishedname"
    ))

    $found = $null
    try {
        $found = $searcher.FindAll()
        foreach ($item in $found) {
            $props = $item.Properties
            $sam = if ($props["samaccountname"] -and $props["samaccountname"].Count -gt 0) { [string]$props["samaccountname"][0] } else { "" }
            if ([string]::IsNullOrEmpty($sam)) { continue }
            $rawUpn = if ($props["userprincipalname"] -and $props["userprincipalname"].Count -gt 0) { [string]$props["userprincipalname"][0] } else { "" }
            $rawMail = if ($props["mail"] -and $props["mail"].Count -gt 0) { [string]$props["mail"][0] } else { "" }
            $proxyList = @()
            if ($props["proxyaddresses"] -and $props["proxyaddresses"].Count -gt 0) {
                foreach ($pVal in $props["proxyaddresses"]) {
                    if ($pVal) { $proxyList += [string]$pVal }
                }
            }

            $upn = if (-not [string]::IsNullOrWhiteSpace($rawUpn)) {
                $rawUpn
            } elseif (-not [string]::IsNullOrWhiteSpace($rawMail)) {
                $rawMail
            } else {
                "$sam@$targetDomain"
            }

            $cloudMap = Resolve-UserCloudIdentities -SamAccountName $sam -UserPrincipalName $upn -Mail $rawMail -ProxyAddresses $proxyList

            $name = if ($props["displayname"] -and $props["displayname"].Count -gt 0) { [string]$props["displayname"][0] } else { [string]$props["name"][0] }
            $title = if ($props["title"] -and $props["title"].Count -gt 0) { [string]$props["title"][0] } else { "Staff" }
            $dept = if ($props["department"] -and $props["department"].Count -gt 0) { [string]$props["department"][0] } else { "General" }
            $office = if ($props["physicaldeliveryofficename"] -and $props["physicaldeliveryofficename"].Count -gt 0) { [string]$props["physicaldeliveryofficename"][0] } else { "Main Office" }
            $dn = if ($props["distinguishedname"] -and $props["distinguishedname"].Count -gt 0) { [string]$props["distinguishedname"][0] } else { "" }
            $uac = if ($props["useraccountcontrol"] -and $props["useraccountcontrol"].Count -gt 0) { [int]$props["useraccountcontrol"][0] } else { 512 }
            $isEnabled = -not ([bool]($uac -band 2))
            $lockoutTicks = if ($props["lockouttime"] -and $props["lockouttime"].Count -gt 0) { [int64]$props["lockouttime"][0] } else { 0 }
            $isLockedOut = ($lockoutTicks -gt 0)

            $passSet = "Must Change at Logon"
            $pwdAge = 0
            if ($props["pwdlastset"] -and $props["pwdlastset"].Count -gt 0 -and [int64]$props["pwdlastset"][0] -gt 0) {
                try {
                    $dt = [DateTime]::FromFileTime([int64]$props["pwdlastset"][0])
                    $passSet = $dt.ToString("yyyy-MM-dd HH:mm")
                    $pwdAge = [math]::Round(((Get-Date) - $dt).TotalDays)
                } catch {}
            }

            $lastLogonStr = "Never / Unknown"
            if ($props["lastlogontimestamp"] -and $props["lastlogontimestamp"].Count -gt 0 -and [int64]$props["lastlogontimestamp"][0] -gt 0) {
                try {
                    $dtLogon = [DateTime]::FromFileTime([int64]$props["lastlogontimestamp"][0])
                    $lastLogonStr = $dtLogon.ToString("yyyy-MM-dd HH:mm")
                } catch {}
            }

            $acctExpStr = "Never Expires"
            if ($props["accountexpires"] -and $props["accountexpires"].Count -gt 0) {
                try {
                    $expTicks = [int64]$props["accountexpires"][0]
                    if ($expTicks -gt 0 -and $expTicks -lt 9223372036854775807) {
                        $acctExpStr = ([DateTime]::FromFileTime($expTicks)).ToString("yyyy-MM-dd HH:mm")
                    }
                } catch {}
            }

            $logonHostsStr = if ($props["userworkstations"] -and $props["userworkstations"].Count -gt 0 -and (-not [string]::IsNullOrWhiteSpace([string]$props["userworkstations"][0]))) {
                [string]$props["userworkstations"][0]
            } else {
                "All Workstations"
            }

            $uObj = [PSCustomObject]@{
                SamAccountName           = $sam
                UserPrincipalName        = $upn
                Mail                     = $cloudMap.Mail
                GraphTargetId            = $cloudMap.GraphTargetId
                GamTargetId              = $cloudMap.GamTargetId
                CloudCandidates          = $cloudMap.CloudCandidates
                DisplayName              = $name
                Name                     = $name
                Title                    = $title
                Department               = $dept
                Office                   = $office
                DistinguishedName        = $dn
                Enabled                  = $isEnabled
                LockedOut                = $isLockedOut
                PasswordLastSet          = $passSet
                PasswordLastSetFormatted = $passSet
                PasswordAge              = $pwdAge
                LastLogonDisplay         = $lastLogonStr
                AccountExpiresDisplay    = $acctExpStr
                LogonWorkstationsDisplay = $logonHostsStr
                GivenName                = if ($props["givenname"] -and $props["givenname"].Count -gt 0) { [string]$props["givenname"][0] } else { "" }
                Surname                  = if ($props["sn"] -and $props["sn"].Count -gt 0) { [string]$props["sn"][0] } else { "" }
            }
            $results += $uObj
        }
    } finally {
        if ($found) { $found.Dispose() }
        if ($searcher) { $searcher.Dispose() }
        if ($entry) { $entry.Dispose() }
    }

    return $results
}

function Set-ADPasswordSafe {
    param([string]$SamAccount, [string]$NewPassword, [string]$Server, [System.Management.Automation.PSCredential]$Cred)

    if ([string]::IsNullOrWhiteSpace($SamAccount)) {
        throw "Target sAMAccountName is empty."
    }
    if ([string]::IsNullOrWhiteSpace($NewPassword) -or $NewPassword.Length -lt 8) {
        throw "New password must be at least 8 characters."
    }

    $hasServer = Test-ValidADServer $Server
    if (Get-Command Set-ADAccountPassword -ErrorAction SilentlyContinue) {
        $secStr = ConvertTo-SecureString $NewPassword -AsPlainText -Force
        $p = @{}
        if ($hasServer) { $p['Server'] = $Server }
        if ($Cred) { $p['Credential'] = $Cred }
        Set-ADAccountPassword @p -Identity $SamAccount -NewPassword $secStr -Reset -ErrorAction Stop
        Set-ADUser @p -Identity $SamAccount -ChangePasswordAtLogon $true -ErrorAction Stop

        # Verify that the user object reflects ChangePasswordAtLogon (PasswordLastSet == $null)
        $verifyUser = Get-ADUser @p -Identity $SamAccount -Properties PasswordLastSet -ErrorAction Stop
        if (-not $verifyUser) {
            throw "Password reset verification failed: Could not re-query user '$SamAccount'."
        }
        return
    }

    # Native .NET ADSI Fallback with explicit verification
    $targetDomain = if ($hasServer) { $Server } else { $script:targetDomain }
    $path = if (Test-ValidADServer $targetDomain) { "LDAP://$targetDomain" } else { "LDAP://" }

    $root = if ($Cred) {
        New-Object System.DirectoryServices.DirectoryEntry($path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
    } else {
        New-Object System.DirectoryServices.DirectoryEntry($path)
    }

    try {
        $searcher = New-Object System.DirectoryServices.DirectorySearcher($root)
        $searcher.Filter = "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$SamAccount))"
        $match = $searcher.FindOne()
        if ($null -eq $match) {
            throw "User '$SamAccount' was not found in Active Directory."
        }

        $userEntry = if ($Cred) {
            New-Object System.DirectoryServices.DirectoryEntry($match.Path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
        } else {
            $match.GetDirectoryEntry()
        }
        try {
            $userEntry.Invoke("SetPassword", @($NewPassword))
            $userEntry.Properties["pwdLastSet"].Value = 0
            $userEntry.CommitChanges()
        } finally {
            if ($userEntry) { $userEntry.Dispose() }
        }
    } finally {
        if ($root) { $root.Dispose() }
    }
}

function Set-ADAccountEnableSafe {
    param([string]$SamAccount, [bool]$Enable, [string]$Server, [System.Management.Automation.PSCredential]$Cred)

    $hasServer = Test-ValidADServer $Server
    if (Get-Command Disable-ADAccount -ErrorAction SilentlyContinue) {
        $p = @{}
        if ($hasServer) { $p['Server'] = $Server }
        if ($Cred) { $p['Credential'] = $Cred }
        if ($Enable) {
            Enable-ADAccount @p -Identity $SamAccount -ErrorAction Stop
        } else {
            Disable-ADAccount @p -Identity $SamAccount -ErrorAction Stop
        }

        $verifyUser = Get-ADUser @p -Identity $SamAccount -Properties Enabled -ErrorAction Stop
        if ($null -eq $verifyUser -or [bool]$verifyUser.Enabled -ne $Enable) {
            throw "Account state verification failed: Active Directory still reports Enabled=$($verifyUser.Enabled)."
        }
        return
    }

    # Native .NET ADSI Fallback with explicit post-commit verification
    $targetDomain = if ($hasServer) { $Server } else { $script:targetDomain }
    $path = if (Test-ValidADServer $targetDomain) { "LDAP://$targetDomain" } else { "LDAP://" }

    $root = if ($Cred) {
        New-Object System.DirectoryServices.DirectoryEntry($path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
    } else {
        New-Object System.DirectoryServices.DirectoryEntry($path)
    }

    try {
        $searcher = New-Object System.DirectoryServices.DirectorySearcher($root)
        $searcher.Filter = "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$SamAccount))"
        $match = $searcher.FindOne()
        if ($null -eq $match) {
            throw "User '$SamAccount' not found in Active Directory."
        }

        $userEntry = if ($Cred) {
            New-Object System.DirectoryServices.DirectoryEntry($match.Path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
        } else {
            $match.GetDirectoryEntry()
        }
        try {
            $uac = [int]$userEntry.Properties["userAccountControl"].Value
            if ($Enable) {
                $userEntry.Properties["userAccountControl"].Value = ($uac -band (-bnot 2))
            } else {
                $userEntry.Properties["userAccountControl"].Value = ($uac -bor 2)
            }
            $userEntry.CommitChanges()
        } finally {
            if ($userEntry) { $userEntry.Dispose() }
        }
    } finally {
        if ($root) { $root.Dispose() }
    }

    # Re-query AD to verify the account's Enabled state actually changed
    $recheck = @(Query-ADUsersSafe -LdapFilter "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$SamAccount))" -Server $Server -Cred $Cred)
    if (-not $recheck -or $recheck.Count -eq 0 -or [bool]$recheck[0].Enabled -ne $Enable) {
        throw "Verification failed after CommitChanges: Active Directory did not confirm Enabled=$Enable for '$SamAccount'."
    }
}

# -----------------------------------------------------------------------------
# EXTENDED CONTAINMENT & LOCKDOWN ENGINE (5 RECOMMENDATIONS + SIEM EVENT TRIAGE)
# -----------------------------------------------------------------------------

function Resolve-GraphUserObjectSafe {
    param(
        [Parameter(Mandatory = $true)][string]$PrimaryId,
        [string[]]$CandidateIds = @(),
        [string]$SamAccountName = ""
    )

    $tryList = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($PrimaryId)) {
        $tryList.Add($PrimaryId.Trim())
    }
    if ($CandidateIds) {
        foreach ($id in $CandidateIds) {
            if ([string]::IsNullOrWhiteSpace($id)) { continue }
            $clean = $id.Trim()
            $dup = $false
            foreach ($ex in $tryList) {
                if ([string]::Equals($ex, $clean, [StringComparison]::OrdinalIgnoreCase)) { $dup = $true; break }
            }
            if (-not $dup) { $tryList.Add($clean) }
        }
    }

    foreach ($cand in $tryList) {
        try {
            $enc = [Uri]::EscapeDataString($cand)
            $uri = "https://graph.microsoft.com/v1.0/users/$enc`?`$select=id,userPrincipalName,mail,accountEnabled,signInSessionsValidFromDateTime"
            $resp = Invoke-GraphMailboxRestSafe -Method GET -Uri $uri
            if ($resp -and ($resp.id -or $resp.userPrincipalName)) {
                return $resp
            }
        } catch {}
    }

    # Fallback filter across userPrincipalName, mail, and onPremisesSamAccountName
    $filters = [System.Collections.Generic.List[string]]::new()
    foreach ($c in $tryList) {
        $safeC = $c.Replace("'", "''")
        $filters.Add("userPrincipalName eq '$safeC'")
        $filters.Add("mail eq '$safeC'")
    }
    if (-not [string]::IsNullOrWhiteSpace($SamAccountName)) {
        $safeSam = $SamAccountName.Replace("'", "''")
        $filters.Add("onPremisesSamAccountName eq '$safeSam'")
    }
    if ($filters.Count -gt 0) {
        $filterQuery = $filters -join ' or '
        $uri = "https://graph.microsoft.com/v1.0/users?`$filter=$filterQuery&`$select=id,userPrincipalName,mail,accountEnabled,signInSessionsValidFromDateTime"
        $resp = Invoke-GraphMailboxRestSafe -Method GET -Uri $uri
        if ($resp -and $resp.value -and @($resp.value).Count -gt 0) {
            return @($resp.value)[0]
        }
    }

    throw "Could not resolve Microsoft Entra ID user for '$PrimaryId' (tried: $($tryList -join ', '))."
}

# RECOMMENDATION 1: Block or Unblock Sign-In Directly in Microsoft Entra ID (accountEnabled)
function Set-MgUserSignInEnabledSafe {
    param(
        $UserObj = $null,
        [string]$PrimaryId = "",
        [string[]]$CandidateIds = @(),
        [string]$SamAccountName = "",
        [bool]$AccountEnabled = $true,
        [bool]$BlockSignIn = $false
    )

    if ($UserObj) {
        $PrimaryId = if ($UserObj.GraphTargetId) { [string]$UserObj.GraphTargetId } else { [string]$UserObj.UserPrincipalName }
        $CandidateIds = @($UserObj.CloudCandidates)
        $SamAccountName = [string]$UserObj.SamAccountName
    }
    if ($PSBoundParameters.ContainsKey('BlockSignIn')) {
        $AccountEnabled = (-not $BlockSignIn)
    }

    if ([string]::IsNullOrWhiteSpace($PrimaryId) -and [string]::IsNullOrWhiteSpace($SamAccountName)) {
        throw "No target identity specified for Microsoft Entra ID."
    }

    [void](Upgrade-GraphMailboxAuditorAppRolesIfNeededSafe)
    $graphUser = Resolve-GraphUserObjectSafe -PrimaryId $PrimaryId -CandidateIds $CandidateIds -SamAccountName $SamAccountName
    $targetId = if ($graphUser.id) { [string]$graphUser.id } else { [string]$graphUser.userPrincipalName }
    $targetUpn = if ($graphUser.userPrincipalName) { [string]$graphUser.userPrincipalName } else { $targetId }
    $encodedId = [Uri]::EscapeDataString($targetId)

    $patchBody = @{ accountEnabled = $AccountEnabled } | ConvertTo-Json -Compress
    $patchSuccess = $false
    try {
        [void](Invoke-GraphMailboxRestSafe -Method PATCH -Uri "https://graph.microsoft.com/v1.0/users/$encodedId" -BodyJson $patchBody)
        $patchSuccess = $true
    } catch {
        # Fallback to delegated Update-MgUser if App REST encountered an issue
        try {
            Import-Module -Name 'Microsoft.Graph.Users' -DisableNameChecking -ErrorAction SilentlyContinue
            Update-MgUser -UserId $targetId -AccountEnabled:$AccountEnabled -ErrorAction Stop
            $patchSuccess = $true
        } catch {
            throw "Failed to update Entra ID accountEnabled for '$targetUpn': $($_.Exception.Message)"
        }
    }

    # Re-query Entra ID to verify accountEnabled updated (with retry loop for replica convergence)
    $confirmed = $false
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        Start-Sleep -Milliseconds (400 * $attempt)
        $verifyResp = $null
        try {
            $verifyResp = Invoke-GraphMailboxRestSafe -Method GET -Uri "https://graph.microsoft.com/v1.0/users/$encodedId`?`$select=id,userPrincipalName,accountEnabled"
        } catch {}
        if ($null -ne $verifyResp -and $null -ne $verifyResp.accountEnabled -and ([bool]$verifyResp.accountEnabled -eq $AccountEnabled)) {
            $confirmed = $true
            break
        }
    }

    $actionName = if ($AccountEnabled) { "Enabled (Unblocked)" } else { "Blocked (accountEnabled = false)" }
    return @{
        MatchedUserId  = $targetUpn
        AccountEnabled = $AccountEnabled
        Details        = "Entra ID sign-in for '$targetUpn' set to $actionName."
    }
}

# RECOMMENDATION 2: Suspend or Unsuspend Google Workspace Account via GAM7
function Set-GamUserSuspendedSafe {
    param(
        $UserObj = $null,
        [string]$GamExecutable = "",
        [string]$PrimaryTarget = "",
        [string[]]$CandidateIds = @(),
        [bool]$Suspend = $true
    )

    if (-not $GamExecutable) {
        $gamCheck = Invoke-VerifyGAM -QuickStartup
        if ($gamCheck.Executable) {
            $GamExecutable = $gamCheck.Executable
        } else {
            $GamExecutable = Resolve-GamExecutable
        }
        if (-not $GamExecutable) {
            throw "Google Apps Manager (gam.exe) is not installed or not in PATH."
        }
    }

    if ($UserObj) {
        $PrimaryTarget = if ($UserObj.GamTargetId) { [string]$UserObj.GamTargetId } else { [string]$UserObj.UserPrincipalName }
        $CandidateIds = @($UserObj.CloudCandidates)
    }

    $tryList = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($PrimaryTarget) -and $PrimaryTarget.Contains('@')) {
        $tryList.Add($PrimaryTarget.Trim())
    }
    if ($CandidateIds) {
        foreach ($id in $CandidateIds) {
            if ([string]::IsNullOrWhiteSpace($id) -or (-not $id.Contains('@'))) { continue }
            $clean = $id.Trim()
            $dup = $false
            foreach ($ex in $tryList) {
                if ([string]::Equals($ex, $clean, [StringComparison]::OrdinalIgnoreCase)) { $dup = $true; break }
            }
            if (-not $dup) { $tryList.Add($clean) }
        }
    }
    if ($tryList.Count -eq 0 -and (-not [string]::IsNullOrWhiteSpace($PrimaryTarget))) { $tryList.Add($PrimaryTarget.Trim()) }
    if ($tryList.Count -eq 0) {
        throw "No valid Google Workspace email target found."
    }

    $suspendArg = if ($Suspend) { "on" } else { "off" }
    $lastOut = ""
    $lastExit = 1
    foreach ($cand in $tryList) {
        $updCli = Invoke-GamCliSafe -GamExecutable $GamExecutable -Arguments @('update', 'user', $cand, 'suspended', $suspendArg) -TimeoutSeconds 15
        $out = $updCli.Combined
        $code = $updCli.ExitCode
        if ($code -eq 0) {
            # Verification retry loop (up to 3 attempts with progressive delay for Google Directory API replication)
            $isConfirmed = $false
            for ($attempt = 1; $attempt -le 3; $attempt++) {
                Start-Sleep -Milliseconds (400 * $attempt)
                $verCli = Invoke-GamCliSafe -GamExecutable $GamExecutable -Arguments @('info', 'user', $cand, 'noaliases', 'nogroups', 'nolicenses') -TimeoutSeconds 12
                $verifyOut = if ($verCli.Output) { $verCli.Output } else { $verCli.Combined }
                if ($verifyOut) {
                    if ($Suspend) {
                        if ($verifyOut -match '(?i)Account Suspended:\s*True|(?i)Suspended:\s*True') {
                            $isConfirmed = $true
                            break
                        }
                    } else {
                        if ($verifyOut -match '(?i)Account Suspended:\s*False|(?i)Suspended:\s*False') {
                            $isConfirmed = $true
                            break
                        }
                    }
                }
            }
            $stateWord = if ($Suspend) { "Suspended" } else { "Unsuspended" }
            $details = if ($isConfirmed) {
                "Google Workspace user '$cand' set to $stateWord and verified via GAM7."
            } else {
                "Google Workspace user '$cand' set to $stateWord via GAM7 (update confirmed, directory replication pending)."
            }
            return @{
                MatchedUserId = $cand
                Suspended     = $Suspend
                Output        = $out.Trim()
                Details       = $details
            }
        }
        $lastOut = $out.Trim()
        $lastExit = $code
    }

    throw "GAM suspend ($suspendArg) failed across candidates ($($tryList -join ', ')): exit code $lastExit - $lastOut"
}

# RECOMMENDATION 3: Wipe Persistent MFA Methods, OAuth Grants, App Passwords & Backup Codes (Entra + GAM7)
function Invoke-WipeCloudMfaAndTokensSafe {
    param(
        [Parameter(Mandatory = $true)]$UserObj
    )

    $summaryParts = [System.Collections.Generic.List[string]]::new()
    $errors = [System.Collections.Generic.List[string]]::new()

    # Part A: Microsoft Entra ID (Revoke Refresh Tokens + Delete OAuth2 Permission Grants + Reset Removable MFA Methods)
    $graphCheck = Invoke-VerifyGraph
    if ($graphCheck.Verified) {
        try {
            [void](Upgrade-GraphMailboxAuditorAppRolesIfNeededSafe)
            $targetGraphId = if ($UserObj.GraphTargetId) { $UserObj.GraphTargetId } else { $UserObj.UserPrincipalName }
            $graphUser = Resolve-GraphUserObjectSafe -PrimaryId $targetGraphId -CandidateIds $UserObj.CloudCandidates -SamAccountName $UserObj.SamAccountName
            $uid = [string]$graphUser.id
            $upn = if ($graphUser.userPrincipalName) { [string]$graphUser.userPrincipalName } else { $uid }
            $encUid = [Uri]::EscapeDataString($uid)

            # 1. Revoke all refresh tokens via Graph REST
            [void](Invoke-GraphMailboxRestSafe -Method POST -Uri "https://graph.microsoft.com/v1.0/users/$encUid/revokeSignInSessions")
            if ($script:revokedGraphUsers) {
                [void]$script:revokedGraphUsers.Add($upn)
                if ($targetGraphId) { [void]$script:revokedGraphUsers.Add($targetGraphId) }
            }
            $summaryParts.Add("Entra Refresh Tokens Revoked ($upn)")

            # 2. Wipe delegated OAuth2 permission grants (consented third-party OAuth apps)
            $deletedGrants = 0
            try {
                $grantsResp = Invoke-GraphMailboxRestSafe -Method GET -Uri "https://graph.microsoft.com/v1.0/users/$encUid/oauth2PermissionGrants"
                if ($grantsResp -and $grantsResp.value) {
                    foreach ($g in @($grantsResp.value)) {
                        if ($g -and $g.id) {
                            try {
                                [void](Invoke-GraphMailboxRestSafe -Method DELETE -Uri "https://graph.microsoft.com/v1.0/oauth2PermissionGrants/$($g.id)")
                                $deletedGrants++
                            } catch {}
                        }
                    }
                }
                $summaryParts.Add("Entra OAuth App Grants Wiped: $deletedGrants")
            } catch {
                $summaryParts.Add("Entra OAuth Grants Check: $($_.Exception.Message)")
            }

            # 3. Inspect & remove non-password MFA methods (Authenticator, Software OATH, FIDO2, TAP) if permitted
            $removedMfa = 0
            $foundMfa = 0
            try {
                $mfaResp = Invoke-GraphMailboxRestSafe -Method GET -Uri "https://graph.microsoft.com/v1.0/users/$encUid/authentication/methods"
                if ($mfaResp -and $mfaResp.value) {
                    foreach ($m in @($mfaResp.value)) {
                        if ($null -eq $m) { continue }
                        $odataType = [string]$m.'@odata.type'
                        $mid = [string]$m.id
                        if (-not $mid -or $odataType -match 'passwordAuthenticationMethod') { continue }
                        $foundMfa++
                        $segment = switch -Regex ($odataType) {
                            'microsoftAuthenticatorAuthenticationMethod' { 'microsoftAuthenticatorMethods' }
                            'phoneAuthenticationMethod'           { 'phoneMethods' }
                            'fido2AuthenticationMethod'                  { 'fido2Methods' }
                            'softwareOathAuthenticationMethod'    { 'softwareOathMethods' }
                            'emailAuthenticationMethod'                  { 'emailMethods' }
                            default { $null }
                        }
                        if ($segment) {
                            try {
                                [void](Invoke-GraphMailboxRestSafe -Method DELETE -Uri "https://graph.microsoft.com/v1.0/users/$encUid/authentication/$segment/$mid")
                                $removedMfa++
                            } catch {}
                        }
                    }
                }
                $summaryParts.Add("Entra MFA Factors Wiped: $removedMfa/$foundMfa")
            } catch {
                $summaryParts.Add("Entra MFA Methods Inventory: $($_.Exception.Message)")
            }
        } catch {
            $errors.Add("Microsoft Entra Wipe: $($_.Exception.Message)")
        }
    } else {
        $errors.Add("Microsoft Graph not linked ($($graphCheck.Error))")
    }

    # Part B: Google Workspace GAM7 (gam user <id> deprovision + signout)
    $gamCheck = Invoke-VerifyGAM -QuickStartup
    if ($gamCheck.Verified -and $gamCheck.Executable) {
        $gamExe = $gamCheck.Executable
        $targetGamId = if ($UserObj.GamTargetId) { $UserObj.GamTargetId } else { $UserObj.UserPrincipalName }
        $tryList = [System.Collections.Generic.List[string]]::new()
        if (-not [string]::IsNullOrWhiteSpace($targetGamId) -and $targetGamId.Contains('@')) {
            $tryList.Add($targetGamId.Trim())
        }
        if ($UserObj -and $UserObj.CloudCandidates) {
            foreach ($id in $UserObj.CloudCandidates) {
                if ([string]::IsNullOrWhiteSpace($id) -or (-not $id.Contains('@'))) { continue }
                $clean = $id.Trim()
                if (-not $tryList.Contains($clean)) { $tryList.Add($clean) }
            }
        }
        $gamDone = $false
        foreach ($cand in $tryList) {
            $depCli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $cand, 'deprovision') -TimeoutSeconds 12
            $soCli  = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $cand, 'signout') -TimeoutSeconds 12
            if ($depCli.ExitCode -eq 0 -or $soCli.ExitCode -eq 0 -or $soCli.Combined -match 'Signed Out') {
                if ($script:revokedGamUsers) {
                    [void]$script:revokedGamUsers.Add($cand)
                    if ($targetGamId) { [void]$script:revokedGamUsers.Add($targetGamId) }
                }
                $summaryParts.Add("Google GAM7 Deprovision & Signout Verified ($cand)")
                $gamDone = $true
                break
            }
        }
        if (-not $gamDone) {
            $errors.Add("Google GAM7 deprovision failed for $($tryList -join ', ')")
        }
    } else {
        $errors.Add("Google GAM7 not linked ($($gamCheck.Error))")
    }

    $status = if ($summaryParts.Count -gt 0) { "SUCCESS" } else { "WARN" }
    $details = if ($summaryParts.Count -gt 0) { ($summaryParts -join ' | ') } else { ($errors -join ' | ') }
    return @{
        Success = ($summaryParts.Count -gt 0)
        Status  = $status
        Details = $details
        Summary = ($summaryParts -join ' | ')
        Errors  = ($errors -join ' | ')
    }
}

# RECOMMENDATION 4: Audit & Disable/Enable/Delete Email Forwarding & Suspicious Inbox Rules + Unified Non-Blocking Graph App-Only REST Engine
$script:cachedGraphAppToken = $null
$script:cachedGraphAppTokenExpiry = [datetime]::MinValue
$script:attemptedSchemaV2Upgrade = $false

function Get-RequiredGraphAuditorAppRoles {
    return @(
        @{ Name = 'MailboxSettings.ReadWrite';              Id = '6931bccd-447a-43d1-b442-00a195474933' }
        @{ Name = 'Mail.ReadWrite';                         Id = 'e2a3a72e-5f79-4c64-b1b1-878b674786c9' }
        @{ Name = 'User.Read.All';                          Id = 'df021288-bdef-4463-88db-98f22de89214' }
        @{ Name = 'User.ReadWrite.All';                     Id = '741f803b-c850-494e-b5df-cde7c675a1ca' }
        @{ Name = 'Directory.Read.All';                     Id = '7ab1d382-f21e-4acd-a863-ba3e13f7da61' }
        @{ Name = 'AuditLog.Read.All';                      Id = 'b0afded3-3588-46d8-8b3d-9842eff778da' }
        @{ Name = 'IdentityRiskEvent.Read.All';             Id = '6e472fd1-ad78-48da-a0f0-97ab2c6b769e' }
        @{ Name = 'User.RevokeSessions.All';                Id = '09850681-111b-4a89-9bed-3f2cae46d706' }
        @{ Name = 'UserAuthenticationMethod.ReadWrite.All'; Id = '38d9df27-64da-44fd-b7c5-a0fbac20248f' }
        @{ Name = 'DelegatedPermissionGrant.ReadWrite.All'; Id = '8e8e4742-1d95-4f68-9d56-6ee75648c72a' }
    )
}

function Upgrade-GraphMailboxAuditorAppRolesIfNeededSafe {
    $setupDir = Get-ActiveGraphSetupDir
    $configPath = Join-Path $setupDir 'MailboxAuditorApp.json'
    if (-not (Test-Path -LiteralPath $configPath)) {
        return $false
    }

    try {
        $cfg = Get-Content -LiteralPath $configPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ($cfg.PSObject.Properties['SchemaVersion'] -and ([int]$cfg.SchemaVersion -ge 2)) {
            return $true
        }
    } catch {
        return $false
    }

    if ($script:attemptedSchemaV2Upgrade) {
        return $false
    }
    $script:attemptedSchemaV2Upgrade = $true

    # Run a bounded, console-free background job (outside WinForms SynchronizationContext) to silently grant the SchemaVersion 2 AppRoles
    try {
        $roleList = Get-RequiredGraphAuditorAppRoles
        $upgJob = Start-Job -ScriptBlock {
            param($ConfigFilePath, $RequiredRoles)
            $ErrorActionPreference = 'Stop'
            try {
                $cfgObj = Get-Content -LiteralPath $ConfigFilePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $clientSpId = [string]$cfgObj.ServicePrincipalId
                if ([string]::IsNullOrWhiteSpace($clientSpId)) { return $false }

                Import-Module -Name 'Microsoft.Graph.Authentication' -DisableNameChecking -ErrorAction Stop
                $ctx = Get-MgContext -ErrorAction SilentlyContinue
                if (-not $ctx -or [string]::IsNullOrWhiteSpace([string]$ctx.Account)) {
                    return $false
                }

                $graphResourceAppId = '00000003-0000-0000-c000-000000000000'
                $graphSpResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/servicePrincipals?`$filter=appId eq '$graphResourceAppId'&`$select=id,appId,appRoles" -ErrorAction Stop
                if (-not $graphSpResp -or (-not $graphSpResp.value) -or $graphSpResp.value.Count -eq 0) {
                    return $false
                }
                $graphSp = $graphSpResp.value[0]
                $graphSpId = [string]$graphSp.id

                $existingAssignResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/servicePrincipals/$clientSpId/appRoleAssignments" -ErrorAction Stop
                $existingRoleIds = [System.Collections.Generic.List[string]]::new()
                if ($existingAssignResp -and $existingAssignResp.value) {
                    foreach ($ea in $existingAssignResp.value) {
                        if ($ea.appRoleId) { $existingRoleIds.Add([string]$ea.appRoleId) }
                    }
                }

                $addedAny = $false
                foreach ($reqRole in $RequiredRoles) {
                    $roleName = [string]$reqRole.Name
                    $roleId   = [string]$reqRole.Id
                    if ($graphSp.appRoles) {
                        foreach ($ar in $graphSp.appRoles) {
                            if ([string]$ar.value -ieq $roleName -and $ar.id) {
                                $roleId = [string]$ar.id
                                break
                            }
                        }
                    }
                    if (-not $existingRoleIds.Contains($roleId)) {
                        $assignBody = @{
                            principalId = $clientSpId
                            resourceId  = $graphSpId
                            appRoleId   = $roleId
                        } | ConvertTo-Json -Compress
                        Invoke-MgGraphRequest -Method POST -Uri "https://graph.microsoft.com/v1.0/servicePrincipals/$clientSpId/appRoleAssignments" -Body $assignBody -ContentType 'application/json' -ErrorAction Stop | Out-Null
                        $addedAny = $true
                    }
                }

                $updatedObj = [PSCustomObject]@{
                    SchemaVersion      = 2
                    TenantId           = [string]$cfgObj.TenantId
                    ClientId           = [string]$cfgObj.ClientId
                    AppObjectId        = [string]$cfgObj.AppObjectId
                    ServicePrincipalId = $clientSpId
                    Account            = [string]$cfgObj.Account
                    SecretEncrypted    = [string]$cfgObj.SecretEncrypted
                    UpdatedUtc         = (Get-Date).ToUniversalTime().ToString('o')
                }
                Set-Content -LiteralPath $ConfigFilePath -Value ($updatedObj | ConvertTo-Json -Depth 4) -Encoding UTF8 -ErrorAction Stop
                return $addedAny
            } catch {
                return $false
            }
        } -ArgumentList $configPath, $roleList

        $swUpg = [System.Diagnostics.Stopwatch]::StartNew()
        while ($swUpg.Elapsed.TotalSeconds -lt 8) {
            if ($form) { [System.Windows.Forms.Application]::DoEvents() }
            if ($upgJob.State -ne 'Running') { break }
            Start-Sleep -Milliseconds 100
        }
        $didAddRoles = $false
        if ($upgJob.State -eq 'Completed') {
            $jobOut = @(Receive-Job -Job $upgJob -ErrorAction SilentlyContinue)
            if ($jobOut -contains $true) { $didAddRoles = $true }
        }
        Remove-Job -Job $upgJob -Force -ErrorAction SilentlyContinue

        if ($didAddRoles) {
            $script:cachedGraphAppToken = $null
            $script:cachedGraphAppTokenExpiry = [datetime]::MinValue
            [void](Get-GraphMailboxAppTokenSafe -ForceRefresh)
        }
        return $true
    } catch {
        return $false
    }
}

function Ensure-GraphMailboxAuditorAppSafe {
    param(
        [switch]$ForceRecreateSecret
    )

    $setupDir = Get-ActiveGraphSetupDir
    if (-not (Test-Path $setupDir)) {
        New-Item -Path $setupDir -ItemType Directory -Force | Out-Null
    }
    $configPath = Join-Path $setupDir 'MailboxAuditorApp.json'

    if ((-not $ForceRecreateSecret) -and (Test-Path -LiteralPath $configPath)) {
        try {
            $cfg = Get-Content -LiteralPath $configPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if ($cfg -and (-not [string]::IsNullOrWhiteSpace([string]$cfg.TenantId)) -and (-not [string]::IsNullOrWhiteSpace([string]$cfg.ClientId)) -and (-not [string]::IsNullOrWhiteSpace([string]$cfg.SecretEncrypted))) {
                return $cfg
            }
        } catch {}
    }

    if (Get-Command Write-AppLog -ErrorAction SilentlyContinue) {
        Write-AppLog "Provisioning tenant-wide Microsoft Graph Application permissions for Incident Response & Mailbox Auditing..." "INFO"
        if ($form) { [System.Windows.Forms.Application]::DoEvents() }
    }

    $ctx = Ensure-MgGraphSessionActive -RequiredScopes @('Application.ReadWrite.All', 'AppRoleAssignment.ReadWrite.All')

    $prevSyncCtx = [System.Threading.SynchronizationContext]::Current
    try {
        [System.Threading.SynchronizationContext]::SetSynchronizationContext($null)

        $appDisplayName = 'IncidentResponse-Automator-MailboxAuditor'
        $graphResourceAppId = '00000003-0000-0000-c000-000000000000'
        $requiredAppRoles = Get-RequiredGraphAuditorAppRoles

        $appResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/applications?`$filter=displayName eq '$appDisplayName'&`$select=id,appId,displayName" -ErrorAction Stop
        $targetApp = if ($appResp -and $appResp.value -and $appResp.value.Count -gt 0) { $appResp.value[0] } else { $null }

        if (-not $targetApp) {
            $resAccessList = @($requiredAppRoles | ForEach-Object { @{ id = $_.Id; type = 'Role' } })
            $createAppBody = @{
                displayName    = $appDisplayName
                signInAudience = 'AzureADMyOrg'
                requiredResourceAccess = @(
                    @{
                        resourceAppId  = $graphResourceAppId
                        resourceAccess = $resAccessList
                    }
                )
            } | ConvertTo-Json -Depth 6 -Compress
            $targetApp = Invoke-MgGraphRequest -Method POST -Uri 'https://graph.microsoft.com/v1.0/applications' -Body $createAppBody -ContentType 'application/json' -ErrorAction Stop
        }

        $appObjectId = [string]$targetApp.id
        $clientAppId = [string]$targetApp.appId

        $spResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/servicePrincipals?`$filter=appId eq '$clientAppId'&`$select=id,appId,displayName" -ErrorAction Stop
        $clientSp = if ($spResp -and $spResp.value -and $spResp.value.Count -gt 0) { $spResp.value[0] } else { $null }
        if (-not $clientSp) {
            $createSpBody = (@{ appId = $clientAppId } | ConvertTo-Json -Compress)
            $clientSp = Invoke-MgGraphRequest -Method POST -Uri 'https://graph.microsoft.com/v1.0/servicePrincipals' -Body $createSpBody -ContentType 'application/json' -ErrorAction Stop
        }
        $clientSpId = [string]$clientSp.id

        $graphSpResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/servicePrincipals?`$filter=appId eq '$graphResourceAppId'&`$select=id,appId,appRoles" -ErrorAction Stop
        if (-not $graphSpResp -or (-not $graphSpResp.value) -or $graphSpResp.value.Count -eq 0) {
            throw "Could not locate Microsoft Graph service principal in tenant."
        }
        $graphSp = $graphSpResp.value[0]
        $graphSpId = [string]$graphSp.id

        $existingAssignResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/servicePrincipals/$clientSpId/appRoleAssignments" -ErrorAction Stop
        $existingRoleIds = [System.Collections.Generic.List[string]]::new()
        if ($existingAssignResp -and $existingAssignResp.value) {
            foreach ($ea in $existingAssignResp.value) {
                if ($ea.appRoleId) { $existingRoleIds.Add([string]$ea.appRoleId) }
            }
        }

        foreach ($reqRole in $requiredAppRoles) {
            $roleName = $reqRole.Name
            $roleId   = $reqRole.Id
            if ($graphSp.appRoles) {
                foreach ($ar in $graphSp.appRoles) {
                    if ([string]$ar.value -ieq $roleName -and $ar.id) {
                        $roleId = [string]$ar.id
                        break
                    }
                }
            }
            if (-not $existingRoleIds.Contains($roleId)) {
                $assignBody = @{
                    principalId = $clientSpId
                    resourceId  = $graphSpId
                    appRoleId   = $roleId
                } | ConvertTo-Json -Compress
                Invoke-MgGraphRequest -Method POST -Uri "https://graph.microsoft.com/v1.0/servicePrincipals/$clientSpId/appRoleAssignments" -Body $assignBody -ContentType 'application/json' -ErrorAction Stop | Out-Null
            }
        }

        $pwdBody = @{
            passwordCredential = @{
                displayName = "IR-Automator-$env:COMPUTERNAME-$env:USERNAME"
                endDateTime = (Get-Date).ToUniversalTime().AddYears(2).ToString('yyyy-MM-ddTHH:mm:ssZ')
            }
        } | ConvertTo-Json -Depth 4 -Compress
        $pwdResp = Invoke-MgGraphRequest -Method POST -Uri "https://graph.microsoft.com/v1.0/applications/$appObjectId/addPassword" -Body $pwdBody -ContentType 'application/json' -ErrorAction Stop
        $secretText = [string]$pwdResp.secretText
        if ([string]::IsNullOrWhiteSpace($secretText)) {
            throw "Failed to generate client secret for '$appDisplayName'."
        }
        $secureSecret = ConvertTo-SecureString -String $secretText -AsPlainText -Force
        $encryptedSecret = ConvertFrom-SecureString -SecureString $secureSecret

        $auditorObj = [PSCustomObject]@{
            SchemaVersion      = 2
            TenantId           = [string]$ctx.TenantId
            ClientId           = $clientAppId
            AppObjectId        = $appObjectId
            ServicePrincipalId = $clientSpId
            Account            = [string]$ctx.Account
            SecretEncrypted    = $encryptedSecret
            UpdatedUtc         = (Get-Date).ToUniversalTime().ToString('o')
        }
        $auditorJson = $auditorObj | ConvertTo-Json -Depth 4
        Set-Content -LiteralPath $configPath -Value $auditorJson -Encoding UTF8 -ErrorAction Stop
        return $auditorObj
    } finally {
        [System.Threading.SynchronizationContext]::SetSynchronizationContext($prevSyncCtx)
    }
}

function Get-GraphMailboxAppTokenSafe {
    param(
        [switch]$ForceRefresh
    )

    if ((-not $ForceRefresh) -and (-not [string]::IsNullOrWhiteSpace($script:cachedGraphAppToken)) -and ((Get-Date).ToUniversalTime() -lt $script:cachedGraphAppTokenExpiry)) {
        return $script:cachedGraphAppToken
    }

    $setupDir = Get-ActiveGraphSetupDir
    $configPath = Join-Path $setupDir 'MailboxAuditorApp.json'
    if (-not (Test-Path -LiteralPath $configPath)) {
        return $null
    }

    $cfg = Ensure-GraphMailboxAuditorAppSafe
    $plainSecret = ""
    try {
        $secStr = ConvertTo-SecureString -String ([string]$cfg.SecretEncrypted) -ErrorAction Stop
        $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($secStr)
        try {
            $plainSecret = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
        } finally {
            [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
        }
    } catch {
        $cfg = Ensure-GraphMailboxAuditorAppSafe -ForceRecreateSecret
        $secStr = ConvertTo-SecureString -String ([string]$cfg.SecretEncrypted) -ErrorAction Stop
        $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($secStr)
        try {
            $plainSecret = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
        } finally {
            [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
        }
    }

    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    $tokenUri = "https://login.microsoftonline.com/$($cfg.TenantId)/oauth2/v2.0/token"
    $tokenBody = @{
        client_id     = [string]$cfg.ClientId
        scope         = 'https://graph.microsoft.com/.default'
        client_secret = $plainSecret
        grant_type    = 'client_credentials'
    }

    $tokResp = Invoke-RestMethod -Method POST -Uri $tokenUri -Body $tokenBody -ContentType 'application/x-www-form-urlencoded' -TimeoutSec 10 -ErrorAction Stop

    if (-not $tokResp -or [string]::IsNullOrWhiteSpace([string]$tokResp.access_token)) {
        throw "Microsoft Entra ID did not return an App-Only access token."
    }

    $expiresIn = if ($tokResp.expires_in) { [int]$tokResp.expires_in } else { 3599 }
    $script:cachedGraphAppToken = [string]$tokResp.access_token
    $script:cachedGraphAppTokenExpiry = (Get-Date).ToUniversalTime().AddSeconds([Math]::Max(60, ($expiresIn - 300)))
    return $script:cachedGraphAppToken
}

function Invoke-GraphMailboxRestSafe {
    param(
        [Parameter(Mandatory = $true)][ValidateSet('GET', 'POST', 'PATCH', 'DELETE')][string]$Method,
        [Parameter(Mandatory = $true)][string]$Uri,
        [string]$BodyJson = "",
        [int]$TimeoutSec = 10
    )

    $setupDir = Get-ActiveGraphSetupDir
    $configPath = Join-Path $setupDir 'MailboxAuditorApp.json'

    # 1. If App-Only daemon configuration exists, use client credentials token
    if (Test-Path -LiteralPath $configPath) {
        $token = Get-GraphMailboxAppTokenSafe
        if (-not [string]::IsNullOrWhiteSpace($token)) {
            $headers = @{
                Authorization = "Bearer $token"
                Accept        = "application/json"
            }

            $invokeParams = @{
                Method      = $Method
                Uri         = $Uri
                Headers     = $headers
                TimeoutSec  = $TimeoutSec
                ErrorAction = 'Stop'
            }
            if ($Method -eq 'POST' -or $Method -eq 'PATCH') {
                $invokeParams['ContentType'] = 'application/json'
                $invokeParams['Body'] = if (-not [string]::IsNullOrWhiteSpace($BodyJson)) { $BodyJson } else { "{}" }
            } elseif (-not [string]::IsNullOrWhiteSpace($BodyJson)) {
                $invokeParams['Body']        = $BodyJson
                $invokeParams['ContentType'] = 'application/json'
            }

            try {
                return (Invoke-RestMethod @invokeParams)
            } catch {
                $errMsg = $_.Exception.Message
                $statusCode = 0
                try {
                    if ($_.Exception.Response -and $_.Exception.Response.StatusCode) {
                        $statusCode = [int]$_.Exception.Response.StatusCode
                    }
                } catch {}

                # If 401 Unauthorized occurs, refresh the OAuth2 client_credentials token once via Invoke-RestMethod and retry
                if ($statusCode -eq 401 -or $errMsg -match '401|Unauthorized') {
                    $token = Get-GraphMailboxAppTokenSafe -ForceRefresh
                    if (-not [string]::IsNullOrWhiteSpace($token)) {
                        $invokeParams['Headers'] = @{
                            Authorization = "Bearer $token"
                            Accept        = "application/json"
                        }
                        return (Invoke-RestMethod @invokeParams)
                    }
                }
            }
        }
    }

    # 2. Delegated fallback via Invoke-MgGraphRequest when App-Only daemon is not configured
    Ensure-MgGraphSessionActive | Out-Null
    $mgParams = @{
        Method      = $Method
        Uri         = $Uri
        ErrorAction = 'Stop'
    }
    if ($Method -eq 'POST' -or $Method -eq 'PATCH') {
        $mgParams['ContentType'] = 'application/json'
        $mgParams['Body'] = if (-not [string]::IsNullOrWhiteSpace($BodyJson)) { $BodyJson } else { "{}" }
    }
    return (Invoke-MgGraphRequest @mgParams)
}

function Get-UserForwardingAndInboxRulesSafe {
    param(
        [Parameter(Mandatory = $true)]$UserObj
    )

    $rulesList = [System.Collections.Generic.List[psobject]]::new()
    $diagnostics = [System.Collections.Generic.List[string]]::new()

    # 1. Audit Microsoft 365 Inbox Rules across any user in the tenant via Microsoft Graph Application permission REST API
    $graphCheck = Invoke-VerifyGraph -QuickStartup
    if ($graphCheck.Verified) {
        $candidateIds = [System.Collections.Generic.List[string]]::new()
        $seedCandidates = @($UserObj.GraphTargetId, $UserObj.UserPrincipalName, $UserObj.Mail, $UserObj.PrimarySmtp)
        foreach ($sc in $seedCandidates) {
            if (-not [string]::IsNullOrWhiteSpace($sc)) {
                $c = ([string]$sc).Trim()
                if (-not $candidateIds.Contains($c)) { $candidateIds.Add($c) }
            }
        }
        if ($UserObj -and $UserObj.CloudCandidates) {
            foreach ($cc in $UserObj.CloudCandidates) {
                if (-not [string]::IsNullOrWhiteSpace($cc)) {
                    $c = ([string]$cc).Trim()
                    if (-not $candidateIds.Contains($c)) { $candidateIds.Add($c) }
                }
            }
        }

        $resolvedM365User = if ($candidateIds.Count -gt 0) { $candidateIds[0] } else { [string]$UserObj.UserPrincipalName }
        try {
            $rulesResp = $null
            $lastGraphErr = $null

            foreach ($tryUser in $candidateIds) {
                try {
                    $encUid = [Uri]::EscapeDataString($tryUser)
                    $rulesUri = "https://graph.microsoft.com/v1.0/users/$encUid/mailFolders/inbox/messageRules"
                    $rulesResp = Invoke-GraphMailboxRestSafe -Method GET -Uri $rulesUri
                    $resolvedM365User = $tryUser
                    break
                } catch {
                    $lastGraphErr = $_
                }
            }

            if ($null -eq $rulesResp -and $null -ne $lastGraphErr) {
                throw $lastGraphErr
            }

            $ruleItems = if ($rulesResp -and $null -ne $rulesResp.value) { @($rulesResp.value) } else { @() }
            foreach ($r in $ruleItems) {
                if ($null -eq $r) { continue }
                $rId = [string]$r.id
                $rName = [string]$r.displayName
                $rEnabled = [bool]$r.isEnabled
                $actionParts = [System.Collections.Generic.List[string]]::new()
                $riskLevel = "NORMAL"

                if ($r.actions) {
                    if ($r.actions.forwardTo -and @($r.actions.forwardTo).Count -gt 0) {
                        $fwds = @($r.actions.forwardTo | ForEach-Object { $_.emailAddress.address }) -join ', '
                        $actionParts.Add("ForwardTo: $fwds")
                        $riskLevel = "HIGH RISK (External/Auto Forward)"
                    }
                    if ($r.actions.forwardAsAttachmentTo -and @($r.actions.forwardAsAttachmentTo).Count -gt 0) {
                        $fwdsA = @($r.actions.forwardAsAttachmentTo | ForEach-Object { $_.emailAddress.address }) -join ', '
                        $actionParts.Add("ForwardAttachment: $fwdsA")
                        $riskLevel = "HIGH RISK (Forward Attachment)"
                    }
                    if ($r.actions.redirectTo -and @($r.actions.redirectTo).Count -gt 0) {
                        $reds = @($r.actions.redirectTo | ForEach-Object { $_.emailAddress.address }) -join ', '
                        $actionParts.Add("RedirectTo: $reds")
                        $riskLevel = "HIGH RISK (Redirect Rule)"
                    }
                    if ($r.actions.delete -eq $true -or $r.actions.permanentDelete -eq $true) {
                        $actionParts.Add("DeleteMessage: True")
                        $riskLevel = "SUSPICIOUS (Auto-Delete Rule)"
                    }
                    if ($r.actions.moveToFolder) {
                        $folder = [string]$r.actions.moveToFolder
                        $actionParts.Add("MoveToFolder: $folder")
                        if ($folder -match 'RSS|Deleted|Trash|Junk|Archive|Conversation') {
                            $riskLevel = "SUSPICIOUS (Hide-Hole Folder Move)"
                        }
                    }
                    if ($r.actions.copyToFolder) {
                        $actionParts.Add("CopyToFolder: $([string]$r.actions.copyToFolder)")
                    }
                    if ($r.actions.markAsRead -eq $true) {
                        $actionParts.Add("MarkAsRead: True")
                    }
                }
                if ($actionParts.Count -eq 0) {
                    $actionParts.Add("Standard Inbox Processing")
                }

                $rulesList.Add([PSCustomObject]@{
                    Provider   = "M365 Inbox Rule"
                    RuleType   = "Inbox Rule"
                    TargetUser = $resolvedM365User
                    RuleId     = $rId
                    RuleName   = $rName
                    State      = if ($rEnabled) { "ENABLED" } else { "DISABLED" }
                    ActionDest = ($actionParts -join '; ')
                    Summary    = ($actionParts -join '; ')
                    Risk       = $riskLevel
                })
            }
            $diagnostics.Add("M365 Graph: Audited $($ruleItems.Count) inbox rule(s) for $resolvedM365User.")
        } catch {
            $diagnostics.Add("M365 Graph Rules Query Note: $($_.Exception.Message)")
        }
    } else {
        $diagnostics.Add("M365 skipped (Not Linked).")
    }

    # 2. Audit Google Workspace (Gmail) Auto-Forwarding, Forwarding Addresses & Filters via GAM7
    $gamCheck = Invoke-VerifyGAM -QuickStartup
    if ($gamCheck.Verified -and $gamCheck.Executable) {
        $gamExe = $gamCheck.Executable
        $targetGamId = if ($UserObj.GamTargetId) { $UserObj.GamTargetId } else { $UserObj.UserPrincipalName }
        try {
            $fwdCli  = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $targetGamId, 'show', 'forward') -TimeoutSeconds 8
            $addrCli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $targetGamId, 'show', 'forwardingaddresses') -TimeoutSeconds 8
            $fltCli  = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $targetGamId, 'show', 'filters') -TimeoutSeconds 8

            $fwdOut  = $fwdCli.Output
            $fwdExit = $fwdCli.ExitCode
            $addrOut = $addrCli.Output
            $fltOut  = $fltCli.Output

            if ($fwdExit -eq 0 -and $fwdOut) {
                $isFwdEnabled = $fwdOut -match 'Enabled:\s*True'
                $fwdEmailMatch = [regex]::Match($fwdOut, 'Forward To:\s*(\S+)')
                $fwdDest = if ($fwdEmailMatch.Success) { $fwdEmailMatch.Groups[1].Value } else { "None Configured" }
                $rulesList.Add([PSCustomObject]@{
                    Provider   = "Gmail Auto-Forward"
                    RuleType   = "Auto-Forward"
                    TargetUser = $targetGamId
                    RuleId     = "GMAIL-AUTO-FWD"
                    RuleName   = "Mailbox Auto-Forwarding"
                    State      = if ($isFwdEnabled) { "ENABLED" } else { "DISABLED" }
                    ActionDest = "ForwardTo: $fwdDest"
                    Summary    = "ForwardTo: $fwdDest"
                    Risk       = if ($isFwdEnabled) { "HIGH RISK (Active Auto-Forward)" } else { "NORMAL" }
                })
            }

            if ($addrOut) {
                foreach ($line in ($addrOut -split "`r?`n")) {
                    if ($line -match 'Forwarding Email:\s*(\S+)') {
                        $fAddr = $Matches[1].Trim()
                        $rulesList.Add([PSCustomObject]@{
                            Provider   = "Gmail Forwarding Address"
                            RuleType   = "Forwarding Address"
                            TargetUser = $targetGamId
                            RuleId     = $fAddr
                            RuleName   = "Registered Forwarding Destination"
                            State      = "REGISTERED"
                            ActionDest = "Destination: $fAddr"
                            Summary    = "Destination: $fAddr"
                            Risk       = "SUSPICIOUS (Verify Forwarding Address)"
                        })
                    }
                }
            }

            if ($fltOut) {
                $currentFilterId = ""
                $currentSummary = [System.Collections.Generic.List[string]]::new()
                foreach ($line in ($fltOut -split "`r?`n")) {
                    if ($line -match 'Filter:\s*(\S+)') {
                        if ($currentFilterId) {
                            $actStr = $currentSummary -join '; '
                            $risk = if ($actStr -match 'Forward|TRASH') { "HIGH RISK (Filter Forward/Trash)" } else { "NORMAL" }
                            $rulesList.Add([PSCustomObject]@{
                                Provider   = "Gmail Filter"
                                RuleType   = "Gmail Filter"
                                TargetUser = $targetGamId
                                RuleId     = $currentFilterId
                                RuleName   = "Gmail Filter $currentFilterId"
                                State      = "ENABLED"
                                ActionDest = if ($actStr) { $actStr } else { "Gmail Filter Rule" }
                                Summary    = if ($actStr) { $actStr } else { "Gmail Filter Rule" }
                                Risk       = $risk
                            })
                        }
                        $currentFilterId = $Matches[1].Trim()
                        $currentSummary.Clear()
                    } elseif ($currentFilterId -and ($line -match '^\s+(Forward|Add Label|Remove Label|Criteria|From|To|Subject):\s*(.+)$')) {
                        $currentSummary.Add("$($Matches[1]): $($Matches[2].Trim())")
                    }
                }
                if ($currentFilterId) {
                    $actStr = $currentSummary -join '; '
                    $risk = if ($actStr -match 'Forward|TRASH') { "HIGH RISK (Filter Forward/Trash)" } else { "NORMAL" }
                    $rulesList.Add([PSCustomObject]@{
                        Provider   = "Gmail Filter"
                        RuleType   = "Gmail Filter"
                        TargetUser = $targetGamId
                        RuleId     = $currentFilterId
                        RuleName   = "Gmail Filter $currentFilterId"
                        State      = "ENABLED"
                        ActionDest = if ($actStr) { $actStr } else { "Gmail Filter Rule" }
                        Summary    = if ($actStr) { $actStr } else { "Gmail Filter Rule" }
                        Risk       = $risk
                    })
                }
            }
            $diagnostics.Add("Google GAM7: Audited forwarding settings & filters for $targetGamId.")
        } catch {
            $diagnostics.Add("Google GAM7 Forwarding Audit Note: $($_.Exception.Message)")
        }
    } else {
        $diagnostics.Add("Google GAM7 skipped (Not Linked).")
    }

    return @{
        Rules       = $rulesList.ToArray()
        Diagnostics = ($diagnostics -join ' | ')
    }
}

function Disable-OrRemoveForwardingRuleSafe {
    param(
        [string]$Provider = "",
        [string]$TargetUser = "",
        [string]$RuleId = "",
        $RuleObj = $null,
        [ValidateSet("Disable", "Enable", "Delete")][string]$Operation = "Disable",
        [switch]$DeleteRule
    )

    if ($PSBoundParameters.ContainsKey('DeleteRule') -and $DeleteRule.IsPresent) {
        $Operation = "Delete"
    }

    $ruleName = ""
    $actionDest = ""
    if ($null -ne $RuleObj) {
        if ($RuleObj.PSObject.Properties['Provider'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.Provider))) {
            $Provider = [string]$RuleObj.Provider
        } elseif ($RuleObj.PSObject.Properties['Platform'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.Platform))) {
            $Provider = [string]$RuleObj.Platform
        }
        if ($RuleObj.PSObject.Properties['TargetUser'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.TargetUser))) {
            $TargetUser = [string]$RuleObj.TargetUser
        }
        if ($RuleObj.PSObject.Properties['RuleId'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.RuleId))) {
            $RuleId = [string]$RuleObj.RuleId
        }
        if ($RuleObj.PSObject.Properties['RuleName'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.RuleName))) {
            $ruleName = [string]$RuleObj.RuleName
        }
        if ($RuleObj.PSObject.Properties['ActionDest'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.ActionDest))) {
            $actionDest = [string]$RuleObj.ActionDest
        } elseif ($RuleObj.PSObject.Properties['Summary'] -and (-not [string]::IsNullOrWhiteSpace([string]$RuleObj.Summary))) {
            $actionDest = [string]$RuleObj.Summary
        }
    }

    if ([string]::IsNullOrWhiteSpace($Provider) -or [string]::IsNullOrWhiteSpace($RuleId)) {
        throw "Rule provider or Rule ID was not specified."
    }

    $displayLabel = if (-not [string]::IsNullOrWhiteSpace($ruleName)) { "'$ruleName' ($RuleId)" } else { "'$RuleId'" }

    if ($Provider -match "M365|Graph|Inbox Rule") {
        $encUser = [Uri]::EscapeDataString($TargetUser)
        $encRule = [Uri]::EscapeDataString($RuleId)
        $uri = "https://graph.microsoft.com/v1.0/users/$encUser/mailFolders/inbox/messageRules/$encRule"
        if ($Operation -eq "Delete") {
            [void](Invoke-GraphMailboxRestSafe -Method DELETE -Uri $uri)
            return @{ Status = "SUCCESS"; Details = "Deleted M365 Inbox Rule $displayLabel for '$TargetUser'." }
        } elseif ($Operation -eq "Enable") {
            $body = @{ isEnabled = $true } | ConvertTo-Json -Compress
            [void](Invoke-GraphMailboxRestSafe -Method PATCH -Uri $uri -BodyJson $body)
            return @{ Status = "SUCCESS"; Details = "Enabled M365 Inbox Rule $displayLabel for '$TargetUser'." }
        } else {
            $body = @{ isEnabled = $false } | ConvertTo-Json -Compress
            [void](Invoke-GraphMailboxRestSafe -Method PATCH -Uri $uri -BodyJson $body)
            return @{ Status = "SUCCESS"; Details = "Disabled M365 Inbox Rule $displayLabel for '$TargetUser'." }
        }
    }

    $gamCheck = Invoke-VerifyGAM -QuickStartup
    if (-not $gamCheck.Verified -or (-not $gamCheck.Executable)) {
        throw "GAM7 is not verified on this workstation."
    }
    $gamExe = $gamCheck.Executable
    if ($Provider -match "Gmail Auto-Forward") {
        if ($Operation -eq "Enable") {
            $fwdMatch = [regex]::Match($actionDest, 'ForwardTo:\s*(\S+@\S+)')
            if (-not $fwdMatch.Success) {
                throw "Cannot enable Gmail Auto-Forwarding because no forwarding destination address is configured on '$TargetUser'."
            }
            $destEmail = $fwdMatch.Groups[1].Value.Trim()
            $cli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $TargetUser, 'forward', 'on', $destEmail, 'keep') -TimeoutSeconds 12
            if ($cli.ExitCode -ne 0) { throw "gam forward on failed: $($cli.Combined)" }
            return @{ Status = "SUCCESS"; Details = "Enabled Gmail Auto-Forwarding to '$destEmail' for '$TargetUser'." }
        } else {
            $cli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $TargetUser, 'forward', 'off') -TimeoutSeconds 12
            if ($cli.ExitCode -ne 0) { throw "gam forward off failed: $($cli.Combined)" }
            return @{ Status = "SUCCESS"; Details = "Disabled Gmail Auto-Forwarding for '$TargetUser'." }
        }
    } elseif ($Provider -match "Gmail Forwarding Address") {
        if ($Operation -eq "Enable") {
            return @{ Status = "SUCCESS"; Details = "Gmail Forwarding Address '$RuleId' is already registered on '$TargetUser' (use Auto-Forward row to toggle forwarding)." }
        }
        $cli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $TargetUser, 'delete', 'forwardingaddress', $RuleId) -TimeoutSeconds 12
        if ($cli.ExitCode -ne 0) { throw "gam delete forwardingaddress failed: $($cli.Combined)" }
        return @{ Status = "SUCCESS"; Details = "Removed Gmail Forwarding Address '$RuleId' for '$TargetUser'." }
    } elseif ($Provider -match "Gmail Filter") {
        if ($Operation -eq "Enable") {
            return @{ Status = "SUCCESS"; Details = "Gmail Filter '$RuleId' is already active (Gmail filters do not have a disabled state; they are either active or deleted)." }
        }
        $cli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $TargetUser, 'delete', 'filter', $RuleId) -TimeoutSeconds 12
        if ($cli.ExitCode -ne 0) { throw "gam delete filter failed: $($cli.Combined)" }
        return @{ Status = "SUCCESS"; Details = "Deleted Gmail Filter '$RuleId' for '$TargetUser'." }
    }

    throw "Unsupported rule provider '$Provider'."
}

# RECOMMENDATION 5: Clear / Restrict Active Directory LogonWorkstations & Set/Clear Account Expiration
function Set-ADExtendedLockdownSafe {
    param(
        [Parameter(Mandatory = $true)][string]$SamAccount,
        [bool]$ExpireImmediately = $false,
        [bool]$ClearExpiration = $false,
        [bool]$ClearOrRestrictWorkstations = $false,
        [bool]$ClearWorkstations = $false,
        [string]$RestrictWorkstationsValue = "",
        [string]$WorkstationValue = "",
        [string]$Server,
        [System.Management.Automation.PSCredential]$Cred
    )

    if ([string]::IsNullOrWhiteSpace($SamAccount)) {
        throw "Target sAMAccountName is empty."
    }

    $wks = if (-not [string]::IsNullOrWhiteSpace($RestrictWorkstationsValue)) {
        $RestrictWorkstationsValue.Trim()
    } elseif (-not [string]::IsNullOrWhiteSpace($WorkstationValue)) {
        $WorkstationValue.Trim()
    } else {
        ""
    }

    $hasServer = Test-ValidADServer $Server
    $targetDomain = if ($hasServer) { $Server } else { $script:targetDomain }
    $expiryUpdated = $false
    $wksUpdated = $false
    $lastErr = ""

    # Method 1: ActiveDirectory RSAT PowerShell module (if available)
    if (Get-Command Set-ADUser -ErrorAction SilentlyContinue) {
        $p = @{}
        if ($hasServer) { $p['Server'] = $Server }
        if ($Cred) { $p['Credential'] = $Cred }

        if ($ExpireImmediately -or $ClearExpiration) {
            try {
                if ($ExpireImmediately) {
                    Set-ADAccountExpiration @p -Identity $SamAccount -DateTime (Get-Date).AddDays(-1) -ErrorAction Stop
                } elseif ($ClearExpiration) {
                    Clear-ADAccountExpiration @p -Identity $SamAccount -ErrorAction Stop
                }
                $expiryUpdated = $true
            } catch {
                $lastErr = $_.Exception.Message
            }
        }

        if ($ClearWorkstations -or (-not [string]::IsNullOrWhiteSpace($wks)) -or $ClearOrRestrictWorkstations) {
            try {
                if ($ClearWorkstations -or $ClearOrRestrictWorkstations) {
                    Set-ADUser @p -Identity $SamAccount -LogonWorkstations $null -ErrorAction Stop
                } elseif (-not [string]::IsNullOrWhiteSpace($wks)) {
                    Set-ADUser @p -Identity $SamAccount -LogonWorkstations $wks -ErrorAction Stop
                }
                $wksUpdated = $true
            } catch {
                $lastErr = $_.Exception.Message
            }
        }
    }

    # Method 2: System.DirectoryServices.AccountManagement (.NET built-in, handles 64-bit AccountExpirationDate natively)
    if ((-not $expiryUpdated -and ($ExpireImmediately -or $ClearExpiration)) -or (-not $wksUpdated -and ($ClearWorkstations -or (-not [string]::IsNullOrWhiteSpace($wks)) -or $ClearOrRestrictWorkstations))) {
        try {
            Add-Type -AssemblyName System.DirectoryServices.AccountManagement -ErrorAction SilentlyContinue
            $pCtx = if (Test-ValidADServer $targetDomain) {
                if ($Cred) {
                    New-Object System.DirectoryServices.AccountManagement.PrincipalContext([System.DirectoryServices.AccountManagement.ContextType]::Domain, $targetDomain, $Cred.UserName, $Cred.GetNetworkCredential().Password)
                } else {
                    New-Object System.DirectoryServices.AccountManagement.PrincipalContext([System.DirectoryServices.AccountManagement.ContextType]::Domain, $targetDomain)
                }
            } else {
                New-Object System.DirectoryServices.AccountManagement.PrincipalContext([System.DirectoryServices.AccountManagement.ContextType]::Domain)
            }
            $usr = $null
            try {
                $usr = [System.DirectoryServices.AccountManagement.UserPrincipal]::FindByIdentity($pCtx, [System.DirectoryServices.AccountManagement.IdentityType]::SamAccountName, $SamAccount)
            } catch {
                $usr = [System.DirectoryServices.AccountManagement.UserPrincipal]::FindByIdentity($pCtx, $SamAccount)
            }
            if ($usr) {
                if (-not $expiryUpdated) {
                    if ($ExpireImmediately) {
                        $usr.AccountExpirationDate = [DateTime]::UtcNow.AddDays(-1)
                    } elseif ($ClearExpiration) {
                        $usr.AccountExpirationDate = $null
                    }
                }
                if (-not $wksUpdated) {
                    if ($ClearWorkstations -or $ClearOrRestrictWorkstations) {
                        $usr.PermittedWorkstations.Clear()
                    } elseif (-not [string]::IsNullOrWhiteSpace($wks)) {
                        $usr.PermittedWorkstations.Clear()
                        foreach ($w in ($wks -split ',')) {
                            $cw = $w.Trim()
                            if (-not [string]::IsNullOrWhiteSpace($cw)) { [void]$usr.PermittedWorkstations.Add($cw) }
                        }
                    }
                }
                $usr.Save()
                $expiryUpdated = $true
                $wksUpdated = $true
                $usr.Dispose()
            }
            $pCtx.Dispose()
        } catch {
            $lastErr = $_.Exception.Message
        }
    }

    # Method 3: Native LDAP via System.DirectoryServices.Protocols + ADSI fallback (bypasses ADSI COM marshaling errors)
    if ((-not $expiryUpdated -and ($ExpireImmediately -or $ClearExpiration)) -or (-not $wksUpdated -and ($ClearWorkstations -or (-not [string]::IsNullOrWhiteSpace($wks)) -or $ClearOrRestrictWorkstations))) {
        $path = if (Test-ValidADServer $targetDomain) { "LDAP://$targetDomain" } else { "LDAP://" }
        $root = if ($Cred) {
            New-Object System.DirectoryServices.DirectoryEntry($path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
        } else {
            New-Object System.DirectoryServices.DirectoryEntry($path)
        }
        try {
            $searcher = New-Object System.DirectoryServices.DirectorySearcher($root)
            $searcher.Filter = "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$SamAccount))"
            [void]$searcher.PropertiesToLoad.Add("distinguishedName")
            $match = $searcher.FindOne()
            if ($null -eq $match) {
                throw "User '$SamAccount' not found in Active Directory."
            }
            $userDn = if ($match.Properties["distinguishedname"] -and $match.Properties["distinguishedname"].Count -gt 0) { [string]$match.Properties["distinguishedname"][0] } else { "" }

            # Step 3A: Direct System.DirectoryServices.Protocols LDAP ModifyRequest (RFC 4511 wire format, zero COM marshaling)
            if (-not [string]::IsNullOrWhiteSpace($userDn)) {
                try {
                    Add-Type -AssemblyName System.DirectoryServices.Protocols -ErrorAction SilentlyContinue
                    $ldapSrv = if (Test-ValidADServer $targetDomain) { $targetDomain } else { $env:USERDNSDOMAIN }
                    $ldapConn = if ($ldapSrv) {
                        New-Object System.DirectoryServices.Protocols.LdapConnection($ldapSrv)
                    } else {
                        New-Object System.DirectoryServices.Protocols.LdapConnection("")
                    }
                    if ($Cred) {
                        $ldapConn.Credential = $Cred.GetNetworkCredential()
                    }

                    # Set or Clear userWorkstations via Protocols
                    if (-not $wksUpdated -and ($ClearWorkstations -or (-not [string]::IsNullOrWhiteSpace($wks)) -or $ClearOrRestrictWorkstations)) {
                        try {
                            if ($ClearWorkstations -or $ClearOrRestrictWorkstations) {
                                $wksMod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                                $wksMod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
                                $wksMod.Name = "userWorkstations"
                                $reqWks = New-Object System.DirectoryServices.Protocols.ModifyRequest($userDn, $wksMod)
                                [void]$ldapConn.SendRequest($reqWks)
                            } else {
                                $wksMod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                                $wksMod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                                $wksMod.Name = "userWorkstations"
                                [void]$wksMod.Add($wks)
                                $reqWks = New-Object System.DirectoryServices.Protocols.ModifyRequest($userDn, $wksMod)
                                [void]$ldapConn.SendRequest($reqWks)
                            }
                            $wksUpdated = $true
                        } catch {
                            if ($ClearWorkstations -or $ClearOrRestrictWorkstations) {
                                $wksUpdated = $true
                            } else {
                                $lastErr = $_.Exception.Message
                            }
                        }
                    }

                    # Set or Clear accountExpires via Protocols
                    if (-not $expiryUpdated -and ($ExpireImmediately -or $ClearExpiration)) {
                        try {
                            $targetTicksStr = if ($ExpireImmediately) { [string]((Get-Date).AddDays(-1).ToFileTimeUtc()) } else { "0" }
                            $expMod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $expMod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                            $expMod.Name = "accountExpires"
                            [void]$expMod.Add($targetTicksStr)
                            $reqExp = New-Object System.DirectoryServices.Protocols.ModifyRequest($userDn, $expMod)
                            [void]$ldapConn.SendRequest($reqExp)
                            $expiryUpdated = $true
                        } catch {
                            $lastErr = $_.Exception.Message
                        }
                    }

                    $ldapConn.Dispose()
                } catch {
                    $lastErr = $_.Exception.Message
                }
            }

            # Step 3B: DirectoryEntry fallback if Protocols did not run or partially succeeded
            if ((-not $expiryUpdated -and ($ExpireImmediately -or $ClearExpiration)) -or (-not $wksUpdated -and ($ClearWorkstations -or (-not [string]::IsNullOrWhiteSpace($wks)) -or $ClearOrRestrictWorkstations))) {
                $userEntry = if ($Cred) {
                    New-Object System.DirectoryServices.DirectoryEntry($match.Path, $Cred.UserName, $Cred.GetNetworkCredential().Password)
                } else {
                    $match.GetDirectoryEntry()
                }
                try {
                    if (-not $wksUpdated) {
                        try {
                            if ($ClearWorkstations -or $ClearOrRestrictWorkstations) {
                                try { $userEntry.PutEx(1, "userWorkstations", $null) } catch { $userEntry.Properties["userWorkstations"].Clear() }
                            } elseif (-not [string]::IsNullOrWhiteSpace($wks)) {
                                try {
                                    $userEntry.Put("userWorkstations", $wks)
                                } catch {
                                    $userEntry.Properties["userWorkstations"].Clear()
                                    [void]$userEntry.Properties["userWorkstations"].Add($wks)
                                }
                            }
                            $userEntry.CommitChanges()
                            $wksUpdated = $true
                        } catch {
                            $lastErr = $_.Exception.Message
                        }
                    }

                    if (-not $expiryUpdated -and ($ExpireImmediately -or $ClearExpiration)) {
                        try {
                            if ($ClearExpiration) {
                                $userEntry.Properties["accountExpires"].Value = 0
                            } else {
                                $ticks = [int64]((Get-Date).AddDays(-1).ToFileTimeUtc())
                                $tickBytes = [System.BitConverter]::GetBytes($ticks)
                                $li = New-Object -ComObject LargeInteger
                                $li.LowPart  = [System.BitConverter]::ToInt32($tickBytes, 0)
                                $li.HighPart = [System.BitConverter]::ToInt32($tickBytes, 4)
                                $userEntry.Properties["accountExpires"].Value = $li
                            }
                            $userEntry.CommitChanges()
                            $expiryUpdated = $true
                        } catch {
                            $lastErr = $_.Exception.Message
                        }
                    }
                } finally {
                    if ($userEntry) { $userEntry.Dispose() }
                }
            }
        } finally {
            if ($root) { $root.Dispose() }
        }
    }

    if ((-not $expiryUpdated -and ($ExpireImmediately -or $ClearExpiration)) -and (-not $wksUpdated)) {
        throw "Failed to update AD lockdown attributes for '$SamAccount': $lastErr"
    }

    # Re-query AD to verify changes committed
    $recheck = @(Query-ADUsersSafe -LdapFilter "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$SamAccount))" -Server $Server -Cred $Cred)
    if (-not $recheck -or $recheck.Count -eq 0) {
        throw "Failed to re-query Active Directory user '$SamAccount' after updating lockdown attributes."
    }
    $resObj = $recheck[0]
    $detailsList = [System.Collections.Generic.List[string]]::new()
    if ($ExpireImmediately) {
        if ($expiryUpdated) { $detailsList.Add("accountExpires set to Expired ($($resObj.AccountExpiresDisplay))") }
        else { $detailsList.Add("accountExpires note: $lastErr") }
    } elseif ($ClearExpiration) {
        $detailsList.Add("accountExpires reset to Never Expires")
    }
    if ($ClearWorkstations) {
        $detailsList.Add("userWorkstations cleared (All Workstations Allowed)")
    } elseif (-not [string]::IsNullOrWhiteSpace($wks)) {
        $detailsList.Add("userWorkstations locked to '$wks'")
    }
    if ($detailsList.Count -eq 0) { $detailsList.Add("Active Directory extended lockdown attributes updated successfully") }
    $resObj | Add-Member -MemberType NoteProperty -Name "Details" -Value ($detailsList -join '; ') -Force
    return $resObj
}

# -----------------------------------------------------------------------------
# SIEM SECURITY EVENT LOG PULLER & PLAIN-ENGLISH EVENT CODE DECODER
# -----------------------------------------------------------------------------
function Get-DecodedEventIntelligence {
    param(
        $EventId = $null,
        [string]$RawMessage = "",
        [string]$Source = "Active Directory",
        [string]$EventCode = "",
        [string]$RawSummary = ""
    )

    $logonTypeMap = @{
        "2"  = "Type 2: Interactive (Local Console Keyboard/Screen)"
        "3"  = "Type 3: Network (SMB Share / RPC)"
        "4"  = "Type 4: Batch (Scheduled Task)"
        "5"  = "Type 5: Service (Windows Service)"
        "7"  = "Type 7: Unlock (Workstation Unlock)"
        "8"  = "Type 8: NetworkCleartext (IIS / Basic Auth)"
        "9"  = "Type 9: NewCredentials (RunAs /NetOnly)"
        "10" = "Type 10: RemoteInteractive (RDP / Terminal Services)"
        "11" = "Type 11: CachedInteractive (Cached Domain Logon)"
    }

    $kerbErrMap = @{
        "0x0"  = "0x0 (Success - Ticket Granted)"
        "0x6"  = "0x6 (Client not found in Kerberos database)"
        "0x12" = "0x12 (Credentials revoked: Account Disabled, Expired, or Locked Out)"
        "0x17" = "0x17 (User password has expired)"
        "0x18" = "0x18 (Pre-Authentication Failed: Wrong Password or Stale Cached Credential)"
        "0x20" = "0x20 (Kerberos Ticket Expired)"
    }

    $ntlmSubMap = @{
        "0xc000006a" = "0xC000006A (Wrong Password / Bad Password)"
        "0xc0000064" = "0xC0000064 (Username does not exist)"
        "0xc0000234" = "0xC0000234 (Account Locked Out)"
        "0xc0000072" = "0xC0000072 (Account Disabled)"
        "0xc0000193" = "0xC0000193 (Account Expired)"
        "0xc0000070" = "0xC0000070 (Workstation Restriction - LogonWorkstations Blocked)"
        "0xc0000071" = "0xC0000071 (Password Expired)"
    }

    $combinedText = "$RawMessage $RawSummary"
    $logonTypeDesc = ""
    if ($combinedText -match 'Logon Type:\s+(\d+)') {
        $lt = $Matches[1]
        $logonTypeDesc = if ($logonTypeMap.ContainsKey($lt)) { $logonTypeMap[$lt] } else { "Logon Type $lt" }
    }

    $srcHost = ""
    if ($combinedText -match 'Workstation Name:\s+([^\r\n\s]+)') { $srcHost = $Matches[1] }
    elseif ($combinedText -match 'Caller Computer Name:\s+([^\r\n\s]+)') { $srcHost = $Matches[1] }
    elseif ($combinedText -match 'Client Address:\s+([^\r\n\s]+)') { $srcHost = $Matches[1] }
    if ($combinedText -match 'Source Network Address:\s+([^\r\n\s-]+)') {
        $ip = $Matches[1]
        $srcHost = if ($srcHost -and $srcHost -ne $ip) { "$srcHost ($ip)" } else { $ip }
    }
    if ([string]::IsNullOrWhiteSpace($srcHost)) { $srcHost = "Local / DC" }

    $subCodeDesc = ""
    if ($combinedText -match '(0x[0-9a-fA-F]+)') {
        $hex = $Matches[1].ToLowerInvariant()
        if ($ntlmSubMap.ContainsKey($hex)) { $subCodeDesc = $ntlmSubMap[$hex] }
        elseif ($kerbErrMap.ContainsKey($hex)) { $subCodeDesc = $kerbErrMap[$hex] }
        else { $subCodeDesc = $hex }
    }

    # Normalize code lookup
    $targetCode = if (-not [string]::IsNullOrWhiteSpace($EventCode)) {
        $EventCode.Trim()
    } elseif ($null -ne $EventId -and [string]$EventId -ne "0") {
        [string]$EventId
    } else {
        "UNKNOWN"
    }

    # Match Active Directory / Windows Security Event IDs
    switch ($targetCode) {
        "4624" {
            $sev = if ($logonTypeDesc -match 'Type 10|Type 9') { "CRITICAL" } else { "INFO" }
            $codeLabel = if ($logonTypeDesc) { "4624 ($($logonTypeDesc.Split(':')[0]))" } else { "4624 (Logon Success)" }
            return @{
                EventCode = $codeLabel
                Title     = "Logon Success"
                Severity  = $sev
                SourceIP  = $srcHost
                Meaning   = "Successful Windows logon$(if($logonTypeDesc){' — ' + $logonTypeDesc})."
                Decision  = "Verify if '$srcHost' is an authorized workstation for this user. If unrecognized or Type 10 (RDP), revoke sessions and disable/expire the account."
            }
        }
        "4625" {
            return @{
                EventCode = "4625 (Failed Logon)"
                Title     = "Failed Logon"
                Severity  = "WARNING"
                SourceIP  = $srcHost
                Meaning   = "Failed Windows logon attempt$(if($subCodeDesc){': ' + $subCodeDesc})$(if($logonTypeDesc){' [' + $logonTypeDesc + ']'})."
                Decision  = "Check Source '$srcHost'. If occurring BEFORE password reset, indicates password spray/brute-force. If AFTER reset, '$srcHost' has a stale cached credential or active attacker retry."
            }
        }
        "4740" {
            return @{
                EventCode = "4740 (Account Lockout)"
                Title     = "Account Lockout"
                Severity  = "CRITICAL"
                SourceIP  = $srcHost
                Meaning   = "Active Directory account was locked out by repeated bad password attempts."
                Decision  = "Caller Computer '$srcHost' triggered the lockout. Inspect '$srcHost' (workstation, VPN gateway, or Exchange) for saved credentials or active brute-force attack."
            }
        }
        "4768" {
            return @{
                EventCode = "4768 (Kerberos TGT)"
                Title     = "Kerberos TGT Request"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "Kerberos Authentication Ticket (TGT) requested$(if($subCodeDesc){' [' + $subCodeDesc + ']'})."
                Decision  = "Confirms active domain authentication from '$srcHost'. To immediately block new Kerberos TGTs, use '4. Disable Account' or 'Expire AD Account'."
            }
        }
        "4769" {
            return @{
                EventCode = "4769 (Kerberos TGS)"
                Title     = "Kerberos Service Ticket"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "Kerberos Service Ticket (TGS) requested for a domain resource$(if($subCodeDesc){' [' + $subCodeDesc + ']'})."
                Decision  = "Shows lateral resource access from '$srcHost'. Resetting the user's AD password and expiring/disabling the account invalidates further ticket renewal."
            }
        }
        "4771" {
            return @{
                EventCode = "4771 (Kerb Pre-Auth Fail)"
                Title     = "Pre-Auth Failure"
                Severity  = "WARNING"
                SourceIP  = $srcHost
                Meaning   = "Kerberos Pre-Authentication failed$(if($subCodeDesc){': ' + $subCodeDesc})."
                Decision  = "0x18 means wrong password/stale credential on '$srcHost'; 0x12 confirms the account is disabled, expired, or locked out."
            }
        }
        "4776" {
            return @{
                EventCode = "4776 (NTLM Validation)"
                Title     = "NTLM Credential Validation"
                Severity  = "WARNING"
                SourceIP  = $srcHost
                Meaning   = "Domain Controller validated NTLM credentials from '$srcHost'$(if($subCodeDesc){' [' + $subCodeDesc + ']'})."
                Decision  = "Legacy NTLM authentication detected from '$srcHost'. If unexpected, restrict LogonWorkstations or disable the AD account."
            }
        }
        "4648" {
            return @{
                EventCode = "4648 (Explicit Creds)"
                Title     = "Explicit Credentials Logon"
                Severity  = "CRITICAL"
                SourceIP  = $srcHost
                Meaning   = "Logon attempted using explicit credentials (RunAs, Scheduled Task, or lateral movement) from '$srcHost'."
                Decision  = "HIGH PRIORITY: Verify whether an admin or script legitimately ran RunAs on '$srcHost'. Otherwise treat as lateral movement and run Full Playbook."
            }
        }
        "4778" {
            return @{
                EventCode = "4778 (RDP Reconnected)"
                Title     = "RDP Session Reconnected"
                Severity  = "CRITICAL"
                SourceIP  = $srcHost
                Meaning   = "Remote Desktop / Terminal Services session was reconnected from '$srcHost'."
                Decision  = "Confirms an active interactive RDP session. Reset password, disable AD account, and restrict LogonWorkstations immediately."
            }
        }
        "4779" {
            return @{
                EventCode = "4779 (RDP Disconnected)"
                Title     = "RDP Session Disconnected"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "Remote Desktop / Terminal Services session disconnected (session may still remain running in background)."
                Decision  = "User disconnected from RDP on '$srcHost' without logging off. Disable account and expire AD account to prevent reconnection."
            }
        }
        "4720" {
            return @{
                EventCode = "4720 (User Created)"
                Title     = "User Account Created"
                Severity  = "WARNING"
                SourceIP  = $srcHost
                Meaning   = "Active Directory user account was created."
                Decision  = "Confirm account creation was authorized by IT provisioning."
            }
        }
        "4722" {
            return @{
                EventCode = "4722 (Account Enabled)"
                Title     = "Account Enabled"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "Active Directory user account was enabled."
                Decision  = "Confirms when the user account was enabled in Active Directory."
            }
        }
        "4723" {
            return @{
                EventCode = "4723 (User Pwd Change)"
                Title     = "User Password Change"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "User attempted to change their own Active Directory password."
                Decision  = "If unrecognized by the user, an attacker with the current password may be rotating credentials."
            }
        }
        "4724" {
            return @{
                EventCode = "4724 (Admin Pwd Reset)"
                Title     = "Admin Password Reset"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "Administrator reset the user's Active Directory password."
                Decision  = "Confirms administrative password reset (Step 1 Containment) committed on the Domain Controller."
            }
        }
        "4725" {
            return @{
                EventCode = "4725 (Account Disabled)"
                Title     = "Account Disabled"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "Active Directory user account was disabled."
                Decision  = "Confirms administrative account disablement (Step 4 Containment) committed on the Domain Controller."
            }
        }
        "4738" {
            return @{
                EventCode = "4738 (User Modified)"
                Title     = "User Object Modified"
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = "User account attributes were modified in Active Directory (e.g., UAC, expiration, or LogonWorkstations)."
                Decision  = "Correlate timestamp with your Audit Trail tab to confirm authorized containment changes."
            }
        }
        # Microsoft Entra ID Cloud Codes
        "50173" {
            return @{
                EventCode = "50173 (Fresh Token Required / Sessions Revoked)"
                Title     = "Fresh Token Required"
                Severity  = "WARNING"
                SourceIP  = "login.microsoftonline.com"
                Meaning   = "Entra rejected refresh token because sessions were revoked by admin (Revoke-MgUserSignInSession)."
                Decision  = "Confirms that Step 2 Revoke Sessions was effective. User must re-authenticate with credentials and MFA."
            }
        }
        "50057" {
            return @{
                EventCode = "50057 (User Account Disabled)"
                Title     = "Account Disabled"
                Severity  = "CRITICAL"
                SourceIP  = "login.microsoftonline.com"
                Meaning   = "Sign-in was blocked because user account is disabled in Microsoft Entra ID (accountEnabled = false)."
                Decision  = "Confirms that 'Block Entra Sign-In' on Tab 3 successfully stopped cloud logins."
            }
        }
        "50126" {
            return @{
                EventCode = "50126 (Invalid Password)"
                Title     = "Invalid Password"
                Severity  = "WARNING"
                SourceIP  = "login.microsoftonline.com"
                Meaning   = "Sign-in failed due to an incorrect username or password in cloud authentication."
                Decision  = "Check source IP. If repeated from non-corporate IPs, indicates an active credential stuffing attempt."
            }
        }
        "50053" {
            return @{
                EventCode = "50053 (Smart Lockout)"
                Title     = "Entra Smart Lockout"
                Severity  = "CRITICAL"
                SourceIP  = "login.microsoftonline.com"
                Meaning   = "Account locked by Entra Smart Lockout due to excessive bad password attempts."
                Decision  = "Active cloud attack detected. Keep sign-in blocked and verify registered MFA factors."
            }
        }
        "50076" {
            return @{
                EventCode = "50076 (MFA Required)"
                Title     = "MFA Required"
                Severity  = "INFO"
                SourceIP  = "login.microsoftonline.com"
                Meaning   = "User prompted to perform Multi-Factor Authentication during cloud sign-in."
                Decision  = "Verify whether user was prompted legitimately or if prompt was triggered by attacker."
            }
        }
        "53003" {
            return @{
                EventCode = "53003 (Conditional Access Block)"
                Title     = "Conditional Access Block"
                Severity  = "WARNING"
                SourceIP  = "login.microsoftonline.com"
                Meaning   = "Access blocked by an Entra Conditional Access policy (e.g. untrusted country or non-compliant device)."
                Decision  = "Inspect sign-in location and device compliance state."
            }
        }
        "RISK_DETECTION" {
            return @{
                EventCode = "RISK_DETECTION (Entra Identity Protection)"
                Title     = "Identity Protection Risk"
                Severity  = "CRITICAL"
                SourceIP  = "Microsoft Entra Risk Engine"
                Meaning   = "Entra Identity Protection flagged anomalous token, impossible travel, anonymous IP, or leaked credential."
                Decision  = "CRITICAL CLOUD THREAT: Click 'Block Entra Sign-In', 'Wipe Cloud MFA & Tokens', and 'Audit M365 & Gmail Rules'."
            }
        }
        "AUDIT_MFA_CHANGE" {
            return @{
                EventCode = "AUDIT_MFA_CHANGE (Auth Method Modified)"
                Title     = "Authentication Method Change"
                Severity  = "CRITICAL"
                SourceIP  = "Microsoft Entra Audit"
                Meaning   = "An authentication factor (Authenticator, FIDO2, phone, or software token) was registered or modified."
                Decision  = "SUSPICIOUS PERSISTENCE: If not initiated by user, an attacker registered a persistence factor. Run 'Wipe Cloud MFA & Tokens'."
            }
        }
        "OAUTH_CONSENT_GRANT" {
            return @{
                EventCode = "OAUTH_CONSENT_GRANT (App Permission Consented)"
                Title     = "OAuth App Consent"
                Severity  = "CRITICAL"
                SourceIP  = "Microsoft Entra Audit"
                Meaning   = "A third-party application was granted delegated or application API permissions to user data."
                Decision  = "If unrecognized application, click 'Wipe Cloud MFA & Tokens' on Tab 3 to delete all OAuth permission grants."
            }
        }
        # Google Workspace Codes
        "LOGIN_CHALLENGE" {
            return @{
                EventCode = "LOGIN_CHALLENGE (Google 2-Step Challenge)"
                Title     = "Google 2-Step Challenge"
                Severity  = "WARNING"
                SourceIP  = "Google Login Audit"
                Meaning   = "Google Workspace presented an extra 2-Step Verification prompt due to unfamiliar IP or device."
                Decision  = "Check IP address. If unrecognized, run 'Revoke Google Sessions' and 'Suspend Google User'."
            }
        }
        "LOGIN_FAILURE" {
            return @{
                EventCode = "LOGIN_FAILURE (Google Login Failed)"
                Title     = "Google Login Failed"
                Severity  = "WARNING"
                SourceIP  = "Google Login Audit"
                Meaning   = "Failed Google Workspace login attempt (bad password or failed challenge)."
                Decision  = "Check IP address and timestamp. If repeated, indicates brute-force or credential stuffing."
            }
        }
        "OAUTH_TOKEN_GRANT" {
            return @{
                EventCode = "OAUTH_TOKEN_GRANT (Google Third-Party App)"
                Title     = "Google OAuth App Grant"
                Severity  = "WARNING"
                SourceIP  = "Google Security Audit"
                Meaning   = "Authorized Google OAuth token granted to an external application or client."
                Decision  = "If application is unrecognized, click 'Wipe Cloud MFA & Tokens' ('gam user deprovision') to revoke all tokens."
            }
        }
        "USER_SUSPENDED" {
            return @{
                EventCode = "USER_SUSPENDED (Google Account Suspended)"
                Title     = "Google Account Suspended"
                Severity  = "WARNING"
                SourceIP  = "Google Admin Audit"
                Meaning   = "Google Workspace account suspended via Admin SDK / GAM7."
                Decision  = "Confirms that 'Suspend Google User' on Tab 3 successfully blocked access."
            }
        }
        "SIGN_OUT_USER" {
            return @{
                EventCode = "SIGN_OUT_USER (Google Sessions Revoked)"
                Title     = "Google Sessions Revoked"
                Severity  = "INFO"
                SourceIP  = "Google Admin Audit"
                Meaning   = "Google Workspace cookies and active web sessions revoked via GAM7."
                Decision  = "Confirms that Step 3 Revoke Google Sessions successfully signed out all active devices."
            }
        }
        default {
            $codeLabel = if ($targetCode -ne "UNKNOWN") { "$targetCode" } else { "Event Telemetry" }
            return @{
                EventCode = $codeLabel
                Title     = $codeLabel
                Severity  = "INFO"
                SourceIP  = $srcHost
                Meaning   = if ($combinedText) { $combinedText } else { "Security event $codeLabel recorded." }
                Decision  = "Inspect event details and correlate with incident response timeline."
            }
        }
    }
}

function Get-UserSecurityEventsSafe {
    param(
        [Parameter(Mandatory = $true)]$UserObj,
        [int]$HoursBack = 24,
        [string]$SourceFilter = "All Sources",
        [string]$Server = "",
        [System.Management.Automation.PSCredential]$Cred = $null
    )

    $eventsList = [System.Collections.Generic.List[psobject]]::new()
    $startTime = (Get-Date).AddHours(-1 * [Math]::Abs($HoursBack))
    $sam = [string]$UserObj.SamAccountName
    $upn = [string]$UserObj.UserPrincipalName
    $targetGraphId = if ($UserObj.GraphTargetId) { [string]$UserObj.GraphTargetId } else { $upn }
    $targetGamId = if ($UserObj.GamTargetId) { [string]$UserObj.GamTargetId } else { $upn }

    # 1. Pull Active Directory Multi-DC Non-Replicated Telemetry + Bounded (<4.5s) Multi-DC Windows Security Event Logs
    if ($SourceFilter -eq "All Sources" -or $SourceFilter -match "Windows|AD|Active Directory") {
        $discoveredDCs = @(Get-DomainControllersListSafe -PreferredServer $Server)
        $dcCountText = if ($discoveredDCs.Count -gt 1) { " across $($discoveredDCs.Count) Domain Controllers ($($discoveredDCs -join ', '))" } else { "" }
        if (Get-Command Write-AppLog -ErrorAction SilentlyContinue) {
            Write-AppLog "[Event Triage 1/3] Querying Active Directory security state & non-replicated logon/lockout events for '$sam'$dcCountText..." "INFO"
            if ($form) { [System.Windows.Forms.Application]::DoEvents() }
        }

        $seenAdEventKeys = @{}

        # 1A. Query live LDAP security telemetry + multi-DC non-replicated attributes (lastLogon, badPwdCount, badPasswordTime)
        try {
            $multiDc = Get-MultiDCUserNonReplicatedTelemetrySafe -SamAccountName $sam -Server $Server -Cred $Cred
            $adSnap = @(Query-ADUsersSafe -LdapFilter "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$sam))" -Server $Server -Cred $Cred)
            if ($adSnap -and $adSnap.Count -gt 0) {
                $uSnap = $adSnap[0]
                $isLockedAny = ([bool]$uSnap.LockedOut) -or ([bool]$multiDc.IsLockedOutAnyDC)
                $bestLogonStr = if ($multiDc.LatestLogonDisplay -and $multiDc.LatestLogonDisplay -ne "Never / Unknown") {
                    [string]$multiDc.LatestLogonDisplay
                } elseif ($uSnap.LastLogonDisplay -and $uSnap.LastLogonDisplay -ne "Never / Unknown") {
                    [string]$uSnap.LastLogonDisplay
                } else {
                    (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
                }
                $dcsQueriedStr = if ($multiDc.QueriedDCs -and $multiDc.QueriedDCs.Count -gt 0) {
                    $multiDc.QueriedDCs -join ', '
                } elseif ($Server) {
                    $Server
                } else {
                    "Domain Controller"
                }

                $adSev = if ($isLockedAny) { "CRITICAL" } elseif (-not $uSnap.Enabled) { "WARNING" } else { "INFO" }
                $adCode = if ($isLockedAny) { "4740 (AD Locked Out)" } elseif (-not $uSnap.Enabled) { "4725 (AD Disabled)" } else { "AD_SECURITY_STATE" }
                $eventsList.Add([PSCustomObject]@{
                    Timestamp = $bestLogonStr
                    Source    = "Active Directory"
                    EventCode = $adCode
                    Severity  = $adSev
                    HostOrIP  = $dcsQueriedStr
                    Meaning   = "AD Enabled: $($uSnap.Enabled) | LockedOut: $isLockedAny | LatestLogon (All DCs): $bestLogonStr | TotalBadPwd (All DCs): $($multiDc.TotalBadPwdCount) | PwdLastSet: $($uSnap.PasswordLastSetFormatted) | Workstations: $($uSnap.LogonWorkstationsDisplay)"
                    Decision  = if ($isLockedAny) { "CRITICAL: Account is locked out in AD. Check for brute-force or stale service credentials." } elseif (-not $uSnap.Enabled) { "Account is currently disabled in Active Directory." } else { "Account is active in AD (queried DCs: $dcsQueriedStr). Use Tab 2 to reset password/disable or Tab 3 to expire & lock workstations." }
                    RawDetail = "sAMAccountName: $sam`r`nUPN: $upn`r`nQueried DCs: $dcsQueriedStr`r`nTrue Latest Logon Across DCs: $bestLogonStr`r`nTotal Bad Password Count Across DCs: $($multiDc.TotalBadPwdCount)`r`nEnabled: $($uSnap.Enabled)`r`nLockedOut: $isLockedAny`r`nPasswordLastSet: $($uSnap.PasswordLastSetFormatted)`r`nAccountExpires: $($uSnap.AccountExpiresDisplay)`r`nLogonWorkstations: $($uSnap.LogonWorkstationsDisplay)"
                })

                # Surface non-replicated per-DC badPasswordTime attributes within lookback window (deduplicated per DC + timestamp)
                if ($multiDc.PerDCBadPasswords -and $multiDc.PerDCBadPasswords.Count -gt 0) {
                    foreach ($bp in $multiDc.PerDCBadPasswords) {
                        if ($null -eq $bp) { continue }
                        if ($bp.BadTime -ge $startTime -or $bp.BadPwdCount -gt 0) {
                            $dedupBadKey = "4625|$($bp.BadTimeStr)|$($bp.ShortDC)"
                            if (-not $seenAdEventKeys.ContainsKey($dedupBadKey)) {
                                $seenAdEventKeys[$dedupBadKey] = $true
                                $eventsList.Add([PSCustomObject]@{
                                    Timestamp = [string]$bp.BadTimeStr
                                    Source    = "Active Directory"
                                    EventCode = "4625 / AD_BAD_PWD (Failed Password on DC)"
                                    Severity  = if ($bp.BadPwdCount -ge 3) { "CRITICAL" } else { "WARNING" }
                                    HostOrIP  = [string]$bp.DC
                                    Meaning   = "Non-replicated badPasswordTime recorded on Domain Controller '$($bp.ShortDC)' (Current DC badPwdCount: $($bp.BadPwdCount))."
                                    Decision  = "Confirm whether user mistyped password or if an endpoint/attacker is attempting bad passwords against $($bp.ShortDC)."
                                    RawDetail = "Domain Controller: $($bp.DC)`r`nNon-Replicated badPasswordTime: $($bp.BadTimeStr)`r`nNon-Replicated badPwdCount on $($bp.ShortDC): $($bp.BadPwdCount)"
                                })
                            }
                        }
                    }
                }
            }
        } catch {}

        # 1B. Fast bounded query (max 4.5 seconds) across all discovered Domain Controllers for non-replicated Security Event IDs with strict deduplication
        try {
            $targetDcArray = if ($discoveredDCs -and $discoveredDCs.Count -gt 0) { @($discoveredDCs | Select-Object -First 5) } else { @("") }
            $winJob = Start-Job -ScriptBlock {
                param($SamName, $UpnName, $StartDt, $DcServers)
                $out = @()
                $xpath = "*[System[(EventID=4624 or EventID=4625 or EventID=4740 or EventID=4768 or EventID=4771 or EventID=4776 or EventID=4720 or EventID=4722 or EventID=4723 or EventID=4724 or EventID=4725 or EventID=4738 or EventID=4648 or EventID=4778)]] and *[EventData[Data='$SamName']]"
                foreach ($dcHost in $DcServers) {
                    try {
                        $gwParams = @{
                            LogName     = 'Security'
                            FilterXPath = $xpath
                            MaxEvents   = 15
                            ErrorAction = 'Stop'
                        }
                        if (-not [string]::IsNullOrWhiteSpace($dcHost)) {
                            $gwParams['ComputerName'] = $dcHost
                        }
                        $evts = @(Get-WinEvent @gwParams)
                        foreach ($e in $evts) {
                            if ($e.TimeCreated -and $e.TimeCreated -lt $StartDt) { continue }
                            $out += [PSCustomObject]@{
                                Id       = [int]$e.Id
                                RecordId = [int64]$e.RecordId
                                Machine  = if ($e.MachineName) { [string]$e.MachineName } elseif ($dcHost) { [string]$dcHost } else { $env:COMPUTERNAME }
                                Time     = $e.TimeCreated.ToString("yyyy-MM-dd HH:mm:ss")
                                Message  = [string]$e.Message
                            }
                        }
                    } catch {}
                }
                return $out
            } -ArgumentList $sam, $upn, $startTime, $targetDcArray

            $swWinJob = [System.Diagnostics.Stopwatch]::StartNew()
            while ($swWinJob.Elapsed.TotalSeconds -lt 4.0) {
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }
                if ($winJob.State -ne 'Running') { break }
                Start-Sleep -Milliseconds 100
            }
            if ($winJob.State -eq 'Completed') {
                $jobEvts = @(Receive-Job -Job $winJob -ErrorAction SilentlyContinue)
                foreach ($je in $jobEvts) {
                    if (-not $je -or -not $je.Id) { continue }
                    $decoded = Get-DecodedEventIntelligence -EventId ([int]$je.Id) -RawMessage ([string]$je.Message)
                    $sevNorm = if ($decoded.Severity -eq "HIGH") { "WARNING" } else { $decoded.Severity }
                    $hostOrIpVal = if ($decoded.SourceIP -and $decoded.SourceIP -ne "Local / Unknown Host") {
                        "$($decoded.SourceIP) (via $(($je.Machine -split '\.')[0]))"
                    } else {
                        [string]$je.Machine
                    }

                    # Strict deduplication so identical events across DCs or queries are never duplicated
                    $dedupKey = "$($je.Id)|$($je.Time)|$($decoded.SourceIP)|$(($je.Machine -split '\.')[0])"
                    if ($seenAdEventKeys.ContainsKey($dedupKey)) { continue }
                    $seenAdEventKeys[$dedupKey] = $true

                    $eventsList.Add([PSCustomObject]@{
                        Timestamp = [string]$je.Time
                        Source    = "Active Directory"
                        EventCode = $decoded.EventCode
                        Severity  = $sevNorm
                        HostOrIP  = $hostOrIpVal
                        Meaning   = $decoded.Meaning
                        Decision  = $decoded.Decision
                        RawDetail = "Domain Controller: $($je.Machine)`r`n" + [string]$je.Message
                    })
                }
            }
            Remove-Job -Job $winJob -Force -ErrorAction SilentlyContinue
        } catch {}
    }

    # 2. Pull Microsoft Entra ID Audit, Sign-In, Risk Detections & Persistence Artifacts (< 4 seconds via non-blocking Graph REST)
    if ($SourceFilter -eq "All Sources" -or $SourceFilter -match "Entra|365") {
        $graphCheck = Invoke-VerifyGraph -QuickStartup
        if ($graphCheck.Verified) {
            if (Get-Command Write-AppLog -ErrorAction SilentlyContinue) {
                Write-AppLog "[Event Triage 2/3] Querying Microsoft Entra ID sign-ins, risk detections & OAuth grants for '$targetGraphId'..." "INFO"
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }
            }
            try {
                [void](Upgrade-GraphMailboxAuditorAppRolesIfNeededSafe)
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }

                $graphUser = Resolve-GraphUserObjectSafe -PrimaryId $targetGraphId -CandidateIds $UserObj.CloudCandidates -SamAccountName $sam
                $gUid = [string]$graphUser.id
                $encUid = [Uri]::EscapeDataString($gUid)
                $gUpn = if ($graphUser.userPrincipalName) { [string]$graphUser.userPrincipalName } else { $targetGraphId }
                $acctEnabled = if ($null -ne $graphUser.accountEnabled) { [bool]$graphUser.accountEnabled } else { $true }
                $validFrom = if ($graphUser.signInSessionsValidFromDateTime) {
                    ([DateTime]$graphUser.signInSessionsValidFromDateTime).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss")
                } else { (Get-Date).ToString("yyyy-MM-dd HH:mm:ss") }

                $eventsList.Add([PSCustomObject]@{
                    Timestamp = $validFrom
                    Source    = "Microsoft Entra ID"
                    EventCode = if ($acctEnabled) { "StsRefreshTokenValidFrom" } else { "50057 (Sign-In Blocked)" }
                    Severity  = if ($acctEnabled) { "INFO" } else { "WARNING" }
                    HostOrIP  = "graph.microsoft.com"
                    Meaning   = "Entra ID SignInSessionsValidFromDateTime = $validFrom | AccountEnabled = $acctEnabled ($gUpn)."
                    Decision  = if ($acctEnabled) { "All M365 refresh tokens issued prior to $validFrom are rejected with Entra Error 50173. Use 'Block Entra Sign-In' on Tab 3 to block new cloud sign-ins." } else { "Entra ID sign-in is currently BLOCKED (Entra Error 50057 will be returned on any login attempt)." }
                    RawDetail = "UserPrincipalName: $gUpn`r`nAccountEnabled: $acctEnabled`r`nSignInSessionsValidFromDateTime: $validFrom"
                })
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }

                # 2A. Entra ID Identity Protection Risk Detections
                try {
                    $safeUpn = $gUpn.Replace("'", "''")
                    $riskUri = "https://graph.microsoft.com/v1.0/identityProtection/riskDetections?`$filter=userPrincipalName eq '$safeUpn'&`$top=10"
                    $riskResp = Invoke-GraphMailboxRestSafe -Method GET -Uri $riskUri -TimeoutSec 6
                    if ($riskResp -and $riskResp.value) {
                        foreach ($rd in @($riskResp.value)) {
                            if ($null -eq $rd) { continue }
                            $rTime = try { ([DateTime]$rd.activityDateTime).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") } catch { [string]$rd.activityDateTime }
                            $rType = [string]$rd.riskEventType
                            $rLevel = [string]$rd.riskLevel
                            $rState = [string]$rd.riskState
                            $rIp = if ($rd.ipAddress) { [string]$rd.ipAddress } else { "Cloud Risk Engine" }
                            $sev = if ($rLevel -match 'high|medium') { "CRITICAL" } else { "WARNING" }
                            $eventsList.Add([PSCustomObject]@{
                                Timestamp = $rTime
                                Source    = "Microsoft Entra ID"
                                EventCode = "RISK: $rType"
                                Severity  = $sev
                                HostOrIP  = $rIp
                                Meaning   = "Suspicious Entra Risk Detection '$rType' (RiskLevel: $rLevel, State: $rState) for $gUpn."
                                Decision  = "CRITICAL CLOUD INDICATOR: Run 'Block Entra Sign-In', 'Wipe Cloud MFA & Tokens', and 'Audit M365 & Gmail Rules' on Tab 3."
                                RawDetail = ($rd | ConvertTo-Json -Depth 4)
                            })
                        }
                    }
                } catch {}
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }

                # 2B. Entra ID Active OAuth2 Permission Grants
                try {
                    $grantsResp = Invoke-GraphMailboxRestSafe -Method GET -Uri "https://graph.microsoft.com/v1.0/users/$encUid/oauth2PermissionGrants" -TimeoutSec 6
                    if ($grantsResp -and $grantsResp.value -and @($grantsResp.value).Count -gt 0) {
                        foreach ($g in @($grantsResp.value)) {
                            if ($null -eq $g) { continue }
                            $scopeStr = [string]$g.scope
                            $isHighRiskScope = $scopeStr -match 'Mail\.ReadWrite|Mail\.Send|Files\.ReadWrite|Directory\.ReadWrite'
                            $eventsList.Add([PSCustomObject]@{
                                Timestamp = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
                                Source    = "Microsoft Entra ID"
                                EventCode = "OAuth2PermissionGrant"
                                Severity  = if ($isHighRiskScope) { "CRITICAL" } else { "WARNING" }
                                HostOrIP  = "ClientId: $($g.clientId)"
                                Meaning   = "Active OAuth App Grant (Scopes: $scopeStr)."
                                Decision  = "If this OAuth app grant is unfamiliar or requests Mail/Files scopes, click 'Wipe Cloud MFA & Tokens' on Tab 3 to revoke all consented OAuth grants."
                                RawDetail = ($g | ConvertTo-Json -Depth 4)
                            })
                        }
                    }
                } catch {}
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }

                # 2C. Query Entra Directory Audits (Top 15)
                try {
                    $safeUpn = $gUpn.Replace("'", "''")
                    $auditUri = "https://graph.microsoft.com/v1.0/auditLogs/directoryAudits?`$filter=targetResources/any(t:t/userPrincipalName eq '$safeUpn')&`$top=15"
                    $auditResp = Invoke-GraphMailboxRestSafe -Method GET -Uri $auditUri -TimeoutSec 6
                    if ($auditResp -and $auditResp.value) {
                        foreach ($a in @($auditResp.value)) {
                            if ($null -eq $a) { continue }
                            $actName = [string]$a.activityDisplayName
                            $actTime = try { ([DateTime]$a.activityDateTime).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") } catch { [string]$a.activityDateTime }
                            $resType = [string]$a.result
                            $isSuspiciousAudit = $actName -match 'security info|Consent|OAuth|role|delegation|forwarding'
                            $sev = if ($isSuspiciousAudit) { "CRITICAL" } elseif ($actName -match 'Revoke|Disable|Reset') { "WARNING" } else { "INFO" }
                            $dec = if ($isSuspiciousAudit) {
                                "SUSPICIOUS PERSISTENCE: '$actName' may indicate an attacker registered rogue MFA or consented to an OAuth app. Run 'Wipe Cloud MFA & Tokens'."
                            } else {
                                "Correlate this Entra ID audit event with your incident containment timeline."
                            }
                            $eventsList.Add([PSCustomObject]@{
                                Timestamp = $actTime
                                Source    = "Microsoft Entra ID"
                                EventCode = $actName
                                Severity  = $sev
                                HostOrIP  = "Entra Audit Log"
                                Meaning   = "Entra Audit Activity '$actName' (Result: $resType) for $gUpn."
                                Decision  = $dec
                                RawDetail = ($a | ConvertTo-Json -Depth 4)
                            })
                        }
                    }
                } catch {}
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }

                # 2D. Query Entra Sign-In Logs (Top 15)
                try {
                    $safeUpn = $gUpn.Replace("'", "''")
                    $signInUri = "https://graph.microsoft.com/v1.0/auditLogs/signIns?`$filter=userPrincipalName eq '$safeUpn'&`$top=15"
                    $signInResp = Invoke-GraphMailboxRestSafe -Method GET -Uri $signInUri -TimeoutSec 8
                    if ($signInResp -and $signInResp.value) {
                        foreach ($s in @($signInResp.value)) {
                            if ($null -eq $s) { continue }
                            $sTime = try { ([DateTime]$s.createdDateTime).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") } catch { [string]$s.createdDateTime }
                            $errCode = if ($s.status -and $null -ne $s.status.errorCode) { [int]$s.status.errorCode } else { 0 }
                            $failReason = if ($s.status -and $s.status.failureReason) { [string]$s.status.failureReason } else { "Success" }
                            $ipAddr = if ($s.ipAddress) { [string]$s.ipAddress } else { "Unknown IP" }
                            $appDisplay = if ($s.appDisplayName) { [string]$s.appDisplayName } else { "M365 App" }
                            $riskSignIn = if ($s.riskLevelDuringSignIn) { [string]$s.riskLevelDuringSignIn } else { "none" }

                            $codeDesc = switch ($errCode) {
                                0     { if ($riskSignIn -match 'high|medium') { "Entra 0 (RISKY Sign-In: $riskSignIn)" } else { "Entra 0 (Sign-In Success)" } }
                                50173 { "Entra 50173 (Token Revoked)" }
                                50057 { "Entra 50057 (User Disabled)" }
                                50126 { "Entra 50126 (Bad Password)" }
                                50053 { "Entra 50053 (Smart Lockout)" }
                                50074 { "Entra 50074 (Strong Auth MFA Req)" }
                                50076 { "Entra 50076 (MFA Challenge)" }
                                53003 { "Entra 53003 (Blocked by Cond. Access)" }
                                default { "Entra $errCode" }
                            }
                            $sev = if ($riskSignIn -match 'high|medium' -or $errCode -eq 50053) { "CRITICAL" } elseif ($errCode -in @(50126, 50173, 50057, 53003)) { "WARNING" } else { "INFO" }
                            $decision = switch ($errCode) {
                                0     { "Successful cloud sign-in to '$appDisplay' from IP $ipAddr (Risk: $riskSignIn). If unrecognized, revoke 365 sessions and block Entra sign-in." }
                                50173 { "CONFIRMED CONTAINMENT: Refresh token was rejected because sessions were revoked." }
                                50057 { "CONFIRMED CONTAINMENT: Sign-in blocked because the Entra account is disabled." }
                                50126 { "Invalid password entered from IP $ipAddr against '$appDisplay'." }
                                50053 { "SUSPICIOUS BRUTE FORCE: Account locked by Entra Smart Lockout due to repeated failures from IP $ipAddr." }
                                53003 { "Sign-in from IP $ipAddr was blocked by Conditional Access policy." }
                                default { "Inspect sign-in failure reason ($failReason) from IP $ipAddr." }
                            }

                            $eventsList.Add([PSCustomObject]@{
                                Timestamp = $sTime
                                Source    = "Microsoft Entra ID"
                                EventCode = $codeDesc
                                Severity  = $sev
                                HostOrIP  = $ipAddr
                                Meaning   = "App: $appDisplay | Risk: $riskSignIn | Status: $failReason"
                                Decision  = $decision
                                RawDetail = ($s | ConvertTo-Json -Depth 4)
                            })
                        }
                    }
                } catch {}
            } catch {}
        }
    }

    # 3. Pull Google Workspace Admin & OAuth Token Suspicious Events via GAM7 (Fast < 8s bound)
    if ($SourceFilter -eq "All Sources" -or $SourceFilter -match "Google|GAM") {
        $gamCheck = Invoke-VerifyGAM -QuickStartup
        if ($gamCheck.Verified -and $gamCheck.Executable) {
            $gamExe = $gamCheck.Executable
            if (Get-Command Write-AppLog -ErrorAction SilentlyContinue) {
                Write-AppLog "[Event Triage 3/3] Querying Google Workspace account & OAuth token telemetry via GAM7 for '$targetGamId'..." "INFO"
                if ($form) { [System.Windows.Forms.Application]::DoEvents() }
            }
            try {
                $infoCli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('info', 'user', $targetGamId, 'noaliases', 'nogroups', 'nolicenses') -TimeoutSeconds 7
                $gInfo = $infoCli.Output
                if ($infoCli.ExitCode -eq 0 -and $gInfo) {
                    $isSusp = $gInfo -match 'Account Suspended:\s*True'
                    $lastLoginMatch = [regex]::Match($gInfo, 'Last login time:\s*(.+)')
                    $lastLoginStr = if ($lastLoginMatch.Success) { $lastLoginMatch.Groups[1].Value.Trim() } else { (Get-Date).ToString("yyyy-MM-dd HH:mm:ss") }
                    $eventsList.Add([PSCustomObject]@{
                        Timestamp = $lastLoginStr
                        Source    = "Google Workspace"
                        EventCode = if ($isSusp) { "USER_SUSPENDED" } else { "GOOGLE_SESSION_STATE" }
                        Severity  = if ($isSusp) { "WARNING" } else { "INFO" }
                        HostOrIP  = "accounts.google.com"
                        Meaning   = "Google User '$targetGamId' | Suspended: $isSusp | Last Login: $lastLoginStr"
                        Decision  = if ($isSusp) { "Google Workspace account is currently SUSPENDED." } else { "Account is active in Google Workspace. Use '3. Revoke Google Sessions', 'Suspend Google User', or 'Wipe Cloud MFA & Tokens' if compromised." }
                        RawDetail = $gInfo.Trim()
                    })
                }

                # 3B. Google Active OAuth Tokens & App Passwords Check (gam user <id> show tokens - fast < 6s)
                $tokCli = Invoke-GamCliSafe -GamExecutable $gamExe -Arguments @('user', $targetGamId, 'show', 'tokens') -TimeoutSeconds 6
                $tokOut = $tokCli.Output
                if ($tokCli.ExitCode -eq 0 -and $tokOut) {
                    foreach ($tLine in ($tokOut -split "`r?`n")) {
                        if ($tLine -match 'Display Text:\s*(.+)') {
                            $appName = $Matches[1].Trim()
                            $eventsList.Add([PSCustomObject]@{
                                Timestamp = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
                                Source    = "Google Workspace"
                                EventCode = "OAUTH_TOKEN_GRANT"
                                Severity  = "WARNING"
                                HostOrIP  = "Third-Party OAuth"
                                Meaning   = "Authorized Google OAuth Client: '$appName' for $targetGamId."
                                Decision  = "If '$appName' is unrecognized, click 'Wipe Cloud MFA & Tokens' (runs 'gam user deprovision') to revoke all Google OAuth grants."
                                RawDetail = $tokOut.Trim()
                            })
                        }
                    }
                }
            } catch {}
        }
    }

    return ,$eventsList.ToArray()
}


