function Write-AppLog {
    param([string]$Message, [string]$Level = "INFO")
    $timestamp = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
    $logLine = "[$timestamp] [$Level] $Message" + [System.Environment]::NewLine
    if ($txtLog) {
        $txtLog.AppendText($logLine)
        $txtLog.SelectionStart = $txtLog.Text.Length
        $txtLog.ScrollToCaret()
    }
}

function Show-ActionPopup {
    param(
        [string]$ActionTitle,
        [bool]$Succeeded,
        [string]$Details = ""
    )
    $nl = [System.Environment]::NewLine
    if ($Succeeded) {
        $body = "SUCCESS: $ActionTitle completed."
        if (-not [string]::IsNullOrWhiteSpace($Details)) {
            $body += "${nl}${nl}${Details}"
        }
        [void][System.Windows.Forms.MessageBox]::Show(
            $form,
            $body,
            "Success - $ActionTitle",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )
    } else {
        $body = "Failed - See Log.${nl}${nl}Action: $ActionTitle"
        if (-not [string]::IsNullOrWhiteSpace($Details)) {
            $body += "${nl}Error: $Details"
        }
        $body += "${nl}${nl}Review the bottom Real-Time Action Log for full diagnostic details."
        [void][System.Windows.Forms.MessageBox]::Show(
            $form,
            $body,
            "Failed - See Log ($ActionTitle)",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        )
    }
}

function Format-CsvSafeField {
    param([string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return "" }
    $clean = $Value.Replace("`r`n", " | ").Replace("`n", " | ").Replace("`r", " | ").Trim()
    return $clean.Replace('"', '""')
}

$script:inMemoryAuditLog = [System.Collections.Generic.List[psobject]]::new()

function Add-AuditEntry {
    param(
        [string]$Action,
        [string]$Status,
        [string]$Details
    )
    $ts = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
    $admin = if ($script:adminAccount) { $script:adminAccount } else { "admin" }
    $upn = if ($script:currentUser) {
        if ($script:currentUser.Mail -and (-not [string]::Equals($script:currentUser.UserPrincipalName, $script:currentUser.Mail, [StringComparison]::OrdinalIgnoreCase))) {
            "$($script:currentUser.UserPrincipalName) ($($script:currentUser.Mail))"
        } else {
            "$($script:currentUser.UserPrincipalName) ($($script:currentUser.SamAccountName))"
        }
    } else {
        "N/A"
    }
    $name = if ($script:currentUser -and $script:currentUser.DisplayName) { $script:currentUser.DisplayName } else { "N/A" }

    $entryObj = [PSCustomObject]@{
        Timestamp  = $ts
        Admin      = $admin
        TargetUPN  = $upn
        TargetName = $name
        Action     = $Action
        Status     = $Status
        Details    = $Details
    }
    if ($null -ne $script:inMemoryAuditLog) {
        [void]$script:inMemoryAuditLog.Add($entryObj)
    }

    $csvLine = '"{0}","{1}","{2}","{3}","{4}","{5}","{6}"' -f `
        (Format-CsvSafeField $ts), `
        (Format-CsvSafeField $admin), `
        (Format-CsvSafeField $upn), `
        (Format-CsvSafeField $name), `
        (Format-CsvSafeField $Action), `
        (Format-CsvSafeField $Status), `
        (Format-CsvSafeField $Details)

    $wroteCsv = $false
    try {
        if (-not (Test-Path $script:auditDir)) {
            New-Item -ItemType Directory -Path $script:auditDir -Force -ErrorAction Stop | Out-Null
        }
        if (-not (Test-Path $script:auditCsv)) {
            "Timestamp,Admin,TargetUPN,TargetName,Action,Status,Details" | Out-File -FilePath $script:auditCsv -Encoding utf8 -Force -ErrorAction Stop
        }
        Add-Content -Path $script:auditCsv -Value $csvLine -Encoding utf8 -ErrorAction Stop
        $wroteCsv = $true
    } catch {
        # Automatic fallback to user-writable LocalAppData if ProgramData was locked by an elevated session
        try {
            $script:auditDir = "$env:LOCALAPPDATA\IncidentResponse-Automator"
            if (-not (Test-Path $script:auditDir)) {
                New-Item -ItemType Directory -Path $script:auditDir -Force -ErrorAction Stop | Out-Null
            }
            $script:auditCsv = Join-Path $script:auditDir "AuditLog.csv"
            if (-not (Test-Path $script:auditCsv)) {
                "Timestamp,Admin,TargetUPN,TargetName,Action,Status,Details" | Out-File -FilePath $script:auditCsv -Encoding utf8 -Force -ErrorAction Stop
            }
            Add-Content -Path $script:auditCsv -Value $csvLine -Encoding utf8 -ErrorAction Stop
            if ($lblAuditPath) { $lblAuditPath.Text = "Audit File: $script:auditCsv" }
            $wroteCsv = $true
        } catch {
            Write-AppLog "WARN: Could not write audit entry to CSV file ($($_.Exception.Message)); retained in session memory." "WARN"
        }
    }
    try {
        if (Get-Command Load-AuditGrid -ErrorAction SilentlyContinue) {
            Load-AuditGrid
        }
    } catch {}
}

# -----------------------------------------------------------------------------
# DYNAMIC TAB 2 INCIDENT & INTEGRATION ALERT BANNER CONTROLLER
# -----------------------------------------------------------------------------
function Update-IntegrationAlertBanner {
    if (-not $pnlAlert -or -not $lblAlertText) { return }

    # 1. Evaluate Active Directory status
    $adVerified = $false
    if ($lblStatusAD -and ($lblStatusAD.Text -match 'VERIFIED')) {
        $adVerified = $true
    } elseif ($script:isDomainJoined) {
        $adVerified = $true
    } elseif ($script:targetDomain -and $script:targetDomain -ne "Not Domain-Joined (Workgroup)" -and ($script:useExplicitCreds -or $script:adCredential)) {
        $adVerified = $true
    }

    # 2. Evaluate Microsoft Graph status
    $graphVerified = $false
    if ($lblStatusGraph -and ($lblStatusGraph.Text -match 'VERIFIED')) {
        $graphVerified = $true
    } else {
        $gState = Get-SetupGraphLogState
        if ($gState.Verified) { $graphVerified = $true }
    }

    # 3. Evaluate Google GAM7 status
    $gamVerified = $false
    if ($lblStatusGAM -and ($lblStatusGAM.Text -match 'VERIFIED')) {
        $gamVerified = $true
    } else {
        $gamCheck = Invoke-VerifyGAM -QuickStartup
        if ($gamCheck.Verified) { $gamVerified = $true }
    }

    $unlinked = [System.Collections.Generic.List[string]]::new()
    if (-not $adVerified) { $unlinked.Add("Active Directory") }
    if (-not $graphVerified) { $unlinked.Add("Microsoft Graph") }
    if (-not $gamVerified) { $unlinked.Add("Google GAM7") }

    $isDark = if ($null -ne $script:isDark) { [bool]$script:isDark } else { $true }

    if ($unlinked.Count -gt 0) {
        $lblAlertText.Text = "ACCOUNT LINK REQUIRED: $($unlinked.Count) integration(s) not linked ($($unlinked -join ', ')). Check Tab 1 ('1. Setup')."
        $pnlAlert.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(69, 10, 10) } else { [System.Drawing.Color]::FromArgb(254, 242, 242) }
        $lblAlertText.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(254, 202, 202) } else { [System.Drawing.Color]::FromArgb(185, 28, 28) }
    } elseif ($null -eq $script:currentUser) {
        $lblAlertText.Text = "ALL INTEGRATIONS VERIFIED: Search for a target user above to begin incident investigation."
        $pnlAlert.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(6, 78, 59) } else { [System.Drawing.Color]::FromArgb(240, 253, 244) }
        $lblAlertText.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(167, 243, 208) } else { [System.Drawing.Color]::FromArgb(21, 128, 61) }
    } elseif (-not $chkVerified.Checked) {
        $uName = if ($script:currentUser.DisplayName) { $script:currentUser.DisplayName } else { $script:currentUser.SamAccountName }
        $lblAlertText.Text = "TARGET USER LOADED ($uName): Verify details above and check confirmation box below to unlock containment actions."
        $pnlAlert.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(30, 58, 138) } else { [System.Drawing.Color]::FromArgb(239, 246, 255) }
        $lblAlertText.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(191, 219, 254) } else { [System.Drawing.Color]::FromArgb(29, 78, 216) }
    } else {
        $uName = if ($script:currentUser.DisplayName) { $script:currentUser.DisplayName } else { $script:currentUser.SamAccountName }
        $lblAlertText.Text = "ACTIONS UNLOCKED: Containment decks active for $uName ($($script:currentUser.SamAccountName)). Proceed with containment."
        $pnlAlert.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(6, 78, 59) } else { [System.Drawing.Color]::FromArgb(236, 253, 245) }
        $lblAlertText.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(167, 243, 208) } else { [System.Drawing.Color]::FromArgb(4, 120, 87) }
    }
}

# -----------------------------------------------------------------------------
# DOMAIN PROFILE & ACTIVE DIRECTORY SWITCHER ENGINE
# -----------------------------------------------------------------------------
function Update-HeaderSubLabelSafe {
    if (-not $lblSub) { return }
    $activeDom = if ($script:targetDomain) { $script:targetDomain } elseif ($script:targetServer) { $script:targetServer } else { "Not Connected (Cloud Only)" }
    $activeServerStr = if ($script:targetServer -and $script:targetServer -ne $activeDom) { " (DC: $($script:targetServer))" } else { "" }
    $showPrefix = ($script:domainProfilesData -and $script:activeProfile -and (($script:domainProfilesData.Profiles.Count -gt 1) -or (-not [bool]$script:activeProfile.IsPrimary -and (-not [bool]$script:domainProfilesData.PrimaryConfigured))))
    $profPrefix = if ($showPrefix) {
        $primTag = if ([bool]$script:activeProfile.IsPrimary) { "Primary: " } else { "" }
        "[$primTag$($script:activeProfile.Name)] "
    } else {
        ""
    }
    $lblSub.Text = "${profPrefix}Domain: $activeDom$activeServerStr | Admin: $($script:adminAccount)"
}

function Clear-TargetUserWorkspaceSafe {
    $script:currentUser = $null
    $script:matchedUsers = @()
    if ($lstResults) { $lstResults.Items.Clear() }
    if ($chkVerified) {
        $chkVerified.Checked = $false
        $chkVerified.Enabled = $false
    }
    if ($btnRefreshUserSessions) { $btnRefreshUserSessions.Enabled = $false }
    if ($pnlResetPass) { $pnlResetPass.Visible = $false }
    if ($lblIdName) { $lblIdName.Text = "Name: (No user selected. Search above and click a user in the list)" }
    if ($lblIdDept) { $lblIdDept.Text = "UPN: --  |  Mail: --  |  sAMAccountName: --  |  Department: --" }
    if ($lblCardPassVal) { $lblCardPassVal.Text = "--" }
    if ($lblCard365Val) { $lblCard365Val.Text = "--" }
    if ($lblCardGoogleVal) { $lblCardGoogleVal.Text = "--" }
    if ($lblCardAcctVal) { $lblCardAcctVal.Text = "--" }
    if ($lblSearchStatus) { $lblSearchStatus.Text = "Type at least 3 characters (e.g. 'jsmith', 'john', 'smith') and click Find Users or press Enter." }
    if (Get-Command Clear-ForwardingRulesResults -ErrorAction SilentlyContinue) { Clear-ForwardingRulesResults }
    if (Get-Command Clear-SecurityEventsResults -ErrorAction SilentlyContinue) { Clear-SecurityEventsResults }
    if (Get-Command Update-ExtendedTabsUserHeader -ErrorAction SilentlyContinue) { Update-ExtendedTabsUserHeader }
}

function Sync-DiagProfileControls {
    if (-not $cmbDiagProfile) { return }
    $script:suppressDiagProfileSync = $true
    try {
        $cmbDiagProfile.Items.Clear()
        $selIdx = 0
        $i = 0
        foreach ($pr in $script:domainProfilesData.Profiles) {
            $domTag = if (-not [string]::IsNullOrWhiteSpace([string]$pr.TargetDomain)) { " ($($pr.TargetDomain))" } else { "" }
            $primTag = if ([bool]$pr.IsPrimary) { " [Primary]" } else { "" }
            [void]$cmbDiagProfile.Items.Add("$($pr.Name)$domTag$primTag")
            if ($script:activeProfile -and [string]::Equals([string]$pr.Id, [string]$script:activeProfile.Id, [StringComparison]::OrdinalIgnoreCase)) {
                $selIdx = $i
            }
            $i++
        }
        if ($cmbDiagProfile.Items.Count -gt 0) {
            $cmbDiagProfile.SelectedIndex = $selIdx
        }
        if ($grpDiagProfile) {
            $count = $script:domainProfilesData.Profiles.Count
            $hasPrimary = [bool]$script:domainProfilesData.PrimaryConfigured -or ($null -ne (Get-PrimaryDomainProfileSafe))
            $grpDiagProfile.Text = if (-not $hasPrimary) {
                " Active Domain Profile (No Primary Profile set — click 'Manage / AD...' or '+ New Profile') "
            } elseif ($count -gt 1) {
                " Active Domain Profile ($count configured — AD + Graph + GAM7 isolated per profile) "
            } else {
                " Active Domain Profile (Single-Domain Mode — click '+ New Profile' for multi-domain switching) "
            }
        }
    } finally {
        $script:suppressDiagProfileSync = $false
    }
}

function Refresh-IntegrationStatusLabelsSafe {
    param([switch]$Quick)

    # 1. Active Directory
    $adCheck = Invoke-VerifyAD -QuickStartup:$Quick
    if ($lblStatusAD) {
        if ($adCheck.Verified) {
            $lblStatusAD.Text = "Active Directory: VERIFIED ($($adCheck.Domain) - $($adCheck.Engine))"
            $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        } else {
            $lblStatusAD.Text = "Active Directory: NOT CONNECTED ($($adCheck.Error))"
            $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
        }
    }

    # 2. Microsoft Graph
    $graphCheck = Invoke-VerifyGraph -QuickStartup
    if ($lblStatusGraph) {
        if ($graphCheck.Verified) {
            $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: VERIFIED ($($graphCheck.Account))"
            $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        } else {
            $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: NOT VERIFIED ($($graphCheck.Error))"
            $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
        }
    }

    # 3. Google GAM7
    $gamCheck = Invoke-VerifyGAM -QuickStartup
    if ($lblStatusGAM) {
        if ($gamCheck.Verified) {
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): VERIFIED (v$($gamCheck.Version) & OAuth Ready)"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        } else {
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): NOT VERIFIED ($($gamCheck.Error))"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(217, 119, 6)
        }
    }

    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
}

function Switch-ActiveDomainProfileSafe {
    param(
        [Parameter(Mandatory = $true)]$TargetProfile,
        [System.Management.Automation.PSCredential]$AdCredential = $null,
        [bool]$UseExplicitAdCreds = $false,
        [bool]$SkipAdVerify = $false
    )

    if (-not $TargetProfile) { return }

    # 1. Persist outgoing profile's Graph context snapshot before switching
    Save-ActiveGraphSnapshotSafe

    # 2. Activate new profile & directories
    $script:activeProfile = $TargetProfile
    $script:activeProfile.LastUsedUtc = (Get-Date).ToUniversalTime().ToString('o')
    $script:domainProfilesData.ActiveProfileId = [string]$TargetProfile.Id

    $paths = Get-DomainProfilePaths -ProfileObj $TargetProfile
    foreach ($d in @($paths.ProfileDir, $paths.MgDir)) {
        if ($d -and (-not (Test-Path -LiteralPath $d -PathType Container))) {
            New-Item -ItemType Directory -Path $d -Force -ErrorAction SilentlyContinue | Out-Null
        }
    }
    if (-not $paths.IsDefault) {
        foreach ($d in @($paths.GamDir, $paths.GraphDir)) {
            if ($d -and (-not (Test-Path -LiteralPath $d -PathType Container))) {
                New-Item -ItemType Directory -Path $d -Force -ErrorAction SilentlyContinue | Out-Null
            }
        }
    }

    $env:GAMCFGDIR = Get-ActiveGamConfigDir
    $env:IR_GRAPH_SETUP_DIR = Get-ActiveGraphSetupDir

    # 3. Switch Graph context & clear cached App token
    Restore-GraphProfileContextSafe -TargetProfile $TargetProfile

    # 4. Update Active Directory connection state for this profile
    $script:targetDomain = [string]$TargetProfile.TargetDomain
    $script:targetServer = if (-not [string]::IsNullOrWhiteSpace([string]$TargetProfile.TargetServer)) {
        [string]$TargetProfile.TargetServer
    } else {
        $script:targetDomain
    }
    $script:useExplicitCreds = $UseExplicitAdCreds
    $script:adCredential = $AdCredential
    if (-not [string]::IsNullOrWhiteSpace([string]$TargetProfile.AdminUsername)) {
        $script:adminAccount = [string]$TargetProfile.AdminUsername
    } elseif (-not $UseExplicitAdCreds) {
        $script:adminAccount = if (-not [string]::IsNullOrEmpty($env:USERDNSDOMAIN)) { "$env:USERNAME@$($env:USERDNSDOMAIN.ToLower())" } elseif ($env:USERNAME) { $env:USERNAME } else { "admin" }
    } else {
        $script:adminAccount = "admin"
    }

    if ($paths.IsDefault -and (-not [string]::IsNullOrWhiteSpace($script:targetDomain))) {
        Save-LastDomainConnectionSafe -TargetDomain $script:targetDomain -TargetServer $script:targetServer -AdminUsername $script:adminAccount
    }
    Save-DomainProfilesSafe

    # 5. Clear stale target user from previous domain profile & refresh UI
    Clear-TargetUserWorkspaceSafe
    Update-HeaderSubLabelSafe
    Sync-DiagProfileControls
    Refresh-IntegrationStatusLabelsSafe -Quick:($SkipAdVerify)

    Write-AppLog "Switched active Domain Profile to '$($TargetProfile.Name)' (GAM: $($env:GAMCFGDIR) | Graph: $($env:IR_GRAPH_SETUP_DIR))." "SUCCESS"
}

function Show-PrimaryProfilePromptSafe {
    param([System.Windows.Forms.Form]$OwnerForm = $form)

    if (-not $script:domainProfilesData) { return }
    if ([bool]$script:domainProfilesData.PrimaryConfigured -or ($null -ne (Get-PrimaryDomainProfileSafe))) { return }

    $isDark = if ($null -ne $script:isDark) { [bool]$script:isDark } else { $true }
    $hasClientProfiles = (@($script:domainProfilesData.Profiles | Where-Object { -not [bool]$_.IsDefault }).Count -gt 0)
    $isOnClientProfile = ($script:activeProfile -and (-not [bool]$script:activeProfile.IsDefault))

    $dlgPrim = New-Object System.Windows.Forms.Form
    $dlgPrim.Text = "Primary Domain Profile Setup"
    $dlgPrim.Size = New-Object System.Drawing.Size(540, 365)
    $dlgPrim.StartPosition = "CenterParent"
    $dlgPrim.FormBorderStyle = "FixedDialog"
    $dlgPrim.MaximizeBox = $false
    $dlgPrim.MinimizeBox = $false
    $dlgPrim.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(248, 250, 252) }
    $dlgPrim.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(248, 250, 252) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }

    $hdr = New-Object System.Windows.Forms.Panel
    $hdr.Size = New-Object System.Drawing.Size(540, 48)
    $hdr.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(30, 41, 59) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $dlgPrim.Controls.Add($hdr)

    $lblHdr = New-Object System.Windows.Forms.Label
    $lblHdr.Text = "No Primary Domain Profile Is Configured Yet"
    $lblHdr.Font = New-Object System.Drawing.Font("Segoe UI", 10.5, [System.Drawing.FontStyle]::Bold)
    $lblHdr.ForeColor = [System.Drawing.Color]::White
    $lblHdr.Location = New-Object System.Drawing.Point(16, 13)
    $lblHdr.AutoSize = $true
    $hdr.Controls.Add($lblHdr)

    $envLabel = if ($script:isDomainJoined) { "Joined Domain: $($script:detectedDomain)" } else { "Workgroup / Remote Workstation" }
    $lblQuestion = New-Object System.Windows.Forms.Label
    $lblQuestion.Location = New-Object System.Drawing.Point(18, 60)
    $lblQuestion.Size = New-Object System.Drawing.Size(492, 66)
    $lblQuestion.Font = New-Object System.Drawing.Font("Segoe UI", 8.75)
    $lblQuestion.Text = "Detected Environment: $envLabel`r`n`r`nWill this current environment be your Primary (Home) Domain Profile?`r`nIf you are installing or running this tool while assisting another domain, keep Primary unset so your home domain profile stays clean for when you return."
    $dlgPrim.Controls.Add($lblQuestion)

    $lblPrimName = New-Object System.Windows.Forms.Label
    $lblPrimName.Text = "Primary Profile Name (if setting this as Primary):"
    $lblPrimName.Font = New-Object System.Drawing.Font("Segoe UI", 8.25, [System.Drawing.FontStyle]::Bold)
    $lblPrimName.Location = New-Object System.Drawing.Point(18, 134)
    $lblPrimName.Size = New-Object System.Drawing.Size(492, 18)
    $dlgPrim.Controls.Add($lblPrimName)

    $txtPrimName = New-Object System.Windows.Forms.TextBox
    $txtPrimName.Location = New-Object System.Drawing.Point(18, 155)
    $txtPrimName.Size = New-Object System.Drawing.Size(490, 24)
    $txtPrimName.Font = New-Object System.Drawing.Font("Segoe UI", 9.25)
    $txtPrimName.Text = if ($script:isDomainJoined -and (-not [string]::IsNullOrWhiteSpace($script:detectedDomain))) { "$($script:detectedDomain) (Primary)" } else { "Primary Domain" }
    $dlgPrim.Controls.Add($txtPrimName)

    $lblOtherName = New-Object System.Windows.Forms.Label
    $lblOtherName.Text = if ($isOnClientProfile) { "Or keep assisting another domain (leave Primary unset for home):" } else { "If assisting another domain instead, name that temporary/client profile:" }
    $lblOtherName.Font = New-Object System.Drawing.Font("Segoe UI", 8.25, [System.Drawing.FontStyle]::Bold)
    $lblOtherName.Location = New-Object System.Drawing.Point(18, 190)
    $lblOtherName.Size = New-Object System.Drawing.Size(492, 18)
    $dlgPrim.Controls.Add($lblOtherName)

    $nextClientNum = (@($script:domainProfilesData.Profiles | Where-Object { -not [bool]$_.IsDefault }).Count) + 1
    $txtClientName = New-Object System.Windows.Forms.TextBox
    $txtClientName.Location = New-Object System.Drawing.Point(18, 211)
    $txtClientName.Size = New-Object System.Drawing.Size(490, 24)
    $txtClientName.Font = New-Object System.Drawing.Font("Segoe UI", 9.25)
    $txtClientName.Text = if ($isOnClientProfile) { [string]$script:activeProfile.Name } else { "Assisting Domain $nextClientNum" }
    if ($isOnClientProfile) { $txtClientName.ReadOnly = $true }
    $dlgPrim.Controls.Add($txtClientName)

    $btnYesPrimary = New-Object System.Windows.Forms.Button
    $btnYesPrimary.Text = "Yes — Set as My Primary Profile"
    $btnYesPrimary.UseMnemonic = $false
    $btnYesPrimary.Location = New-Object System.Drawing.Point(18, 252)
    $btnYesPrimary.Size = New-Object System.Drawing.Size(214, 34)
    $btnYesPrimary.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnYesPrimary.BackColor = [System.Drawing.Color]::FromArgb(37, 99, 235)
    $btnYesPrimary.ForeColor = [System.Drawing.Color]::White
    $btnYesPrimary.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $dlgPrim.Controls.Add($btnYesPrimary)

    $btnNoAssisting = New-Object System.Windows.Forms.Button
    $btnNoAssisting.Text = if ($isOnClientProfile) { "No — Stay on Current Profile" } else { "No — Assisting Another Domain" }
    $btnNoAssisting.UseMnemonic = $false
    $btnNoAssisting.Location = New-Object System.Drawing.Point(240, 252)
    $btnNoAssisting.Size = New-Object System.Drawing.Size(184, 34)
    $btnNoAssisting.Font = New-Object System.Drawing.Font("Segoe UI", 8.25, [System.Drawing.FontStyle]::Bold)
    $btnNoAssisting.BackColor = [System.Drawing.Color]::FromArgb(5, 150, 105)
    $btnNoAssisting.ForeColor = [System.Drawing.Color]::White
    $btnNoAssisting.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $dlgPrim.Controls.Add($btnNoAssisting)

    $btnLater = New-Object System.Windows.Forms.Button
    $btnLater.Text = "Later"
    $btnLater.Location = New-Object System.Drawing.Point(432, 252)
    $btnLater.Size = New-Object System.Drawing.Size(76, 34)
    $btnLater.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
    $btnLater.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnLater.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlgPrim.Controls.Add($btnLater)

    $btnYesPrimary.Add_Click({
        $primTitle = if (-not [string]::IsNullOrWhiteSpace($txtPrimName.Text)) { $txtPrimName.Text.Trim() } else { "Primary Domain" }
        $defPr = Get-ProfileByIdSafe -ProfileId 'default'
        if (-not $defPr) { $defPr = $script:domainProfilesData.Profiles[0] }

        if ($script:activeProfile -and ($script:activeProfile.Id -ne $defPr.Id)) {
            # Technician returned home from a temporary/client profile: populate Primary slot cleanly and switch to it
            if ($script:isDomainJoined -and (-not [string]::IsNullOrWhiteSpace($script:detectedDomain))) {
                $defPr.TargetDomain = $script:detectedDomain
                $defPr.TargetServer = $script:detectedDomain
                $defPr.UseExplicitCreds = $false
            }
            Set-PrimaryDomainProfileSafe -TargetProfile $defPr -NewName $primTitle
            Switch-ActiveDomainProfileSafe -TargetProfile $defPr -UseExplicitAdCreds ([bool]$defPr.UseExplicitCreds) -SkipAdVerify $false
        } else {
            Set-PrimaryDomainProfileSafe -TargetProfile $defPr -NewName $primTitle
            Update-HeaderSubLabelSafe
            Sync-DiagProfileControls
        }
        Write-AppLog "Primary Domain Profile configured: '$($defPr.Name)'." "SUCCESS"
        $dlgPrim.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $dlgPrim.Close()
    })

    $btnNoAssisting.Add_Click({
        if ($isOnClientProfile) {
            Write-AppLog "Staying on '$($script:activeProfile.Name)'. Primary Domain Profile remains unset until you return to your home domain." "INFO"
            $dlgPrim.DialogResult = [System.Windows.Forms.DialogResult]::OK
            $dlgPrim.Close()
            return
        }
        $clientTitle = if (-not [string]::IsNullOrWhiteSpace($txtClientName.Text)) { $txtClientName.Text.Trim() } else { "Assisting Domain $nextClientNum" }
        $newClientPr = New-DomainProfileSafe -ProfileName $clientTitle
        Switch-ActiveDomainProfileSafe -TargetProfile $newClientPr -UseExplicitAdCreds $true -SkipAdVerify $true
        Write-AppLog "Created isolated Domain Profile '$($newClientPr.Name)' for assisting another domain. Primary Domain Profile kept clean and unset for your home domain." "INFO"
        $dlgPrim.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $dlgPrim.Close()
    })

    $dlgPrim.AcceptButton = $btnYesPrimary
    $dlgPrim.CancelButton = $btnLater
    [void]$dlgPrim.ShowDialog($OwnerForm)
}

function Show-NewDomainProfileModal {
    param([System.Windows.Forms.Form]$OwnerForm = $form)

    $isDark = if ($null -ne $script:isDark) { [bool]$script:isDark } else { $true }
    $dlgNew = New-Object System.Windows.Forms.Form
    $dlgNew.Text = "Add Domain Profile"
    $dlgNew.Size = New-Object System.Drawing.Size(470, 235)
    $dlgNew.StartPosition = "CenterParent"
    $dlgNew.FormBorderStyle = "FixedDialog"
    $dlgNew.MaximizeBox = $false
    $dlgNew.MinimizeBox = $false
    $dlgNew.BackColor = if ($isDark) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::FromArgb(248, 250, 252) }
    $dlgNew.ForeColor = if ($isDark) { [System.Drawing.Color]::FromArgb(248, 250, 252) } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }

    $lblPrompt = New-Object System.Windows.Forms.Label
    $lblPrompt.Text = "Domain Profile Name (e.g. 'Home Domain', 'Contoso Corp', 'Client A'):"
    $lblPrompt.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $lblPrompt.Location = New-Object System.Drawing.Point(18, 16)
    $lblPrompt.Size = New-Object System.Drawing.Size(420, 20)
    $dlgNew.Controls.Add($lblPrompt)

    $txtName = New-Object System.Windows.Forms.TextBox
    $txtName.Location = New-Object System.Drawing.Point(18, 40)
    $txtName.Size = New-Object System.Drawing.Size(418, 24)
    $txtName.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
    $dlgNew.Controls.Add($txtName)

    $chkCopyGamSecrets = New-Object System.Windows.Forms.CheckBox
    $chkCopyGamSecrets.Text = "Copy current GAM client_secrets.json (use if profiles share 1 Google Cloud project)"
    $chkCopyGamSecrets.Font = New-Object System.Drawing.Font("Segoe UI", 8)
    $chkCopyGamSecrets.Location = New-Object System.Drawing.Point(18, 76)
    $chkCopyGamSecrets.Size = New-Object System.Drawing.Size(422, 34)
    $chkCopyGamSecrets.Checked = $false
    $srcGamDir = Get-ActiveGamConfigDir
    $hasCurrSec = $srcGamDir -and (Test-Path -LiteralPath (Join-Path $srcGamDir 'client_secrets.json') -PathType Leaf)
    $chkCopyGamSecrets.Enabled = [bool]$hasCurrSec
    $dlgNew.Controls.Add($chkCopyGamSecrets)

    $lblNote = New-Object System.Windows.Forms.Label
    $lblNote.Text = "Each Domain Profile stores its own isolated AD domain, Graph tenant/app, and GAM7 config."
    $lblNote.Font = New-Object System.Drawing.Font("Segoe UI", 8)
    $lblNote.ForeColor = [System.Drawing.Color]::FromArgb(148, 163, 184)
    $lblNote.Location = New-Object System.Drawing.Point(18, 114)
    $lblNote.Size = New-Object System.Drawing.Size(420, 20)
    $dlgNew.Controls.Add($lblNote)

    $btnCreate = New-Object System.Windows.Forms.Button
    $btnCreate.Text = "Create Profile"
    $btnCreate.Location = New-Object System.Drawing.Point(216, 146)
    $btnCreate.Size = New-Object System.Drawing.Size(118, 32)
    $btnCreate.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Bold)
    $btnCreate.BackColor = [System.Drawing.Color]::FromArgb(37, 99, 235)
    $btnCreate.ForeColor = [System.Drawing.Color]::White
    $btnCreate.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $dlgNew.Controls.Add($btnCreate)

    $btnCancelNew = New-Object System.Windows.Forms.Button
    $btnCancelNew.Text = "Cancel"
    $btnCancelNew.Location = New-Object System.Drawing.Point(344, 146)
    $btnCancelNew.Size = New-Object System.Drawing.Size(92, 32)
    $btnCancelNew.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
    $btnCancelNew.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCancelNew.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlgNew.Controls.Add($btnCancelNew)

    $createdProfile = $null
    $btnCreate.Add_Click({
        if ([string]::IsNullOrWhiteSpace($txtName.Text)) {
            [System.Windows.Forms.MessageBox]::Show($dlgNew, "Please enter a name for the new domain profile.", "Name Required", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
            return
        }
        $dlgNew.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $dlgNew.Close()
    })

    $dlgNew.AcceptButton = $btnCreate
    $dlgNew.CancelButton = $btnCancelNew
    $dlgNew.Add_Shown({ $txtName.Focus() })

    if ($dlgNew.ShowDialog($OwnerForm) -eq [System.Windows.Forms.DialogResult]::OK) {
        $createdProfile = New-DomainProfileSafe -ProfileName $txtName.Text -CopyCurrentGamSecrets:($chkCopyGamSecrets.Checked)
    }
    return $createdProfile
}

