$btnDiagSwitchProfile.Add_Click({
    $idx = $cmbDiagProfile.SelectedIndex
    if ($idx -lt 0 -or $idx -ge $script:domainProfilesData.Profiles.Count) { return }
    $targetPr = $script:domainProfilesData.Profiles[$idx]
    if ($script:activeProfile -and ($targetPr.Id -eq $script:activeProfile.Id)) {
        Refresh-IntegrationStatusLabelsSafe -Quick:$false
        return
    }
    if ([bool]$targetPr.UseExplicitCreds -and (-not [string]::IsNullOrWhiteSpace([string]$targetPr.TargetDomain))) {
        # Switch Cloud immediately, and open Domain Switcher pre-selected so operator can enter AD password (or skip AD)
        Switch-ActiveDomainProfileSafe -TargetProfile $targetPr -UseExplicitAdCreds $true -SkipAdVerify $true
        Show-DomainSwitcher -PreselectProfileId $targetPr.Id
    } else {
        Switch-ActiveDomainProfileSafe -TargetProfile $targetPr -UseExplicitAdCreds ([bool]$targetPr.UseExplicitCreds) -SkipAdVerify $false
    }
})

$btnDiagNewProfile.Add_Click({
    $newPr = Show-NewDomainProfileModal -OwnerForm $form
    if ($newPr) {
        Switch-ActiveDomainProfileSafe -TargetProfile $newPr -UseExplicitAdCreds $true -SkipAdVerify $true
        Write-DiagLog "[INFO] Created and switched to new Domain Profile '$($newPr.Name)'. Link Graph, GAM7, and/or AD above for this domain."
        Show-ActionPopup -ActionTitle "New Domain Profile" -Succeeded $true -Details "Switched to '$($newPr.Name)'.`n`nNow click '1. Setup Microsoft Graph', '2. Setup Google GAM7', or 'Switch AD Account / Domain' to link this domain."
    }
})

$btnDiagManageProfiles.Add_Click({
    $idx = $cmbDiagProfile.SelectedIndex
    $preId = if ($idx -ge 0 -and $idx -lt $script:domainProfilesData.Profiles.Count) { [string]$script:domainProfilesData.Profiles[$idx].Id } else { "" }
    Show-DomainSwitcher -PreselectProfileId $preId
})

function Write-DiagLog {
    param([string]$Message)
    $lvl = if ($Message -match '^\[FAIL\]|^\[ERROR\]') { "ERROR" } elseif ($Message -match '^\[PASS\]|^\[SUCCESS\]') { "SUCCESS" } elseif ($Message -match '^\[WARN\]') { "WARN" } else { "INFO" }
    Write-AppLog $Message $lvl
}

$btnTestAD.Add_Click({
    Write-DiagLog "=== VERIFYING ACTIVE DIRECTORY CONNECTIVITY (LIVE LDAP RootDSE) ==="
    $adCheck = Invoke-VerifyAD
    if ($adCheck.Verified) {
        $lblStatusAD.Text = "Active Directory: VERIFIED ($($adCheck.Domain) - $($adCheck.Engine))"
        $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
        Write-DiagLog "[PASS] Active Directory LDAP handshake verified! Domain: $($adCheck.Domain) | Engine: $($adCheck.Engine)"
        Show-ActionPopup -ActionTitle "Test Active Directory" -Succeeded $true -Details "Domain: $($adCheck.Domain)`nEngine: $($adCheck.Engine)"
    } else {
        $lblStatusAD.Text = "Active Directory: FAILED / NOT CONNECTED ($($adCheck.Error))"
        $lblStatusAD.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        Write-DiagLog "[FAIL] Active Directory verification failed: $($adCheck.Error)"
        Show-ActionPopup -ActionTitle "Test Active Directory" -Succeeded $false -Details $adCheck.Error
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

