$btnRunRsatSetup.Add_Click({
    try {
        Write-DiagLog "Launching Setup-RSAT-ActiveDirectory.bat (requires Administrator elevation)..."
        $exitCode = Invoke-SetupBatchScript -FileName "Setup-RSAT-ActiveDirectory.bat" -Base64Payload $script:EmbeddedRsatBatB64 -Elevate
        Write-DiagLog "Setup-RSAT-ActiveDirectory.bat exited with code $exitCode. Verifying ActiveDirectory module..."
        if ($exitCode -eq 0 -and (Get-Module -ListAvailable -Name ActiveDirectory)) {
            Import-Module ActiveDirectory -ErrorAction SilentlyContinue
            Write-DiagLog "[SUCCESS] ActiveDirectory RSAT PowerShell module is installed and verified."
            Show-ActionPopup -ActionTitle "Install RSAT ActiveDirectory" -Succeeded $true -Details "RSAT ActiveDirectory module installed and verified."
        } else {
            Write-DiagLog "[WARN] RSAT ActiveDirectory module was not detected after installer exited (code $exitCode). Native .NET LDAP remains active."
            Show-ActionPopup -ActionTitle "Install RSAT ActiveDirectory" -Succeeded $false -Details "RSAT module not detected (Native .NET LDAP remains active)."
        }
    } catch {
        Write-DiagLog "[ERROR] RSAT setup error: $($_.Exception.Message)"
        Show-ActionPopup -ActionTitle "Install RSAT ActiveDirectory" -Succeeded $false -Details $_.Exception.Message
    }
})

$btnSwitchGraphAcct.Add_Click({
    $switchPs1 = Join-Path ([IO.Path]::GetTempPath()) ("IRSwitchGraph_" + [Guid]::NewGuid().ToString("N").Substring(0, 8) + ".ps1")
    $resultFlag = Join-Path ([IO.Path]::GetTempPath()) ("IRSwitchGraphOk_" + [Guid]::NewGuid().ToString("N").Substring(0, 8) + ".txt")
    try {
        if (-not (Get-Module -ListAvailable -Name 'Microsoft.Graph.Authentication')) {
            Show-ActionPopup -ActionTitle "Switch Graph Account" -Succeeded $false -Details "Microsoft.Graph.Authentication module is not installed yet. Click '1. Setup Microsoft Graph' first."
            return
        }

        Write-DiagLog "Opening Device-Code authentication to switch Microsoft Graph account..."
        $switchScopes = @(
            'User.RevokeSessions.All',
            'Directory.AccessAsUser.All',
            'User.ReadWrite.All',
            'UserAuthenticationMethod.ReadWrite.All',
            'MailboxSettings.ReadWrite',
            'Mail.ReadWrite',
            'AuditLog.Read.All',
            'IdentityRiskEvent.Read.All'
        )
        $scopeCsv = $switchScopes -join ','
        $safeFlagPath = $resultFlag.Replace("'", "''")
        $logDir = Get-ActiveGraphSetupDir
        $safeLogDir = $logDir.Replace("'", "''")

        $switchScript = @"
`$ErrorActionPreference = 'Stop'
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host '       SWITCH MICROSOFT GRAPH ACCOUNT (DEVICE-CODE)' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''
Write-Host '1. Copy the code and sign-in URL below.' -ForegroundColor Yellow
Write-Host '2. Open it in an InPrivate window or browser profile signed into your ADMIN account.' -ForegroundColor Yellow
Write-Host '   (Do NOT authorize your primary daily account.)' -ForegroundColor Yellow
Write-Host ''
try {
    Import-Module Microsoft.Graph.Authentication -DisableNameChecking -ErrorAction Stop
    if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
        Set-MgGraphOption -DisableLoginByWAM `$true -ErrorAction SilentlyContinue
    }
    try { Disconnect-MgGraph -ErrorAction SilentlyContinue | Out-Null } catch {}

    Connect-MgGraph -Scopes ('$scopeCsv' -split ',') -ContextScope CurrentUser -UseDeviceAuthentication -NoWelcome -ErrorAction Stop
    `$ctx = Get-MgContext -ErrorAction Stop
    if (-not `$ctx -or [string]::IsNullOrWhiteSpace([string]`$ctx.Account)) {
        throw 'Microsoft Graph did not return a signed-in account.'
    }

    if (-not (Test-Path -LiteralPath '$safeLogDir')) {
        New-Item -ItemType Directory -Path '$safeLogDir' -Force | Out-Null
    }
    `$logFile = Join-Path '$safeLogDir' 'Setup.log'
    `$ts = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    `$logLines = @(
        "Microsoft Graph setup started: `$ts",
        "[`$ts] [Success] Authenticated account: `$(`$ctx.Account)",
        "[`$ts] [Success] Tenant ID: `$(`$ctx.TenantId)",
        "[`$ts] [Success] All requested delegated permissions are present.",
        "[`$ts] [Success] Setup completed successfully for `$(`$ctx.Account)."
    )
    Set-Content -LiteralPath `$logFile -Value `$logLines -Encoding UTF8 -Force
    Set-Content -LiteralPath '$safeFlagPath' -Value ([string]`$ctx.Account) -Encoding UTF8 -Force

    Write-Host ''
    Write-Host "Switched Microsoft Graph account to: `$(`$ctx.Account)" -ForegroundColor Green
    Start-Sleep -Seconds 2
} catch {
    Write-Host ''
    Write-Host "Account switch error: `$(`$_.Exception.Message)" -ForegroundColor Red
    Read-Host 'Press Enter to close'
    exit 1
}
"@
        Set-Content -LiteralPath $switchPs1 -Value $switchScript -Encoding UTF8 -Force
        $psExe = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
        if (-not (Test-Path -LiteralPath $psExe)) { $psExe = "powershell.exe" }
        $null = Start-Process -FilePath $psExe -ArgumentList @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$switchPs1`"") -Wait -PassThru -WindowStyle Normal

        if (Test-Path -LiteralPath $resultFlag -PathType Leaf) {
            try {
                Import-Module Microsoft.Graph.Authentication -DisableNameChecking -ErrorAction SilentlyContinue
                if (Get-Command -Name 'Set-MgGraphOption' -ErrorAction SilentlyContinue) {
                    Set-MgGraphOption -DisableLoginByWAM $true -ErrorAction SilentlyContinue
                }
                Disconnect-MgGraph -ErrorAction SilentlyContinue | Out-Null
                Connect-MgGraph -ContextScope CurrentUser -NoWelcome -ErrorAction SilentlyContinue
            } catch {}

            $script:cachedGraphAppToken = $null
            $script:cachedGraphAppTokenExpiry = [datetime]::MinValue
            Save-ActiveGraphSnapshotSafe
            $graphCheck = Invoke-VerifyGraph -LiveApiCheck
            if ($graphCheck.Verified) {
                if ($script:activeProfile) {
                    $script:activeProfile.GraphAccountHint = [string]$graphCheck.Account
                    $script:activeProfile.GraphTenantIdHint = [string]$graphCheck.TenantId
                    Save-DomainProfilesSafe
                }
                $lblStatusGraph.Text = "Microsoft Graph SDK & Auth: VERIFIED ($($graphCheck.Account))"
                $lblStatusGraph.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
                Write-DiagLog "[SUCCESS] Switched Microsoft Graph account to $($graphCheck.Account) (Tenant: $($graphCheck.TenantId))."
                if ($script:currentUser) { Update-SelectedUserSessionBoxes }
                Show-ActionPopup -ActionTitle "Switch Graph Account" -Succeeded $true -Details "Profile: $($script:activeProfile.Name)`nActive Microsoft Graph account:`n$($graphCheck.Account)"
            } else {
                Write-DiagLog "[WARN] Graph switch verification notice: $($graphCheck.Error)"
                Show-ActionPopup -ActionTitle "Switch Graph Account" -Succeeded $false -Details $graphCheck.Error
            }
        } else {
            Write-DiagLog "Microsoft Graph account switch was cancelled or did not complete."
        }
    } catch {
        Write-DiagLog "[ERROR] Switch Graph Account failed: $($_.Exception.Message)"
        Show-ActionPopup -ActionTitle "Switch Graph Account" -Succeeded $false -Details $_.Exception.Message
    } finally {
        if (Test-Path -LiteralPath $switchPs1) { Remove-Item -LiteralPath $switchPs1 -Force -ErrorAction SilentlyContinue }
        if (Test-Path -LiteralPath $resultFlag) { Remove-Item -LiteralPath $resultFlag -Force -ErrorAction SilentlyContinue }
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

$btnSwitchGamAcct.Add_Click({
    $switchGamPs1 = Join-Path ([IO.Path]::GetTempPath()) ("IRSwitchGam_" + [Guid]::NewGuid().ToString("N").Substring(0, 8) + ".ps1")
    $gamFlag = Join-Path ([IO.Path]::GetTempPath()) ("IRSwitchGamOk_" + [Guid]::NewGuid().ToString("N").Substring(0, 8) + ".txt")
    try {
        $gamExe = Resolve-GamExecutable
        if (-not $gamExe) {
            Show-ActionPopup -ActionTitle "Switch GAM Account" -Succeeded $false -Details "gam.exe was not found. Click '2. Setup Google GAM7' first."
            return
        }

        $gamDir = Split-Path -Parent $gamExe
        $cfgDir = Get-ActiveGamConfigDir
        $env:GAMCFGDIR = $cfgDir
        $isCustomGamProf = (-not [string]::IsNullOrWhiteSpace($script:BaseDefaultGamCfgDir)) -and ($cfgDir.TrimEnd('\') -ine $script:BaseDefaultGamCfgDir.TrimEnd('\'))
        $hasSecrets = (Test-Path -LiteralPath (Join-Path $cfgDir 'client_secrets.json') -PathType Leaf) -or ((-not $isCustomGamProf) -and (Test-Path -LiteralPath (Join-Path $gamDir 'client_secrets.json') -PathType Leaf))
        if (-not $hasSecrets) {
            Show-ActionPopup -ActionTitle "Switch GAM Account" -Succeeded $false -Details "Google OAuth client_secrets.json was not found for this profile ($cfgDir). Click '2. Setup Google GAM7' first to link your Google Cloud project."
            return
        }

        Write-DiagLog "Launching GAM7 OAuth account switcher for profile '$($script:activeProfile.Name)'..."
        $safeGamExe = $gamExe.Replace("'", "''")
        $safeGamFlag = $gamFlag.Replace("'", "''")
        $safeCfgDir = $cfgDir.Replace("'", "''")
        $gamSwitchScript = @"
`$ErrorActionPreference = 'Continue'
`$env:GAMCFGDIR = '$safeCfgDir'
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host '      SWITCH GOOGLE WORKSPACE GAM7 ADMIN ACCOUNT' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host "Config Folder: $safeCfgDir" -ForegroundColor DarkCyan
Write-Host ''
Write-Host 'Clearing existing GAM OAuth token and starting new authorization...' -ForegroundColor Yellow
Write-Host 'TIP: If a browser tab opens to your primary Google account, switch to or' -ForegroundColor Yellow
Write-Host '     copy the authorization URL into an InPrivate/Admin browser window.' -ForegroundColor Yellow
Write-Host ''
& '$safeGamExe' oauth delete
Write-Host ''
& '$safeGamExe' oauth create
`$createCode = `$LASTEXITCODE
Write-Host ''
if (`$createCode -eq 0) {
    & '$safeGamExe' oauth verify
    if (`$LASTEXITCODE -eq 0) {
        & '$safeGamExe' oauth info
        Set-Content -LiteralPath '$safeGamFlag' -Value 'OK' -Encoding UTF8 -Force
        Write-Host ''
        Write-Host 'Google Workspace GAM7 account switched and verified!' -ForegroundColor Green
        Start-Sleep -Seconds 2
        exit 0
    }
}
Write-Host ''
Write-Host 'GAM OAuth switch did not complete verification. Review messages above.' -ForegroundColor Red
Read-Host 'Press Enter to close'
exit 1
"@
        Set-Content -LiteralPath $switchGamPs1 -Value $gamSwitchScript -Encoding UTF8 -Force
        $psExe = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
        if (-not (Test-Path -LiteralPath $psExe)) { $psExe = "powershell.exe" }
        $null = Start-Process -FilePath $psExe -ArgumentList @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$switchGamPs1`"") -Wait -PassThru -WindowStyle Normal

        $gamCheck = Invoke-VerifyGAM
        if ($gamCheck.Verified) {
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): VERIFIED (v$($gamCheck.Version) & OAuth Ready)"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(21, 128, 61)
            Write-DiagLog "[SUCCESS] Switched Google GAM7 OAuth account (v$($gamCheck.Version) verified)."
            if ($script:currentUser) { Update-SelectedUserSessionBoxes }
            if (Test-Path -LiteralPath $gamFlag -PathType Leaf) {
                Show-ActionPopup -ActionTitle "Switch GAM Account" -Succeeded $true -Details "Google Workspace GAM7 OAuth verified for the new admin account."
            }
        } else {
            $lblStatusGAM.Text = "Google Apps Manager (GAM7): NOT VERIFIED ($($gamCheck.Error))"
            $lblStatusGAM.ForeColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
            Write-DiagLog "[WARN] GAM7 verification after account switch: $($gamCheck.Error)"
            Show-ActionPopup -ActionTitle "Switch GAM Account" -Succeeded $false -Details $gamCheck.Error
        }
    } catch {
        Write-DiagLog "[ERROR] Switch GAM Account failed: $($_.Exception.Message)"
        Show-ActionPopup -ActionTitle "Switch GAM Account" -Succeeded $false -Details $_.Exception.Message
    } finally {
        if (Test-Path -LiteralPath $switchGamPs1) { Remove-Item -LiteralPath $switchGamPs1 -Force -ErrorAction SilentlyContinue }
        if (Test-Path -LiteralPath $gamFlag) { Remove-Item -LiteralPath $gamFlag -Force -ErrorAction SilentlyContinue }
    }
    if (Get-Command Update-IntegrationAlertBanner -ErrorAction SilentlyContinue) {
        Update-IntegrationAlertBanner
    }
})

