$grpRulesAudit.Controls.Add($txtRuleDecision)

$script:loadedForwardingRules = @()

function Update-RuleActionButtonsState {
    $hasRules = ($null -ne $script:loadedForwardingRules -and $script:loadedForwardingRules.Count -gt 0)
    $hasSelected = ($hasRules -and $null -ne $gridRules.SelectedRows -and $gridRules.SelectedRows.Count -gt 0)
    $isVerified = [bool]$chkVerified.Checked
    $suspCount = 0
    if ($hasRules) {
        foreach ($r in $script:loadedForwardingRules) {
            if ($null -ne $r -and ($r.Risk -like "*HIGH*" -or $r.Risk -like "*SUSPICIOUS*")) {
                $suspCount++
            }
        }
    }
    $btnDisableSelectedRule.Enabled = ($hasSelected -and $isVerified)
    $btnEnableSelectedRule.Enabled  = ($hasSelected -and $isVerified)
    $btnDeleteSelectedRule.Enabled  = ($hasSelected -and $isVerified)
    $btnDisableAllSuspiciousRules.Enabled = (($suspCount -gt 0) -and $isVerified)
}

function Clear-ForwardingRulesResults {
    if ($gridRules) { $gridRules.Rows.Clear() }
    $script:loadedForwardingRules = @()
    if ($btnDisableSelectedRule) { $btnDisableSelectedRule.Enabled = $false }
    if ($btnEnableSelectedRule)  { $btnEnableSelectedRule.Enabled  = $false }
    if ($btnDeleteSelectedRule)  { $btnDeleteSelectedRule.Enabled  = $false }
    if ($btnDisableAllSuspiciousRules) { $btnDisableAllSuspiciousRules.Enabled = $false }
    if ($txtRuleDecision) {
        $txtRuleDecision.Text = "RULE INSPECTOR: Click 'Audit M365 & Gmail Rules' above to scan for hidden BEC exfiltration or auto-delete rules."
    }
}

$btnClearRules.Add_Click({
    Clear-ForwardingRulesResults
    Write-AppLog "Cleared M365 & Gmail Forwarding / Inbox Rules audit table." "INFO"
})

$gridRules.Add_SelectionChanged({
    Update-RuleActionButtonsState
    if ($gridRules.SelectedRows.Count -le 0) { return }
    $idx = $gridRules.SelectedRows[0].Index
    if ($idx -ge 0 -and $idx -lt $script:loadedForwardingRules.Count) {
        $rObj = $script:loadedForwardingRules[$idx]
        $nl = [System.Environment]::NewLine
        $plat = if ($rObj.PSObject.Properties['Provider'] -and $rObj.Provider) { $rObj.Provider } else { $rObj.Platform }
        $rType = if ($rObj.PSObject.Properties['RuleType'] -and $rObj.RuleType) { $rObj.RuleType } else { "Rule" }
        $sumText = if ($rObj.PSObject.Properties['ActionDest'] -and $rObj.ActionDest) { $rObj.ActionDest } else { $rObj.Summary }
        $recAction = if ($rObj.Risk -like "*HIGH*" -or $rObj.Risk -like "*SUSPICIOUS*") {
            "RECOMMENDED: HIGH BEC EXFILTRATION / STEALTH RISK - Click 'Disable Rule' or 'Delete Rule' above immediately."
        } else {
            "RECOMMENDED: Review rule destination/criteria. You can Disable, Enable, or Delete this rule using the buttons above."
        }
        $txtRuleDecision.Text = "[$plat | $rType | State: $($rObj.State) | Risk: $($rObj.Risk)] $($rObj.RuleName) (ID: $($rObj.RuleId)) -> $sumText$nl$recAction"
    }
})

# Tab 3 Action Handlers (With Real-Time Shared Logging + Action Popups)
$btnBlockEntraSignIn.Add_Click({
    if ($null -eq $script:currentUser) { return }
    Write-AppLog "Blocking Microsoft Entra ID sign-in (accountEnabled = false) for '$($script:currentUser.UserPrincipalName)'..." "INFO"
    $form.Refresh()
    try {
        $res = Set-MgUserSignInEnabledSafe -UserObj $script:currentUser -BlockSignIn $true
        $script:currentUser.GraphTargetId = $res.MatchedUserId
        $lblCard365Val.Text = "Sign-In Blocked"
        $lblCard365Sub.Text = "Account Suspended / Disabled"
        Write-AppLog "SUCCESS: Blocked Microsoft Entra ID sign-in (accountEnabled = false) for '$($res.MatchedUserId)'." "SUCCESS"
        Add-AuditEntry "Block Entra Sign-In" "SUCCESS" $res.Details
        Show-ActionPopup -ActionTitle "Block Entra Sign-In" -Succeeded $true -Details $res.Details
    } catch {
        Write-AppLog "ERROR: Block Entra Sign-In failed: $($_.Exception.Message)" "ERROR"
        Add-AuditEntry "Block Entra Sign-In" "FAILED" $_.Exception.Message
        Show-ActionPopup -ActionTitle "Block Entra Sign-In" -Succeeded $false -Details $_.Exception.Message
    }
})

$btnUnblockEntraSignIn.Add_Click({
    if ($null -eq $script:currentUser) { return }
    Write-AppLog "Unblocking Microsoft Entra ID sign-in (accountEnabled = true) for '$($script:currentUser.UserPrincipalName)'..." "INFO"
    $form.Refresh()
    try {
        $res = Set-MgUserSignInEnabledSafe -UserObj $script:currentUser -BlockSignIn $false
        $script:currentUser.GraphTargetId = $res.MatchedUserId
        $lblCard365Val.Text = "Login Capable (Active)"
        $lblCard365Sub.Text = "Sign-In Enabled & Active"
        Write-AppLog "SUCCESS: Re-enabled Microsoft Entra ID sign-in (accountEnabled = true) for '$($res.MatchedUserId)'." "SUCCESS"
        Add-AuditEntry "Unblock Entra Sign-In" "SUCCESS" $res.Details
        Show-ActionPopup -ActionTitle "Unblock Entra Sign-In" -Succeeded $true -Details $res.Details
    } catch {
        Write-AppLog "ERROR: Unblock Entra Sign-In failed: $($_.Exception.Message)" "ERROR"
        Add-AuditEntry "Unblock Entra Sign-In" "FAILED" $_.Exception.Message
        Show-ActionPopup -ActionTitle "Unblock Entra Sign-In" -Succeeded $false -Details $_.Exception.Message
    }
})

