        $msg = "Pulled $($pulled.Count) security event(s) across Active Directory, Microsoft Entra ID, and Google Workspace for '$($script:currentUser.UserPrincipalName)'."
        Write-AppLog "SUCCESS: $msg" "SUCCESS"
        Add-AuditEntry "Pull Security Events" "SUCCESS" $msg
        Show-ActionPopup -ActionTitle "Pull Security Events" -Succeeded $true -Details $msg
    } catch {
        $errMsg = $_.Exception.Message
        $lblEventStats.Text = "Error pulling security events: $errMsg"
        Write-AppLog "ERROR pulling security events: $errMsg" "ERROR"
        Add-AuditEntry "Pull Security Events" "FAILED" $errMsg
        Show-ActionPopup -ActionTitle "Pull Security Events" -Succeeded $false -Details $errMsg
    }
})

